INSERT IGNORE INTO `templates_reseller` (`Id`, `reseller_id`, `template_name`, `html_content`, `header_id`, `footer_id`, `language_code`, `CreatedBy`, `ModifiedBy`, `CreatedAt`, `ModifiedAt`) VALUES (1, 197, 'FINALBILL_PRICE_CAP_DETAIL_EAN', '<table class=\"table_no_width table-custom mb-3\" style=\"width: 100%\">\r\n    <thead class=\"header-line\">\r\n        <th class=\"pl-2\"> [product_type] - EAN [EAN_number]</th>\r\n        <th class=\"pl-2\" style=\"width: 100px;\"></th>\r\n    </thead>\r\n    <tbody>\r\n        <tr>\r\n            <td class=\"pl-2\">\r\n                Totale verbruikskosten 2023 incl. btw\r\n            </td>\r\n            <td style=\"position: relative; text-align: right; white-space: nowrap;\" class=\"pr-2\">\r\n                [price_net_usage]\r\n            </td>\r\n        </tr>\r\n        <tr>\r\n            <td class=\"pl-2\">\r\n                Netto afgenomen verbruik 2023\r\n\r\n            </td>\r\n            <td style=\"position: relative; text-align: right; white-space: nowrap;\" class=\"pr-2\">\r\n                [net_usage] [product_unit]\r\n                <div style=\"position: absolute;\r\n                z-index: 1;\r\n                bottom: -15px;\r\n                left: -12px;\">÷</div>\r\n                <div style=\"    position: absolute;\r\n                   border-bottom: 1px solid;\r\n                   height: 1px;\r\n                   width: 98%;\r\n                   bottom: 0px;\">\r\n                 </div>\r\n            </td>\r\n        </tr>\r\n        <tr class=\"white-background\">\r\n            <td class=\"pl-2\">\r\n                Gewogen gemiddelde tarief\r\n            </td>\r\n            <td style=\"position: relative; text-align: right; white-space: nowrap;\" class=\"pr-2\">\r\n                [wa_price_cap_tariff]\r\n            </td>\r\n        </tr>\r\n        <tr>\r\n            <td class=\"pl-2\">\r\n                Plafondprijs (incl. btw, excl. EB)\r\n            </td>\r\n            <td style=\"position: relative; text-align: right; white-space: nowrap;\" class=\"pr-2\">\r\n                [price_cap_tariff]\r\n                <div style=\"position: absolute;\r\n                z-index: 1;\r\n                bottom: -15px;\r\n                left: -12px;\">-</div>\r\n                <div style=\"    position: absolute;\r\n                border-bottom: 1px solid;\r\n                height: 1px;\r\n                width: 98%;\r\n                bottom: 0px;\">\r\n                </div>\r\n\r\n            </td>\r\n        </tr>\r\n        <tr class=\"white-background\">\r\n            <td class=\"font-weight-bold pl-2\">\r\n                Tegemoetkoming per [product_unit]\r\n            </td>\r\n            <td class=\"font-weight-bold pr-2\" style=\"position: relative; text-align: right; white-space: nowrap;\">\r\n                [compensation_tariff]\r\n            </td>\r\n        </tr>\r\n    </tbody>\r\n</table>', NULL, NULL, 'nl', 'ke-pdf', NULL, '2023-11-27 09:07:13.152323', NULL);
INSERT IGNORE INTO `templates_reseller` (`Id`, `reseller_id`, `template_name`, `html_content`, `header_id`, `footer_id`, `language_code`, `CreatedBy`, `ModifiedBy`, `CreatedAt`, `ModifiedAt`) VALUES (8, 197, 'FINALBILL_PRICE_CAP_DETAIL_EAN_USAGE_TOTAL', '<table class=\"table table-custom mb-0 mt-4\"> \r\n    <thead>\r\n        <th class=\"pl-2 vertical-align-bottom\" style=\"width: 350px; max-width: 350px;\">TEGEMOETKOMING UIT HET PRIJSPLAFOND VOOR [product_type]<br/>\r\n            ([pricecap_ean_start_date] / [pricecap_ean_end_date]) - EAN [EAN_number]\r\n        </th>\r\n        <th class=\"pl-2 text-right\" style=\"vertical-align: bottom; width: 170px; max-width: 170px;\">\r\n              <span class=\"float-left\">AANTAL</span>\r\n              <span class=\"d-inline-block pr-4\">x</span>\r\n        </th>\r\n            \r\n        <th class=\"pl-2 text-right\" style=\"vertical-align: bottom;\">\r\n          <span class=\"float-left\">TARIEF</span>\r\n          <br>\r\n          <span class=\"float-left\">INCL. BTW</span>\r\n          <span class=\"d-inline-block pr-4\">=</span>\r\n        </th>   \r\n        <th class=\"pl-2 vertical-align-bottom text-right\">BEDRAG<br/>\r\n            INCL. BTW</th>\r\n\r\n    </thead>\r\n    <tbody>\r\n        <tr>\r\n            <td class=\"pl-2\">\r\n                Tegemoetkoming prijsplafond\r\n            </td>\r\n            <td class=\"pl-2\">\r\n                [price_cap_usage] [product_unit]\r\n            </td>\r\n            <td class=\"pl-2\">\r\n                [compensation_tariff]\r\n            </td>\r\n            <td class=\"text-right\">\r\n                [total_price_cap]\r\n            </td>\r\n        </tr>\r\n    </tbody>\r\n</table>', NULL, NULL, 'nl', 'ke-pdf', NULL, '2023-11-27 09:07:13.152323', NULL);
INSERT IGNORE INTO `templates_reseller` (`Id`, `reseller_id`, `template_name`, `html_content`, `header_id`, `footer_id`, `language_code`, `CreatedBy`, `ModifiedBy`, `CreatedAt`, `ModifiedAt`) VALUES (15, 197, 'FINALBILL_PRICE_CAP_SECTION', '<div style=\"page-break-before: always\" class=\"[show-price-cap-section]\"></div>\r\n<div class=\"page [show-price-cap-section]\">\r\n    <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n            <div class=\"row\">\r\n                <div class=\"col-12\">\r\n                    <p class=\"mb-1 font-weight-bold\">2. Prijsplafond</p>\r\n                    <p>Deze <span class=\"[final_bill_visible]\">eindafrekening</span>\r\n                        <span class=\"[yearly_bill_visible]\">jaarafrekening</span> heeft (mogelijk ten dele) betrekking op energielevering in 2023. In 2023\r\n                        geldt er een\r\n                        prijsplafond voor energie. Hieronder lees je wat dit voor jou betekent.</p>\r\n                </div>\r\n            </div>\r\n            <div class=\"mt-3\">\r\n                <p class=\"mb-1 font-weight-bold\">Hoe werkt het prijsplafond?</p>\r\n                <p>Met het prijsplafond betaal je een maximumtarief (de plafondprijs) voor stroom en gas, tot een\r\n                    maximale\r\n                    hoeveelheid energieverbruik (het volumeplafond). Je betaalt dan tot het volumeplafond de\r\n                    plafondprijs, ook al zijn\r\n                    jouw contracttarieven hoger. Verbruik je meer dan het volumeplafond? Dan betaal je voor het verbruik\r\n                    boven het\r\n                    plafond je contracttarieven. Zijn jouw contracttarieven lager dan de plafondprijs? Dan betaal je de\r\n                    lagere tarieven.</p>\r\n                <p>De plafondprijzen en het volumeplafond vind je in de onderstaande tabel:</p>\r\n                <table class=\"table table-custom mb-0\" style=\"width: 100%;\">\r\n                    <thead>\r\n                        <th class=\"pl-2 vertical-align-bottom\" style=\"width: 25%; min-width: 25%; max-width: 25%\">PRODUCT</th>\r\n                        <th class=\"pl-2 vertical-align-bottom\" style=\"width: 25%;\">VOLUMEPLAFOND</th>\r\n                        <th class=\"pl-2 vertical-align-bottom\" style=\"width: 25%;\">PLAFONDPRIJS<br>\r\n                            (INCL. BTW EN EB*)</th>\r\n                        <th class=\"pl-2 vertical-align-bottom\" style=\"width: 25%;\">PLAFONDPRIJS<br>\r\n                            (INCL. BTW, EXCL. EB*)</th>\r\n                    </thead>\r\n                    <tbody>\r\n                        <tr>\r\n                            <td style=\"width: 25%; min-width: 25%; max-width: 25%;\">\r\n                                Stroom\r\n                            </td>\r\n                            <td style=\"width: 25%;\">\r\n                                [price_cap_volume_elk] kWh\r\n                            </td>\r\n                            <td style=\"width: 25%;\">\r\n                                [price_cap_with_eb_elk]\r\n                            </td>\r\n                            <td style=\"width: 25%;\">\r\n                                [price_cap_without_eb_elk]\r\n                            </td>\r\n                        </tr>\r\n                        <tr>\r\n                            <td style=\"width: 25%; min-width: 25%; max-width: 25%;\">\r\n                                Gas\r\n                            </td>\r\n                            <td>\r\n                                [price_cap_volume_gas] m<sup>3</sup>\r\n                            </td>\r\n                            <td>\r\n                                [price_cap_with_eb_gas]\r\n                            </td>\r\n                            <td>\r\n                                [price_cap_without_eb_gas]\r\n                            </td>\r\n                        </tr>\r\n                    </tbody>\r\n                </table>\r\n                <span class=\"note\">* Energiebelasting</span>\r\n\r\n                <p class=\"mb-1 mt-3 font-weight-bold\">Volumeplafond in 2023</p>\r\n                <p>Omdat je in de winter meer verbruikt dan in de zomer, is het volumeplafond in de wintermaanden hoger\r\n                    dan in\r\n                    de zomermaanden. Wij zijn daarom verplicht om het volumeplafond uit te rekenen voor de periode in je\r\n                    <span class=\"[final_bill_visible]\">eindafrekening</span>\r\n                        <span class=\"[yearly_bill_visible]\">jaarafrekening</span> die betrekking heeft op 2023. Voor jou is dit volumeplafond in de periode\r\n                    [price_cap_period_start_date] tot [price_cap_period_end_date]:</p>\r\n                <table>\r\n                    <tbody>\r\n                        <tr>\r\n                            <tr>\r\n                            <td class=\"[show_fraction_based_volume_elk]\">Stroom:</td>\r\n                            <td class=\"[show_fraction_based_volume_elk]\" style=\"width: 10px;\" > </td>\r\n                            <td class=\"[show_fraction_based_volume_elk]\">[price_cap_fraction_based_volume_elk] kWh</td>\r\n                            <td class=\"[show_fraction_based_volume_elk]\" style=\"width: 30px;\"> </td>\r\n                            <td class=\"[show_fraction_based_volume_gas]\">Gas:</td>\r\n                            <td class=\"[show_fraction_based_volume_gas]\" style=\"width: 10px;\"> </td>\r\n                            <td class=\"[show_fraction_based_volume_gas]\">[price_cap_fraction_based_volume_gas] m<sup>3</sup>\r\n                            </td>\r\n                        </tr>\r\n                        </tr>\r\n                    </tbody>\r\n                </table>\r\n                <p class=\"mt-3\">Heb je zonnepanelen? Dan trekken we eerst de teruggeleverde stroom af van jouw verbruik.\r\n                    Dit heet salderen.</p>\r\n                <p>Het verschil – jouw netto afgenomen verbruik – vergelijken we dan met jouw volumeplafond.</p>\r\n\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div style=\"page-break-before: always\"></div>\r\n<div class=\"page\">\r\n    <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n            <div class=\"row\">\r\n                <div class=\"col-12\">\r\n                    <p class=\"mb-1 font-weight-bold\">Gemiddelde tarief</p>\r\n                    <p>Jouw <span class=\"[final_bill_visible]\">eindafrekening</span>\r\n                        <span class=\"[yearly_bill_visible]\">jaarafrekening</span> kan meerdere tarieven bevatten. Denk\r\n                        aan aparte normaal- en daltarieven, of\r\n                        fluctuerende tarieven per maand. We moeten daarom van de overheid jouw volume-gewogen gemiddelde\r\n                        tarief in\r\n                        2023 uitrekenen. Vervolgens vergelijken we dit tarief met de plafondprijs. Het verschil\r\n                        daartussen krijg je tot het\r\n                        verbruiksplafond vergoed van de overheid. Jouw volume-gewogen gemiddelde tarief in 2023 was:\r\n                    </p>\r\n                    <div class=\"row\">\r\n                        <div class=\"[show_price_cap_usage_elk] col-6\" style=\"display: flex; flex-direction: column;\">\r\n                            [pricecap_detail_elk_eans]\r\n                        </div>\r\n         \r\n                        <div class=\"[show_price_cap_usage_gas] col-6\" style=\"display: flex; flex-direction: column;\">\r\n                            [pricecap_detail_gas_eans]\r\n                        </div>\r\n                    </div>\r\n                    <p class=\"mb-1 mt-3 font-weight-bold\">Jouw voordeel</p>\r\n                    <p>De tegemoetkoming uit het prijsplafond wordt berekend door het verschil tussen het volume-gewogen\r\n                        gemiddelde\r\n                        tarief en de plafondprijs te vermenigvuldigen met het volumeplafond. Onderstaand zie je welk\r\n                        voordeel dit voor jou\r\n                        oplevert. Dit voordeel geldt als een korting op jouw energiekosten.</p>\r\n\r\n                    <p class=\"[show_message_price_cap_compensation_elk]\">Voor stroom ontvang je geen tegemoetkoming uit het prijsplafond. Dit komt omdat het gemiddelde tarief gelijk of lager was dan de plafondprijs, of omdat jouw netto verbruik in 2023 gelijk of lager was dan 0.</p>\r\n                    <p class=\"[show_message_price_cap_compensation_gas]\">Voor gas ontvang je geen tegemoetkoming uit het prijsplafond. Dit komt omdat het gemiddelde tarief gelijk of lager was dan de plafondprijs, of omdat jouw netto verbruik in 2023 gelijk of lager was dan 0.</p>\r\n                    <p class=\"[show_message_price_cap_compensation_both]\">Voor stroom en gas ontvang je geen tegemoetkoming uit het prijsplafond. Dit komt omdat het gemiddelde tarief gelijk of lager was dan de plafondprijs, of omdat jouw netto verbruik in 2023 gelijk of lager was dan 0.</p>\r\n                    [price_cap_ean_details]\r\n\r\n                    <table class=\"[show_price_cap_ean_detail_total]\">\r\n                        <tbody>\r\n                            <tr>\r\n                                <td style=\"height: 15px;\"></td>\r\n                            </tr>\r\n                            <tr>\r\n                                <td class=\"w-100\"></td>\r\n                                <td class=\"pl-2 text-right font-weight-bold text-nowrap t-nowrap mt-3\">\r\n                                    <div class=\"border-top-bold position-relative\">\r\n                                        <span class=\"pr-5\"> Totaal tegemoetkoming prijsplafond incl. btw*</span>\r\n                                        <span>[total_price_cap]</span>\r\n                                    </div>\r\n                                </td>\r\n                            </tr>\r\n                        </tbody>\r\n                    </table>\r\n\r\n                    <p class=\"mt-3\">* De tegemoetkoming wordt uitgekeerd als onbelaste kortingsregel op de <span\r\n                            class=\"[final_bill_visible]\">eindafrekening.</span>\r\n                        <span class=\"[yearly_bill_visible]\">jaarafrekening.</span>\r\n                    </p>\r\n                    <p>Kijk voor meer informatie over het prijsplafond op <a style=\"text-decoration: none;\" href=\"https://www.rijksoverheid.nl/onderwerpen/koopkracht/plannen-kabinet-met-prijsplafond-voor-gas-en-elektriciteit\">de\r\n                            website</a> van de Rijksoverheid.</p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>', NULL, NULL, 'nl', 'ke-pdf', NULL, '2023-11-27 09:07:13.152323', NULL);
INSERT IGNORE INTO `templates_reseller` (`Id`, `reseller_id`, `template_name`, `html_content`, `header_id`, `footer_id`, `language_code`, `CreatedBy`, `ModifiedBy`, `CreatedAt`, `ModifiedAt`) VALUES (22, 197, 'FINALBILL_TEMPLATE', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n\r\n<head>\r\n  <title>Billing | Kikker</title>\r\n  <meta charset=\"utf-8\">\r\n  <link rel=\"icon\" href=\"asset/kikker-icon.ico\" />\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\r\n  <link rel=\"stylesheet\" href=\"https://storage.googleapis.com/kikkerprodbucket/static-files/pdf-css/site.css\">\r\n  <link rel=\"stylesheet\" href=\"https://storage.googleapis.com/kikkerprodbucket/static-files/pdf-css/final_bill.css\">\r\n</head>\r\n\r\n<style>\r\n  .table-fixed-v thead th,\r\n  .table-fixed-v tbody tr td {\r\n    /* color: #6d6d6d; */\r\n    min-width: 110px;\r\n  }\r\n\r\n  .table-fixed-v thead th:last-child,\r\n  .table-fixed-v tbody tr td:last-child {\r\n    /* color: #6d6d6d; */\r\n    min-width: 50px;\r\n  }\r\n\r\n  .table_fixed_delivery .table-fixed-v thead th:nth-child(1),\r\n  .table_fixed_delivery .table-fixed-v tbody tr td:nth-child(1),\r\n  .table-usage thead th:nth-child(1),\r\n  .table-usage tbody tr td:nth-child(1) {\r\n    /* color: #6d6d6d; */\r\n    min-width: 250px;\r\n    max-width: 250px;\r\n    width: 250px;\r\n  }\r\n\r\n  .table_fixed_delivery .table-fixed-v thead th:nth-child(1) {\r\n    padding-right: 55px;\r\n  }\r\n\r\n  .table-fixed-v thead th:nth-child(2),\r\n  .table-fixed-v tbody tr td:nth-child(2) {\r\n    min-width: 180px;\r\n  }\r\n</style>\r\n\r\n<body>\r\n  <div class=\"page\">\r\n    <div class=\"container text-normal\">\r\n      <div class=\"content\">\r\n        <div class=\"row\">\r\n          <div class=\"col-12\">\r\n            <p class=\"mb-0\"></span>[customer_full_name]<br>[billing_address_street] [billing_address_houseNr]<br>\r\n                [billing_address_zipcode] [billing_address_city]\r\n                <span class=\"float-right\">[date_generate_PDF]</span>\r\n              </p>\r\n            <p class=\"mt-5 mb-0\">Beste [customer_first_name],</p>\r\n            <br>\r\n            <p class=\"mb-4 [final_bill_visible]\">Dit is je eindafrekening over de verbruiksperiode van\r\n              [final_bill_start_date] tot [final_bill_end_date] voor je\r\n              leveringsadres [delivery_address_street] [delivery_address_houseNr] te [delivery_address_city]. Je\r\n              ontvangt deze afrekening omdat je contract met Kikker\r\n              Energie eindigt. In deze eindafrekening berekenen we de kosten tot de einddatum van je contract. Indien je\r\n              onlangs\r\n              een nieuw Kikker Energie-contract hebt afgesloten, ontvang je hier apart bericht van.\r\n            </p>\r\n\r\n            <p class=\"mb-4 [yearly_bill_visible]\">Dit is je jaarafrekening over de verbruiksperiode van\r\n              [final_bill_start_date] tot [final_bill_end_date] voor je leveringsadres [delivery_address_street] te\r\n              [delivery_address_city]. In deze jaarafrekening vind je een overzicht van je energieverbruik in het\r\n              afgelopen\r\n              jaar en wat je hiervoor hebt betaald.\r\n            </p>\r\n            <p>\r\n              Alle bedragen die vermeld staan in deze afrekening zijn inclusief [vat]% btw. Meer informatie over je\r\n              verbruik of de\r\n              precieze berekening van je <span class=\"[final_bill_visible]\">eindafrekening</span><span\r\n                class=\"[yearly_bill_visible]\">jaarafrekening</span> vind je op de volgende pagina’s.\r\n            </p>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"mt-5\">\r\n          <table class=\"table\">\r\n            <tbody>\r\n              <tr>\r\n                <td class=\"pl-2\">\r\n                  In rekening gebrachte termijnbedragen\r\n                </td>\r\n                <td class=\"pl-2 text-right\">€ [total_generated_amount]</td>\r\n              </tr>\r\n              <tr class=\"[show_price_cap_billing]\">\r\n                <td class=\"pl-2\"> Tegemoetkoming uit het prijsplafond </td>\r\n                <td class=\"pl-2 text-right\">[total_price_cap]</td>\r\n              </tr>\r\n              <tr>\r\n                <td class=\"pl-2\">\r\n                  Totale kosten over deze eindnota\r\n                </td>\r\n                <td class=\"pl-2 text-right\">[total_real_amount]</td>\r\n              </tr>\r\n              <tr>\r\n                <td class=\"pl-2 font-weight-bold\">\r\n                  [is_receive]\r\n                </td>\r\n                <td class=\"pl-2 text-right  font-weight-bold\">€ [difference_amount]</td>\r\n              </tr>\r\n            </tbody>\r\n          </table>\r\n        </div>\r\n\r\n        <div class=\"mt-3\">\r\n          <p class=\"mb-1 font-weight-bold\">\r\n            De termijnbedragen op je <span class=\"[final_bill_visible]\">eindafrekening</span><span\r\n              class=\"[yearly_bill_visible]\">jaarafrekening</span>\r\n          </p>\r\n          <p class=\"mb-4\">\r\n            Op deze <span class=\"[final_bill_visible]\">eindafrekening</span><span\r\n              class=\"[yearly_bill_visible]\">jaarafrekening</span> verrekenen we alle termijnbedragen die we tot nu toe\r\n            hebben gefactureerd. Indien je één of\r\n            meerdere termijnfacturen nog niet hebt betaald, moet je dit alsnog doen. Je kunt al je termijnfacturen\r\n            vinden in de\r\n            Kikker app.\r\n          </p>\r\n        </div>\r\n        \r\n        <div class=\"mt-3\">\r\n          <p class=\"mb-1 font-weight-bold [yearly_bill_visible] [new_monthly_amount_visible]\">\r\n            Je nieuwe termijnbedrag</span>\r\n          </p>\r\n          <p class=\"mb-4 [yearly_bill_visible] [new_monthly_amount_visible]\">\r\n            Op basis van je verbruik in de afgelopen 12 maanden, hebben we een nieuw termijnbedrag voor je uitgerekend.\r\n            We passen het termijnbedrag automatisch voor je aan. Ben je het niet eens met je nieuwe termijnbedrag? Dan\r\n            kun je dit gemakkelijk aanpassen in onze mobiele app.\r\n          </p>\r\n        </div>\r\n\r\n        <div class=\"row monthly-amount-block [yearly_bill_visible] [new_monthly_amount_visible] mt-3\"\r\n          style=\"background-image: url(\'data:image/png;base64,\');background-size: 100%; background-repeat: no-repeat; background-position: center center;\">\r\n          <div class=\"col-6\">\r\n            <span>\r\n              Oude termijnbedrag\r\n            </span>\r\n            <span class=\"float-right\">\r\n              € [current_monthly_amount]\r\n            </span>\r\n          </div>\r\n\r\n          <div class=\"col-6 pl-5 font-weight-bold\">\r\n            <span>\r\n              Nieuwe termijnbedrag\r\n            </span>\r\n            <span class=\"float-right\">\r\n              € [new_monthly_amount]\r\n            </span>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"mt-3 avoid-break-page\">\r\n          <p class=\"font-weight-bold mb-1\">Vragen?</p>\r\n          <p class=\"mb-3\" style=\"text-align: left;\">Neem contact op met jouw wederverkoper [reseller_name]. Dit kun je doen via e-mail op <a style=\"color: #4a90e2\"\r\n              href=\"mailto:[reseller_email]\">[reseller_email]</a> of telefonisch op [reseller_phone]. Ook kun je Kikker\r\n            Energie zelf bereiken op <a href=\"mailto:servicedesk@kikker.nl\">servicedesk@kikker.nl</a> of 020 - 29 94\r\n            200.</p>\r\n          <p class=\"mb-3\">Met vriendelijke groet, </p>\r\n          <p class=\"mb-0\">Kikker Energie</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div style=\"page-break-before: always\">&nbsp;</div>\r\n\r\n  <div class=\"page\">\r\n    <div class=\"container text-normal\">\r\n      <div class=\"content\">\r\n        <div class=\"row\">\r\n          <div class=\"col-12\">\r\n            <p>Meer informatie over je verbruik of de precieze berekening van je <span class=\"[final_bill_visible]\">eindafrekening</span><span\r\n                class=\"[yearly_bill_visible]\">jaarafrekening</span> vind je op de volgende pagina’s.</p>\r\n            <p class=\"mb-1 font-weight-bold\">Samenvatting van je <span\r\n                class=\"[final_bill_visible]\">eindafrekening</span><span\r\n                class=\"[yearly_bill_visible]\">jaarafrekening</span></p>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"mt-5\">\r\n          <table class=\"table table-first\">\r\n            <tbody>\r\n              <tr>\r\n                <td class=\"pl-2\">\r\n                  1. In rekening gebrachte termijnbedragen\r\n                </td>\r\n                <td class=\"pl-2 text-right\">€ [total_generated_amount]</td>\r\n              </tr>\r\n              <tr>\r\n                <td class=\"pl-2 font-weight-bold\">\r\n                </td>\r\n                <td class=\"pl-2 text-right  font-weight-bold\">€ [total_generated_amount]</td>\r\n              </tr>\r\n            </tbody>\r\n          </table>\r\n        </div>\r\n\r\n        <div class=\"mt-4\">\r\n          <table class=\"table table-first\">\r\n            <tbody>\r\n              <tr>\r\n                <td class=\"pl-2\">\r\n                  2. Leveringskosten van [product_type]\r\n                </td>\r\n                <td class=\"pl-2 text-right\">[total_delivery_amount]</td>\r\n              </tr>\r\n              <tr class=\"[show_price_cap_billing]\">\r\n                <td class=\"pl-2\"> 3. Tegemoetkoming uit het prijsplafond</td>\r\n                <td class=\"pl-2 text-right\">[total_price_cap]</td>\r\n              </tr>\r\n              <tr>\r\n                <td class=\"pl-2 [hide_price_cap_billing]\">3. Overheidsheffingen op [product_type], dit dragen we af aan de overheid</td>\r\n                  <td class=\"pl-2 [show_price_cap_billing]\">4. Overheidsheffingen op [product_type], dit dragen we af aan de overheid</td>\r\n                <td class=\"pl-2 text-right\">[total_tax_amount]</td>\r\n              </tr>\r\n              <tr>\r\n                <td class=\"pl-2 [hide_price_cap_billing]\">4. Netbeheerkosten op [product_type], dit dragen we af aan je netbeheerder</td>\r\n                <td class=\"pl-2 [show_price_cap_billing]\">5. Netbeheerkosten op [product_type], dit dragen we af aan je netbeheerder</td>\r\n                <td class=\"pl-2 text-right\">[total_grid_operator_amount]</td>\r\n              </tr>\r\n              <tr>\r\n                <td class=\"pl-2 font-weight-bold\">\r\n                </td>\r\n                <td class=\"pl-2 text-right  font-weight-bold\">[total_real_amount_incl_cancel_fee]</td>\r\n              </tr>\r\n            </tbody>\r\n          </table>\r\n          <div class=\"mt-2 pt-4 position-relative text-right font-weight-bold elk-gas-total btw-total\">\r\n            <span class=\"w-200 nowrap\">[is_receive]</span>\r\n            <span>€ [difference_amount]</span>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div style=\"page-break-before: always\">&nbsp;</div>\r\n\r\n  <div class=\"page\">\r\n    <div class=\"container text-normal\">\r\n      <div class=\"content\">\r\n        <div class=\"[usage_only_gas_elk_visible]\">\r\n          <p class=\"mb-1 font-weight-bold\">\r\n            Berekening van je verbruik\r\n          </p>\r\n          <p class=\"mb-5\">\r\n            Op basis van je meterstanden bepalen wij hoeveel energie je hebt verbruikt. De meterstanden lezen wij uit\r\n            via je\r\n            slimme meter, vragen wij bij je op via de Kikker app of berekenen we zelf. Onderstaand vind je een overzicht\r\n            van je\r\n            verbruik per periode. Omdat tussen periodes soms verschillende tarieven gelden, kan het zijn dat je\r\n            verschillende\r\n            periodes ziet.\r\n          </p>\r\n        </div>\r\n\r\n        <div class=\"table-usage [usage_only_gas_elk_visible]\">\r\n          [usage_item_by_ean]\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"[usage_only_gas_elk_visible]\" style=\"page-break-before: always\">&nbsp;</div>\r\n\r\n  <div class=\"page [usage_both_gas_elk_visible]\">\r\n    <div class=\"container text-normal\">\r\n      <div class=\"content\">\r\n        <div>\r\n          <p class=\"mb-1 font-weight-bold\">\r\n            Berekening van je verbruik\r\n          </p>\r\n          <p class=\"mb-5\">\r\n            Op basis van je meterstanden bepalen wij hoeveel energie je hebt verbruikt. De meterstanden lezen wij uit\r\n            via je\r\n            slimme meter, vragen wij bij je op via de Kikker app of berekenen we zelf. Onderstaand vind je een overzicht\r\n            van je\r\n            verbruik per periode. Omdat tussen periodes soms verschillende tarieven gelden, kan het zijn dat je\r\n            verschillende\r\n            periodes ziet.\r\n          </p>\r\n        </div>\r\n\r\n        <div class=\"table-usage\">\r\n          [usage_item_by_ean]\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"[usage_both_gas_elk_visible]\" style=\"page-break-before: always\">&nbsp;</div>\r\n\r\n  <div class=\"page\">\r\n    <div class=\"container text-normal\">\r\n      <div class=\"content\">\r\n        <div>\r\n          <p class=\"mb-4\">Op de volgende pagina’s vind je een nadere specificatie van de kosten die weergegeven zijn op\r\n            pagina 2.</p>\r\n          [return_tariff_section]\r\n          <p class=\"mb-1 font-weight-bold\">1. Leveringskosten voor [product_type]</p>\r\n          <p class=\"mb-5\">\r\n            Onderstaand vind je een specificatie van je leveringskosten voor [product_type]. Door je verbruik te\r\n            vermenigvuldigen\r\n            met je tarief bepalen we je kosten per contract.\r\n          </p>\r\n        </div>\r\n\r\n        <div class=\"table_fixed_delivery\">\r\n          [fixed_delivery_item]\r\n        </div>\r\n\r\n        <div class=\"mt-3 [fixed_delivery_item_first_page_visible]\">\r\n\r\n          <div class=\"mt-2 pt-4 position-relative text-right font-weight-bold elk-gas-total btw-total\">\r\n            <span class=\"w-200 nowrap\">Totaalbedrag voor leveringskosten voor [product_type]</span>\r\n            <span>€ [fixed_delivery_total]</span>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div style=\"page-break-before: always\">&nbsp;</div>\r\n\r\n  [fixed_delivery_item_dynamic_page]\r\n\r\n  [price_cap_section_template]\r\n\r\n  <div class=\"page\">\r\n    <div class=\"container text-normal\">\r\n      <div class=\"content\">\r\n        <div class=\"row\">\r\n          <div class=\"col-12\">\r\n           <p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">2. Overheidsheffingen op [product_type]</p>\r\n            <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">3. Overheidsheffingen op [product_type]</p>\r\n            <p style=\"display: [show_new_ode_tax_description]\">Naast de kosten voor het verbruik van [product_type],\r\n              moet je ook belastingen betalen aan de overheid. Ook deze zijn afhankelijk van je verbruik. Onderstaande\r\n              kosten dragen wij direct af aan de overheid. Omdat de heffingen jaarlijks (per 1 januari) veranderen zie\r\n              je onderstaand mogelijk twee berekeningen: een voor de periode vóór en een voor de periode ná 1 januari.\r\n            </p>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"mt-5 custom-table table_tax\">\r\n          [tax_item]\r\n        </div>\r\n        <div class=\"mt-3 [tax_item_first_page_visible]\">\r\n          <div class=\"mt-2 pt-4 position-relative text-right font-weight-bold elk-gas-total btw-total\">\r\n            <span class=\"w-200 nowrap\">Totaalbedrag voor overheidsheffingen op [product_type]</span>\r\n            <span>[tax_item_total]</span>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div style=\"page-break-before: always\">&nbsp;</div>\r\n\r\n  [tax_item_dynamic_page]\r\n\r\n  <div class=\"page\">\r\n    <div class=\"container text-normal\">\r\n      <div class=\"content\">\r\n        <div class=\"row\">\r\n          <div class=\"col-12\">\r\n            <p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">3. Netbeheerkosten voor [product_type]</p>\r\n            <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">4. Netbeheerkosten voor [product_type]</p>\r\n            <p class=\"mb-3\">Om van [product_type] gebruik te kunnen maken, dien je aangesloten te zijn op het openbare\r\n              [product_type]netwerk\r\n              van je netbeheerder. Hiervoor betaal je een vaste vergoeding die afhankelijk is van je aansluiting. Wij\r\n              dragen deze\r\n              vervolgens weer af aan je netbeheerder. Ook hier geldt dat de tarieven jaarlijks per 1 januari wijzigen.\r\n              Om deze reden\r\n              zie je onderstaand mogelijk weer twee berekeningen: voor de periode vóór en de periode ná 1 januari.\r\n            </p>\r\n            <p>\r\n              Je netbeheerder: <strong>[grid_operator_name]</strong>\r\n            </p>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"mt-5 custom-table table_grid_operator\">\r\n          [grid_operator_item]\r\n\r\n        </div>\r\n        <div class=\"mt-3 [grid_operator_item_first_page_visible]\">\r\n          <div class=\"mt-2 pt-4 position-relative text-right font-weight-bold elk-gas-total btw-total\">\r\n            <span class=\"w-200 nowrap\">Totaalbedrag voor netbeheerkosten op [product_type]</span>\r\n            <span>[grid_operator_total]</span>\r\n          </div>\r\n        </div>\r\n\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div style=\"page-break-before: always\">&nbsp;</div>\r\n\r\n  <div class=\"page\">\r\n    <div class=\"container text-normal\">\r\n      <div class=\"content\">\r\n        <div class=\"row\">\r\n          <div class=\"col-12\">\r\n          	<p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">4. Totaal in rekening gebrachte termijnbedragen</p>\r\n            <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">5. Totaal in rekening gebrachte termijnbedragen</p>\r\n            <p>Hier zie je een overzicht van de door ons in rekening gebrachte termijnbedragen in de afgelopen periode (incl. btw). Een negatief termijnbedrag wordt als niet in rekening gebracht beschouwd en daarom als 0 weergegeven.\r\n            </p>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"mt-5\">\r\n          <table class=\"table table-custom\">\r\n            <thead>\r\n              <th class=\"pl-2\">MAAND</th>\r\n              <th class=\"pl-2 text-right\">BEDRAG</th>\r\n            </thead>\r\n            <tbody>\r\n              [charged_item_by_month]\r\n            </tbody>\r\n          </table>\r\n          <div class=\"mt-2 pt-4 position-relative text-right font-weight-bold elk-gas-total btw-total\">\r\n            <span class=\"w-200 nowrap\">Totaal in rekening gebrachte termijnbedragen</span>\r\n            <span>€ [total_generated_amount]</span>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div style=\"page-break-before: always\">&nbsp;</div>\r\n\r\n  [grid_operator_item_dynamic_page]\r\n\r\n  <div class=\"page\">\r\n    <div class=\"container text-normal\">\r\n      <div class=\"content\">\r\n        <div>\r\n          <p class=\"font-weight-bold\">Jouw EAN-codes</p>\r\n          [elk_gas_eans]\r\n        </div>\r\n\r\n        <div class=\"mt-5\">\r\n          <p class=\"font-weight-bold\">Btw-aangifte</p>\r\n          <p class=\"mb-0\">\r\n            [reseller_name] handelt onder de leveranciersvergunning van Kikker Energie. In het geval je een btw-aangifte\r\n            moet doen, dien je daarom de gegevens van Kikker Energie te gebruiken. De benodigde informatie van Kikker\r\n            Energie en je netbeheerder vind je onderstaand:\r\n          </p>\r\n        </div>\r\n\r\n        <div class=\"row mt-4\">\r\n          <div class=\"col-5\">\r\n            <p class=\"mb-0\">\r\n              Kikker Energie B.V.</br>\r\n              Tolnasingel 12 </br> 2411PV Bodegraven\r\n            </p>\r\n            <p class=\"mb-0\">KvK: 71246681</p>\r\n            <p class=\"mb-0\">Btw nr.: NL858635732B01</p>\r\n          </div>\r\n          <div class=\"col-5\">\r\n            <p class=\"mb-0\">\r\n              [grid_operator_name]</br>\r\n              [grid_operator_house_nr]</br>\r\n              [grid_operator_postcode]\r\n            </p>\r\n            <p class=\"mb-0\">KvK: [grid_operator_kvk]</p>\r\n            <p class=\"mb-0\">Btw nr.: [grid_operator_btw]</p>\r\n          </div>\r\n\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n</body>\r\n\r\n</html>', NULL, NULL, 'nl', 'ke-pdf', NULL, '2023-11-27 09:07:13.152323', NULL);
INSERT IGNORE INTO `templates_reseller` (`Id`, `reseller_id`, `template_name`, `html_content`, `header_id`, `footer_id`, `language_code`, `CreatedBy`, `ModifiedBy`, `CreatedAt`, `ModifiedAt`) VALUES (29, 197, 'FINALBILL_TEMPLATE_AL_NUMBER', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n\r\n<head>\r\n    <title>Billing | Kikker</title>\r\n    <meta charset=\"utf-8\">\r\n    <link rel=\"icon\" href=\"asset/kikker-icon.ico\" />\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\r\n    <link rel=\"stylesheet\" href=\"https://storage.googleapis.com/kikkerprodbucket/static-files/pdf-css/site.css\">\r\n    <link rel=\"stylesheet\" href=\"https://storage.googleapis.com/kikkerprodbucket/static-files/pdf-css/final_bill.css\">\r\n</head>\r\n\r\n<body>\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div class=\"row header mr-0 ml-0\">\r\n                    <div style=\"width: 33%;\">\r\n                    </div>\r\n                    <div class=\"[hide-header-invoice-info] header-invoice-info\">\r\n                        <div class=\"d-flex justify-content-end\">\r\n                            <div class=\"space-span d-inline-block\" style=\"padding-top: 0\">\r\n                                <div class=\"mb-0 d-flex\">\r\n                                    <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\">Klantnummer:</p>\r\n                                    <p class=\"mb-0\">[client_number]</p>\r\n                                </div>\r\n                                <div class=\"mb-0 d-flex\">\r\n                                    <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\"\r\n                                        >Contractnummer:\r\n                                    </p>\r\n                                    <p class=\"mb-0\">[contract_number]</p>\r\n                                </div>\r\n                                <div class=\"mb-0 d-flex [hidden_contract_reference]\" style=\"flex-flow: row;\">\r\n                                    <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\">Contractreferentie: </p>\r\n                                    <p class=\"mb-0\">[contract_reference]</p>\r\n                                </div>\r\n                                <div class=\"mb-0 d-flex\">\r\n                                    <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\"\r\n                                        >Factuurnummer:\r\n                                    </p>\r\n                                    <p class=\"mb-0\">[invoice_number]</p>\r\n                                </div>\r\n                                <div class=\"mb-0 d-flex [company_name_visible]\" style=\"flex-flow: row;\">\r\n                                    <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\">Bedrijfsnaam: </p>\r\n                                    <p class=\"mb-0\">[company_name]</p>\r\n                                </div>\r\n                                <div class=\"mb-0 d-flex\" style=\"flex-flow: row;\">\r\n                                    <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\">Energie intermediair: </p>\r\n                                    <p class=\"mb-0\">[header_reseller_name]</p>\r\n                                </div>\r\n                                <div class=\"mb-0 d-flex\">\r\n                                    <p class=\"text-right vertical-align-top pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\"\r\n                                        >Leveringsadres:</p\r\n                                    >\r\n                                    <p class=\"mb-0\" class=\"d-inline-block\"\r\n                                        >[delivery_address_street] [delivery_address_houseNr] [delivery_address_zipcode]<br><span class=\"text-capitalize\">[delivery_address_city]</span></p\r\n                                    >\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n                <div class=\"row\">\r\n                    <div class=\"col-12\">\r\n                        <p class=\"mb-5\">\r\n                            <span class=\"float-right\">[date_generate_PDF]</span>\r\n                        </p>\r\n                        <p class=\"mb-4\">Beste [customer_first_name],</p>\r\n                        <p class=\"mb-4 [final_bill_visible]\">Dit is je eindafrekening over de verbruiksperiode van\r\n                            [final_bill_start_date] tot [final_bill_end_date] voor je leveringsadres\r\n                            [delivery_address_street] [delivery_address_houseNr] te <span\r\n                                class=\"text-capitalize\">[delivery_address_city]</span>. Je ontvangt deze afrekening\r\n                            omdat je contract met [reseller_name] eindigt. In deze eindafrekening berekenen we de kosten\r\n                            tot de einddatum van je contract. Indien je onlangs een nieuw [reseller_name]-contract hebt\r\n                            afgesloten, ontvang je hier apart bericht van. </p>\r\n                        <p class=\"mb-4 [yearly_bill_visible]\">Dit is je jaarafrekening over de verbruiksperiode van\r\n                            [final_bill_start_date] tot [final_bill_end_date] voor je leveringsadres\r\n                            [delivery_address_street] [delivery_address_houseNr] te <span\r\n                                class=\"text-capitalize\">[delivery_address_city]</span>. In deze jaarafrekening vind je\r\n                            een overzicht van je energieverbruik in het afgelopen jaar en wat je hiervoor hebt betaald.\r\n                        </p>\r\n                    </div>\r\n                </div>\r\n                [FINALBILL_TEMPLATE_UNPAID_AMOUNT_INVOICE_ITEM]\r\n                [FINALBILL_TEMPLATE_PAID_AMOUNT_INVOICE_ITEM]\r\n                <div>\r\n                    <p class=\"mb-1 font-weight-bold [yearly_bill_visible] [new_monthly_amount_visible]\"> Je nieuwe\r\n                        termijnbedrag </span>\r\n                    </p>\r\n                    <p class=\"mb-4 [yearly_bill_visible] [new_monthly_amount_visible]\"> Op basis van je verbruik in de\r\n                        afgelopen 12 maanden, hebben we een nieuw termijnbedrag voor je uitgerekend. We passen het\r\n                        termijnbedrag automatisch voor je aan. Ben je het niet eens met je nieuwe termijnbedrag? Dan kun\r\n                        je dit gemakkelijk aanpassen in onze mobiele app. </p>\r\n                </div>\r\n                <div class=\"row monthly-amount-block [yearly_bill_visible] [new_monthly_amount_visible] mt-4\"\r\n                    style=\"background-image: url(\'data:image/png;base64,\');background-size: 100%; background-repeat: no-repeat; background-position: center center;\">\r\n                    <div class=\"col-6\">\r\n                        <span> Oude termijnbedrag </span>\r\n                        <span class=\"float-right\"> € [current_monthly_amount] </span>\r\n                    </div>\r\n                    <div class=\"col-6 pl-5 font-weight-bold\">\r\n                        <span> Nieuwe termijnbedrag </span>\r\n                        <span class=\"float-right\"> € [new_monthly_amount] </span>\r\n                    </div>\r\n                </div>\r\n                <div class=\"mt-4 avoid-break-page\">\r\n                    <p class=\"font-weight-bold mb-1\">Vragen?</p>\r\n                    <p class=\"mb-3\" style=\"text-align: left;\">Je kunt altijd contact met ons opnemen via [reseller_email] of bellen naar\r\n                        [reseller_phone]</p>\r\n                    <p class=\"mb-3\">Met vriendelijke groet, </p>\r\n                    <p class=\"mb-0\">[reseller_name]</p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n            <div>\r\n                <p>Meer informatie over je verbruik of de precieze berekening van je <span class=\"[final_bill_visible]\">eindafrekening</span> <span class=\"[yearly_bill_visible]\">jaarafrekening</span> vind je op de volgende pagina’s.</p>\r\n                <div class=\"mb-1 font-weight-bold\">Samenvatting van je <span\r\n                        class=\"[final_bill_visible]\">eindafrekening</span>\r\n                    <span class=\"[yearly_bill_visible]\">jaarafrekening</span>\r\n                </div>\r\n                <div class=\"[hide_text_summary]\">[text_summary]</div>\r\n                <div class=\"mt-5\">\r\n                    <table class=\"table table-first\">\r\n                        <tbody>\r\n                            <tr>\r\n                                <td class=\"pl-2\"> 1. Leveringskosten van [product_type] </td>\r\n                                <td class=\"pl-2 text-right\">[total_delivery_amount]</td>\r\n                            </tr>\r\n                            <tr class=\"[show_price_cap_billing]\">\r\n                                <td class=\"pl-2\"> 2. Tegemoetkoming uit het prijsplafond</td>\r\n                                <td class=\"pl-2 text-right\">[total_price_cap]</td>\r\n                              </tr>\r\n                            <tr>\r\n                                <td class=\"pl-2 [hide_price_cap_billing]\"> 2. Overheidsheffingen op [product_type], dit dragen we af aan de overheid </td>\r\n                                <td class=\"pl-2 [show_price_cap_billing]\"> 3. Overheidsheffingen op [product_type], dit dragen we af aan de overheid </td>\r\n                                <td class=\"pl-2 text-right\">[total_tax_amount]</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <td class=\"pl-2 [hide_price_cap_billing]\"> 3. Netbeheerkosten op [product_type], dit dragen we af aan je\r\n                                    netbeheerder</td>\r\n                                <td class=\"pl-2 [show_price_cap_billing]\"> 4. Netbeheerkosten op [product_type], dit dragen we af aan je\r\n                                    netbeheerder </td>\r\n                                <td class=\"pl-2 text-right\">[total_grid_operator_amount]</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <td class=\"pl-2 font-weight-bold\"></td>\r\n                                <td class=\"pl-2 text-right  font-weight-bold\">[total_real_amount_incl_cancel_fee]</td>\r\n                            </tr>\r\n                        </tbody>\r\n                    </table>\r\n                </div>\r\n                <div class=\"mt-5\">\r\n                    <table class=\"table table-first\">\r\n                        <tbody>\r\n                            <tr>\r\n                                <td class=\"pl-2 [hide_price_cap_billing]\"> 4. In rekening gebrachte termijnbedragen </td>\r\n                                <td class=\"pl-2 [show_price_cap_billing]\"> 5. In rekening gebrachte termijnbedragen </td>\r\n                                <td class=\"pl-2 text-right\">[total_generated_amount_negative]</td>\r\n                            </tr>\r\n                            <tr class=\"[total_unpaid_amount_class]\">\r\n                                <td class=\"pl-4 font-italic\"> Openstaande termijnbedragen </td>\r\n                                <td class=\"pl-2 text-right\">[total_unpaid_amount]</td>\r\n                            </tr>\r\n                            <tr class=\"[total_collection_cost_amount_class]\">\r\n                                <td class=\"pl-4 font-italic\"> Openstaande incassokosten </td>\r\n                                <td class=\"pl-2 text-right\">[total_collection_cost_amount]</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <td class=\"pl-2 font-weight-bold\"></td>\r\n                                <td class=\"pl-2 text-right  font-weight-bold\">[total_real_generated_amount_negative]\r\n                                </td>\r\n                            </tr>\r\n                        </tbody>\r\n                    </table>\r\n                    <table>\r\n                        <tbody>\r\n                            <tr>\r\n                                <td class=\"w-100\"></td>\r\n                                <td class=\"pl-2 text-right font-weight-bold text-nowrap t-nowrap\">\r\n                                    <div class=\"border-top-bold position-relative\">\r\n                                        <span class=\"pr-5\">[is_receive]</span>\r\n                                        <span>€ [difference_amount]</span>\r\n                                    </div>\r\n                                </td>\r\n                            </tr>\r\n                        </tbody>\r\n                    </table>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div class=\"[usage_only_gas_elk_visible]\">\r\n                    <p class=\"mb-1 font-weight-bold\"> Berekening van je verbruik </p>\r\n                    <p class=\"mb-5\"> Op basis van je meterstanden bepalen wij hoeveel energie je hebt verbruikt. De\r\n                        meterstanden lezen wij uit via je slimme meter, vragen wij bij je op of berekenen we zelf.\r\n                        Onderstaand vind je een overzicht van je verbruik per periode. Omdat tussen periodes soms\r\n                        verschillende tarieven gelden, kan het zijn dat je verschillende periodes ziet. </p>\r\n                </div>\r\n                <div class=\"[usage_only_gas_elk_visible]\"> [usage_item_by_ean] </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    <div class=\"[usage_only_gas_elk_visible]\" style=\"page-break-before: always\"></div>\r\n    <div class=\"page [usage_both_gas_elk_visible]\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div>\r\n                    <p class=\"mb-1 font-weight-bold\"> Berekening van je verbruik </p>\r\n                    <p class=\"mb-5\"> Op basis van je meterstanden bepalen wij hoeveel energie je hebt verbruikt. De\r\n                        meterstanden lezen wij uit via je slimme meter, vragen wij bij je op of berekenen we zelf.\r\n                        Onderstaand vind je een overzicht van je verbruik per periode. Omdat tussen periodes soms\r\n                        verschillende tarieven gelden, kan het zijn dat je verschillende periodes ziet. </p>\r\n                </div>\r\n                <div> [usage_item_by_ean] </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    <div class=\"[usage_both_gas_elk_visible]\" style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div>\r\n                    <p class=\"mb-4\">Op de volgende pagina’s vind je een nadere specificatie van de kosten die\r\n                        weergegeven zijn op pagina 2.</p>\r\n                    [return_tariff_section]\r\n                    <p class=\"mb-1 font-weight-bold\">1. Leveringskosten voor [product_type]</p>\r\n                    <p class=\"mb-5\"> Onderstaand vind je een specificatie van je leveringskosten voor [product_type].\r\n                        Door je verbruik te vermenigvuldigen met je tarief bepalen we je kosten per contract. </p>\r\n                </div>\r\n                <div class=\"table_fixed_delivery\"> [fixed_delivery_item_dynamic_page] </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n\r\n    [price_cap_section_template]\r\n\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div class=\"row\">\r\n                    <div class=\"col-12\">\r\n                        <p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">2. Overheidsheffingen op [product_type]</p>\r\n                        <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">3. Overheidsheffingen op [product_type]</p>\r\n                        <p style=\"display: [show_new_ode_tax_description]\">Naast de kosten voor het verbruik van\r\n                            [product_type], moet je ook belastingen betalen aan de overheid. Ook deze zijn afhankelijk\r\n                            van je verbruik. Onderstaande kosten dragen wij direct af aan de overheid. Omdat de\r\n                            heffingen jaarlijks (per 1 januari) veranderen zie je onderstaand mogelijk twee\r\n                            berekeningen: een voor de periode vóór en een voor de periode ná 1 januari.</p>\r\n                    </div>\r\n                </div>\r\n                <div class=\"mt-3\"> [tax_item_dynamic_page] </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div class=\"row\">\r\n                    <div class=\"col-12\">\r\n                        <p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">3. Netbeheerkosten voor [product_type]</p>\r\n                        <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">4. Netbeheerkosten voor [product_type]</p>\r\n                        <p class=\"mb-3\">Om van [product_type] gebruik te kunnen maken, dien je aangesloten te zijn op\r\n                            het openbare [product_type]netwerk van je netbeheerder. Hiervoor betaal je een vaste\r\n                            vergoeding die afhankelijk is van je aansluiting. Wij dragen deze vervolgens weer af aan je\r\n                            netbeheerder. Ook hier geldt dat de tarieven jaarlijks per 1 januari wijzigen. Om deze reden\r\n                            zie je onderstaand mogelijk weer twee berekeningen: voor de periode vóór en de periode ná 1\r\n                            januari. </p>\r\n                        <p> Je netbeheerder: <strong>[grid_operator_name]</strong>\r\n                        </p>\r\n                    </div>\r\n                </div>\r\n                <div class=\"mt-3 custom-table table_grid_operator\"> [grid_operator_item_dynamic_page] </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div class=\"row\">\r\n                    <div class=\"col-12\">\r\n                    	<p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">4. Totaal in rekening gebrachte termijnbedragen</p>\r\n                        <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">5. Totaal in rekening gebrachte termijnbedragen</p>\r\n                        <p class=\"mb-1\">Hier zie je een overzicht van de door ons in rekening gebrachte termijnbedragen in de afgelopen periode (incl. btw). Een negatief termijnbedrag wordt als niet in rekening gebracht beschouwd en daarom als 0 weergegeven.</p>\r\n                    </div>\r\n                </div>\r\n                <div class=\"mt-5\">\r\n                    <table class=\"table table-custom\">\r\n                        <thead>\r\n                            <th class=\"pl-2 charge-item-month-column\">MAAND</th>\r\n                            <th class=\"pl-2 charge-item-invoice-number\">FACTUURNUMMER</th>\r\n                            <th class=\"pl-2 text-right\" colspan=\"2\">BEDRAG</th>\r\n                        </thead>\r\n                        <tbody> [charged_item_by_month] </tbody>\r\n                    </table>\r\n                    <table>\r\n                        <tbody>\r\n                            <tr>\r\n                                <td style=\"height: 15px;\"></td>\r\n                            </tr>\r\n                            <tr>\r\n                                <td class=\"w-100\"></td>\r\n                                <td class=\"pl-2 text-right font-weight-bold text-nowrap t-nowrap\">\r\n                                    <div class=\"border-top-bold position-relative\">\r\n                                        <span class=\"pr-5\">Totaal in rekening gebrachte termijnbedragen</span>\r\n                                        <span>[total_generated_amount]</span>\r\n                                    </div>\r\n                                </td>\r\n                            </tr>\r\n                        </tbody>\r\n                    </table>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div>\r\n                    <p class=\"font-weight-bold\">Jouw EAN-codes</p> [elk_gas_eans]\r\n                </div>\r\n                <div class=\"mt-5\">\r\n                    <p class=\"font-weight-bold\">Btw-aangifte</p>\r\n                    <p class=\"mb-0\">\r\n                        [reseller_name] handelt onder de leveranciersvergunning van Kikker Energie. In het geval je een\r\n                        btw-aangifte moet doen, dien je daarom de gegevens van Kikker Energie te gebruiken. De benodigde\r\n                        informatie van Kikker Energie en je netbeheerder vind je onderstaand:\r\n                    </p>\r\n                </div>\r\n                <div class=\"row mt-4\">\r\n                    <div class=\"col-5\">\r\n                        <p class=\"mb-0\">\r\n                            Kikker Energie B.V.</br>\r\n                            Tolnasingel 12 </br> 2411PV Bodegraven\r\n                        </p>\r\n                        <p class=\"mb-0\">KvK: 71246681</p>\r\n                        <p class=\"mb-0\">Btw nr.: NL858635732B01</p>\r\n                    </div>\r\n                    <div class=\"col-5\">\r\n                        <p class=\"mb-0\"> [grid_operator_name] </br> [grid_operator_house_nr] </br>\r\n                            [grid_operator_postcode] </p>\r\n                        <p class=\"mb-0\">KvK: [grid_operator_kvk]</p>\r\n                        <p class=\"mb-0\">Btw nr.: [grid_operator_btw]</p>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</body>\r\n\r\n</html>', NULL, NULL, 'nl', 'ke-pdf', NULL, '2023-11-27 09:07:13.152323', NULL);
INSERT IGNORE INTO `templates_reseller` (`Id`, `reseller_id`, `template_name`, `html_content`, `header_id`, `footer_id`, `language_code`, `CreatedBy`, `ModifiedBy`, `CreatedAt`, `ModifiedAt`) VALUES (36, 197, 'FINALBILL_TEMPLATE_CANCELATION_FEE', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n\r\n<head>\r\n  <title>Billing | Kikker</title>\r\n  <meta charset=\"utf-8\">\r\n  <link rel=\"icon\" href=\"asset/kikker-icon.ico\" />\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\r\n  <link rel=\"stylesheet\" href=\"https://storage.googleapis.com/kikkerprodbucket/static-files/pdf-css/site.css\">\r\n  <link rel=\"stylesheet\" href=\"https://storage.googleapis.com/kikkerprodbucket/static-files/pdf-css/final_bill.css\">\r\n</head>\r\n\r\n<body>\r\n  <div class=\"page\">\r\n    <div class=\"container text-normal\">\r\n      <div class=\"content\">\r\n        <div class=\"row\">\r\n          <div class=\"col-12\">\r\n            <p class=\"mb-0\"></span>[customer_full_name]<br>[billing_address_street] [billing_address_houseNr]<br>\r\n                [billing_address_zipcode] [billing_address_city]\r\n                <span class=\"float-right\">[date_generate_PDF]</span>\r\n              </p>\r\n            <p class=\"mt-5 mb-0\">Beste [customer_first_name],</p>\r\n            <br>\r\n            <p class=\"mb-2 [final_bill_visible]\">Dit is je eindafrekening over de verbruiksperiode van\r\n              [final_bill_start_date] tot [final_bill_end_date] voor je\r\n              leveringsadres [delivery_address_street] [delivery_address_houseNr] te [delivery_address_city]. Je\r\n              ontvangt deze afrekening omdat je contract met Kikker\r\n              Energie eindigt. In deze eindafrekening berekenen we de kosten tot de einddatum van je contract. Indien je\r\n              onlangs\r\n              een nieuw Kikker Energie-contract hebt afgesloten, ontvang je hier apart bericht van.\r\n            </p>\r\n\r\n            <p class=\"mb-2 [yearly_bill_visible]\">Dit is je jaarafrekening over de verbruiksperiode van\r\n              [final_bill_start_date] tot [final_bill_end_date] voor je leveringsadres [delivery_address_street] te\r\n              [delivery_address_city]. In deze jaarafrekening vind je een overzicht van je energieverbruik in het\r\n              afgelopen\r\n              jaar en wat je hiervoor hebt betaald.\r\n            </p>\r\n            <p>\r\n              Alle bedragen die vermeld staan in deze afrekening zijn inclusief [vat]% btw. Meer informatie over je\r\n              verbruik of de\r\n              precieze berekening van je <span class=\"[final_bill_visible]\">eindafrekening</span><span\r\n                class=\"[yearly_bill_visible]\">jaarafrekening</span> vind je op de volgende pagina’s.\r\n            </p>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"mt-3\">\r\n          <table class=\"table\">\r\n            <tbody>\r\n              <tr>\r\n                <td class=\"pl-2\">\r\n                  In rekening gebrachte termijnbedragen\r\n                </td>\r\n                <td class=\"pl-2 text-right\">€ [total_generated_amount]</td>\r\n              </tr>\r\n              <tr class=\"[show_price_cap_billing]\">\r\n                <td class=\"pl-2\"> Tegemoetkoming uit het prijsplafond </td>\r\n                <td class=\"pl-2 text-right\">[total_price_cap]</td>\r\n              </tr>\r\n              <tr>\r\n                <td class=\"pl-2\">\r\n                  Totale kosten over deze eindnota\r\n                </td>\r\n                <td class=\"pl-2 text-right\">[total_real_amount]</td>\r\n              </tr>\r\n              <tr class=\"[cancelation_fee_visible]\">\r\n                <td class=\"pl-2\">\r\n                  Opzegboete\r\n                </td>\r\n                <td class=\"pl-2 text-right\">[cancelation_fee]</td>\r\n              </tr>\r\n              <tr>\r\n                <td class=\"pl-2 font-weight-bold\">\r\n                  [is_receive]\r\n                </td>\r\n                <td class=\"pl-2 text-right  font-weight-bold\">€ [difference_amount]</td>\r\n              </tr>\r\n            </tbody>\r\n          </table>\r\n        </div>\r\n\r\n        <div class=\"mt-3\">\r\n          <p class=\"mb-1 font-weight-bold\">\r\n            De termijnbedragen op je <span class=\"[final_bill_visible]\">eindafrekening</span><span\r\n              class=\"[yearly_bill_visible]\">jaarafrekening</span>\r\n          </p>\r\n          <p class=\"mb-3\">\r\n            Op deze <span class=\"[final_bill_visible]\">eindafrekening</span><span\r\n              class=\"[yearly_bill_visible]\">jaarafrekening</span> verrekenen we alle termijnbedragen die we tot nu toe\r\n            hebben gefactureerd. Indien je één of\r\n            meerdere termijnfacturen nog niet hebt betaald, moet je dit alsnog doen. Je kunt al je termijnfacturen\r\n            vinden in de\r\n            Kikker app.\r\n          </p>\r\n\r\n          <p class=\"mb-1 font-weight-bold [yearly_bill_visible] [new_monthly_amount_visible]\">\r\n            Je nieuwe termijnbedrag</span>\r\n          </p>\r\n          <p class=\"mb-3 [yearly_bill_visible] [new_monthly_amount_visible]\">\r\n            Op basis van je verbruik in de afgelopen 12 maanden, hebben we een nieuw termijnbedrag voor je uitgerekend.\r\n            We passen het termijnbedrag automatisch voor je aan. Ben je het niet eens met je nieuwe termijnbedrag? Dan\r\n            kun je dit gemakkelijk aanpassen in onze mobiele app.\r\n          </p>\r\n        </div>\r\n\r\n        <div class=\"row monthly-amount-block [yearly_bill_visible] [new_monthly_amount_visible] mt-3\"\r\n          style=\"background-image: url(\'data:image/png;base64,\');background-size: 100%; background-repeat: no-repeat; background-position: center center;\">\r\n          <div class=\"col-6\">\r\n            <span>\r\n              Oude termijnbedrag\r\n            </span>\r\n            <span class=\"float-right\">\r\n              € [current_monthly_amount]\r\n            </span>\r\n          </div>\r\n\r\n          <div class=\"col-6 pl-5 font-weight-bold\">\r\n            <span>\r\n              Nieuwe termijnbedrag\r\n            </span>\r\n            <span class=\"float-right\">\r\n              € [new_monthly_amount]\r\n            </span>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"mt-3 avoid-break-page\">\r\n          <p class=\"font-weight-bold mb-1\">Vragen?</p>\r\n          <p class=\"mb-3\" style=\"text-align: left;\">Neem contact op met jouw wederverkoper [reseller_name]. Dit kun je doen via e-mail op <a\r\n              href=\"mailto:[reseller_email]\">[reseller_email]</a> of telefonisch op [reseller_phone]. Ook kun je Kikker\r\n            Energie zelf bereiken op <a href=\"mailto:servicedesk@kikker.nl\">servicedesk@kikker.nl</a> of 020 - 29 94\r\n            200.</p>\r\n          <p class=\"mb-3\">Met vriendelijke groet, </p>\r\n          <p class=\"mb-0\">Kikker Energie</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div style=\"page-break-before: always\">&nbsp;</div>\r\n\r\n  <div class=\"page\">\r\n    <div class=\"container text-normal\">\r\n      <div class=\"content\">\r\n        <div class=\"row\">\r\n          <div class=\"col-12\">\r\n            <p>Meer informatie over je verbruik of de precieze berekening van je eindafrekening vind je op de volgende pagina’s.</p>\r\n            <p class=\"mb-1 font-weight-bold\">Samenvatting van je <span\r\n                class=\"[final_bill_visible]\">eindafrekening</span><span\r\n                class=\"[yearly_bill_visible]\">jaarafrekening</span></p>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"mt-5 table-first\">\r\n          <table class=\"table\">\r\n            <tbody>\r\n              <tr>\r\n                <td class=\"pl-2\">\r\n                  1. In rekening gebrachte termijnbedragen\r\n                </td>\r\n                <td class=\"pl-2 text-right\">€ [total_generated_amount]</td>\r\n              </tr>\r\n              <tr>\r\n                <td class=\"pl-2 font-weight-bold\">\r\n                </td>\r\n                <td class=\"pl-2 text-right  font-weight-bold\">€ [total_generated_amount]</td>\r\n              </tr>\r\n            </tbody>\r\n          </table>\r\n        </div>\r\n\r\n        <div class=\"mt-4 table-first\">\r\n          <table class=\"table\">\r\n            <tbody>\r\n              <tr>\r\n                <td class=\"pl-2\">\r\n                  2. Leveringskosten van [product_type]\r\n                </td>\r\n                <td class=\"pl-2 text-right\">[total_delivery_amount]</td>\r\n              </tr>\r\n              <tr class=\"[show_price_cap_billing]\">\r\n                <td class=\"pl-2\"> 3. Tegemoetkoming uit het prijsplafond</td>\r\n                <td class=\"pl-2 text-right\">[total_price_cap]</td>\r\n              </tr>\r\n              <tr>\r\n                <td class=\"pl-2 [hide_price_cap_billing]\">3. Overheidsheffingen op [product_type], dit dragen we af aan de overheid</td>\r\n                <td class=\"pl-2 [show_price_cap_billing]\">4. Overheidsheffingen op [product_type], dit dragen we af aan de overheid</td>\r\n                <td class=\"pl-2 text-right\">[total_tax_amount]</td>\r\n              </tr>\r\n              <tr>\r\n                <td class=\"pl-2 [hide_price_cap_billing]\">4. Netbeheerkosten op [product_type], dit dragen we af aan je netbeheerder</td>\r\n                <td class=\"pl-2 [show_price_cap_billing]\">5. Netbeheerkosten op [product_type], dit dragen we af aan je netbeheerder</td>\r\n                <td class=\"pl-2 text-right\">[total_grid_operator_amount]</td>\r\n              </tr>\r\n              <tr>\r\n                <td class=\"pl-2 [hide_price_cap_billing]\">5. Opzegboete voor tussentijdse opzegging</td>\r\n                <td class=\"pl-2 [show_price_cap_billing]\">6. Opzegboete voor tussentijdse opzegging</td>\r\n                <td class=\"pl-2 text-right\">[cancelation_fee]</td>\r\n              </tr>\r\n              <tr>\r\n                <td class=\"pl-2 font-weight-bold\">\r\n                </td>\r\n                <td class=\"pl-2 text-right  font-weight-bold\">[total_real_amount_incl_cancel_fee]</td>\r\n              </tr>\r\n            </tbody>\r\n          </table>\r\n          <div class=\"mt-2 pt-4 position-relative text-right font-weight-bold elk-gas-total btw-total\">\r\n            <span class=\"w-200 nowrap\">[is_receive]</span>\r\n            <span>€ [difference_amount]</span>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div style=\"page-break-before: always\">&nbsp;</div>\r\n\r\n  <div class=\"page\">\r\n    <div class=\"container text-normal\">\r\n      <div class=\"content\">\r\n        <div class=\"[usage_only_gas_elk_visible]\">\r\n          <p class=\"mb-1 font-weight-bold\">\r\n            Berekening van je verbruik\r\n          </p>\r\n          <p>\r\n            Op basis van je meterstanden bepalen wij hoeveel energie je hebt verbruikt. De meterstanden lezen wij uit\r\n            via je\r\n            slimme meter, vragen wij bij je op via de Kikker app of berekenen we zelf. Onderstaand vind je een overzicht\r\n            van je\r\n            verbruik per periode. Omdat tussen periodes soms verschillende tarieven gelden, kan het zijn dat je\r\n            verschillende\r\n            periodes ziet.\r\n          </p>\r\n        </div>\r\n\r\n        <div class=\"mt-5 table-usage [usage_only_gas_elk_visible]\">\r\n          [usage_item_by_ean]\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"[usage_only_gas_elk_visible]\" style=\"page-break-before: always\">&nbsp;</div>\r\n\r\n  <div class=\"page [usage_both_gas_elk_visible]\">\r\n    <div class=\"container text-normal\">\r\n      <div class=\"content\">\r\n        <div>\r\n          <p class=\"mb-1 font-weight-bold\">\r\n            Berekening van je verbruik\r\n          </p>\r\n          <p>\r\n            Op basis van je meterstanden bepalen wij hoeveel energie je hebt verbruikt. De meterstanden lezen wij uit\r\n            via je\r\n            slimme meter, vragen wij bij je op via de Kikker app of berekenen we zelf. Onderstaand vind je een overzicht\r\n            van je\r\n            verbruik per periode. Omdat tussen periodes soms verschillende tarieven gelden, kan het zijn dat je\r\n            verschillende\r\n            periodes ziet.\r\n          </p>\r\n        </div>\r\n\r\n        <div class=\"mt-5 table-usage\">\r\n          [usage_item_by_ean]\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"[usage_both_gas_elk_visible]\" style=\"page-break-before: always\">&nbsp;</div>\r\n\r\n  <div class=\"page\">\r\n    <div class=\"container text-normal\">\r\n      <div class=\"content\">\r\n        <div>\r\n          <p class=\"mb-4\">Op de volgende pagina’s vind je een nadere specificatie van de kosten die weergegeven zijn op\r\n            pagina 2.</p>\r\n          [return_tariff_section]\r\n          <p class=\"mb-1 font-weight-bold\">1. Leveringskosten voor [product_type]</p>\r\n          <p class=\"mb-5\">\r\n            Onderstaand vind je een specificatie van je leveringskosten voor [product_type]. Door je verbruik te\r\n            vermenigvuldigen\r\n            met je tarief bepalen we je kosten per contract.\r\n          </p>\r\n        </div>\r\n\r\n        <div class=\"table-delivery\">\r\n          [fixed_delivery_item]\r\n        </div>\r\n\r\n        <div class=\"mt-3 [fixed_delivery_item_first_page_visible]\">\r\n\r\n          <div class=\"mt-2 pt-4 position-relative text-right font-weight-bold elk-gas-total btw-total\">\r\n            <span class=\"w-200 nowrap\">Totaalbedrag voor leveringskosten voor [product_type]</span>\r\n            <span>€ [fixed_delivery_total]</span>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div style=\"page-break-before: always\">&nbsp;</div>\r\n\r\n  [fixed_delivery_item_dynamic_page]\r\n\r\n  [price_cap_section_template]\r\n\r\n  <div class=\"page\">\r\n    <div class=\"container text-normal\">\r\n      <div class=\"content\">\r\n        <div class=\"row\">\r\n          <div class=\"col-12\">\r\n            <p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">2. Overheidsheffingen op [product_type]</p>\r\n            <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">3. Overheidsheffingen op [product_type]</p>\r\n            <p style=\"display: [show_new_ode_tax_description]\">Naast de kosten voor het verbruik van [product_type],\r\n              moet je ook belastingen betalen aan de overheid. Ook deze zijn afhankelijk van je verbruik. Onderstaande\r\n              kosten dragen wij direct af aan de overheid. Omdat de heffingen jaarlijks (per 1 januari) veranderen zie\r\n              je onderstaand mogelijk twee berekeningen: een voor de periode vóór en een voor de periode ná 1 januari.\r\n            </p>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"mt-5 custom-table\">\r\n          [tax_item]\r\n        </div>\r\n        <div class=\"mt-3 [tax_item_first_page_visible]\">\r\n          <div class=\"mt-2 pt-4 position-relative text-right font-weight-bold elk-gas-total btw-total\">\r\n            <span class=\"w-200 nowrap\">Totaalbedrag voor overheidsheffingen op [product_type]</span>\r\n            <span>[tax_item_total]</span>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div style=\"page-break-before: always\">&nbsp;</div>\r\n\r\n  [tax_item_dynamic_page]\r\n\r\n  <div class=\"page\">\r\n    <div class=\"container text-normal\">\r\n      <div class=\"content\">\r\n        <div class=\"row\">\r\n          <div class=\"col-12\">\r\n            <p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">3. Netbeheerkosten voor [product_type]</p>\r\n            <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">4. Netbeheerkosten voor [product_type]</p>\r\n            <p class=\"mb-3\">Om van [product_type] gebruik te kunnen maken, dien je aangesloten te zijn op het openbare\r\n              [product_type]netwerk\r\n              van je netbeheerder. Hiervoor betaal je een vaste vergoeding die afhankelijk is van je aansluiting. Wij\r\n              dragen deze\r\n              vervolgens weer af aan je netbeheerder. Ook hier geldt dat de tarieven jaarlijks per 1 januari wijzigen.\r\n              Om deze reden\r\n              zie je onderstaand mogelijk weer twee berekeningen: voor de periode vóór en de periode ná 1 januari.\r\n            </p>\r\n            <p>\r\n              Je netbeheerder: <strong>[grid_operator_name]</strong>\r\n            </p>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"mt-5 custom-table\">\r\n          [grid_operator_item]\r\n\r\n        </div>\r\n        <div class=\"mt-3 [grid_operator_item_first_page_visible]\">\r\n          <div class=\"mt-2 pt-4 position-relative text-right font-weight-bold elk-gas-total btw-total\">\r\n            <span class=\"w-200 nowrap\">Totaalbedrag voor netbeheerkosten op [product_type]</span>\r\n            <span>[grid_operator_total]</span>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div style=\"page-break-before: always\">&nbsp;</div>\r\n\r\n  [grid_operator_item_dynamic_page]\r\n\r\n  <div class=\"page\">\r\n    <div class=\"container text-normal\">\r\n      <div class=\"content\">\r\n        <div class=\"row\">\r\n          <div class=\"col-12\">\r\n            <p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">4. Opzegboete voor tussentijdse opzegging</p>\r\n            <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">5. Opzegboete voor tussentijdse opzegging</p>\r\n            <p>Dit contract had een looptijd voor [contract_duration], maar is na [day_active_in_our_system] dagen\r\n              opgezegd. Conform de afgesproken voorwaarden, wordt bij opzegging gedurende de vaste looptijd van het\r\n              contract een opzegboete in rekening gebracht. Deze opzegboete is afhankelijk van de resterende looptijd\r\n              van het contract en geldt per product ([product_type]). Voor een resterende looptijd van [remaning_days],\r\n              bedraagt de opzegboete € [cancelation_fee_summary] per product. Hierbij houden we ons aan de richtlijnen\r\n              van de Autoriteit Consument en Markt.\r\n            </p>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"mt-5\">\r\n          <table class=\"table table-custom [cancellation_fee_visible]\">\r\n            <thead>\r\n              <th class=\"pl-2 text-uppercase\">OPZEGBOETE VOOR CONTRACT MET RESTERENDE LOOPTIJD MEER DAN\r\n                [contract_duration_title]</th>\r\n              <th class=\"pl-2 text-right\">BEDRAG</th>\r\n            </thead>\r\n            <tbody>\r\n              <tr class=\"[cancellation_fee_elk_visible]\">\r\n                <td class=\"pl-2\">\r\n                  Opzegboete stroom\r\n                </td>\r\n                <td class=\"pl-2 text-right\">€ [cancelation_fee_elk]</td>\r\n              </tr>\r\n              <tr class=\"[cancellation_fee_gas_visible]\">\r\n                <td class=\"pl-2\">\r\n                  Opzegboete gas\r\n                </td>\r\n                <td class=\"pl-2 text-right\">€ [cancelation_fee_gas]</td>\r\n              </tr>\r\n            </tbody>\r\n          </table>\r\n          <div class=\"mt-2 pt-4 position-relative text-right font-weight-bold elk-gas-total btw-total\">\r\n            <span class=\"w-200 nowrap\">Totaalbedrag opzegboete voor tussentijdse opzegging</span>\r\n            <span>€ [cancelation_fee_last_page]</span>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <div style=\"page-break-before: always\">&nbsp;</div>\r\n\r\n  <div class=\"page\">\r\n    <div class=\"container text-normal\">\r\n      <div class=\"content\">\r\n        <div class=\"row\">\r\n          <div class=\"col-12\">\r\n          	<p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">5. Totaal in rekening gebrachte termijnbedragen</p>\r\n            <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">6. Totaal in rekening gebrachte termijnbedragen</p>\r\n            <p>Hier zie je een overzicht van de door ons in rekening gebrachte termijnbedragen in de afgelopen periode (incl. btw). Een negatief termijnbedrag wordt als niet in rekening gebracht beschouwd en daarom als 0 weergegeven.\r\n            </p>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"mt-5\">\r\n          <table class=\"table table-custom\">\r\n            <thead>\r\n              <th class=\"pl-2\">MAAND</th>\r\n              <th class=\"pl-2 text-right\">BEDRAG</th>\r\n            </thead>\r\n            <tbody>\r\n              [charged_item_by_month]\r\n            </tbody>\r\n          </table>\r\n          <div class=\"mt-2 pt-4 position-relative text-right font-weight-bold elk-gas-total btw-total\">\r\n            <span class=\"w-200 nowrap\">Totaal in rekening gebrachte termijnbedragen</span>\r\n            <span>€ [total_generated_amount]</span>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div style=\"page-break-before: always\">&nbsp;</div>\r\n\r\n  <div class=\"page\">\r\n    <div class=\"container text-normal\">\r\n      <div class=\"content\">\r\n        <div class=\"mt-2\">\r\n          <p class=\"font-weight-bold\">Jouw EAN-codes</p>\r\n          [elk_gas_eans]\r\n        </div>\r\n\r\n        <div class=\"mt-5\">\r\n          <p class=\"font-weight-bold\">Btw-aangifte</p>\r\n          <p class=\"mb-0\">\r\n            [reseller_name] handelt onder de leveranciersvergunning van Kikker Energie. In het geval je een btw-aangifte\r\n            moet doen, dien je daarom de gegevens van Kikker Energie te gebruiken. De benodigde informatie van Kikker\r\n            Energie en je netbeheerder vind je onderstaand:\r\n          </p>\r\n        </div>\r\n\r\n        <div class=\"row mt-4\">\r\n          <div class=\"col-5\">\r\n            <p class=\"mb-0\">\r\n              Kikker Energie B.V.</br>\r\n              Tolnasingel 12 </br> 2411PV Bodegraven\r\n            </p>\r\n            <p class=\"mb-0\">KvK: 71246681</p>\r\n            <p class=\"mb-0\">Btw nr.: NL858635732B01</p>\r\n          </div>\r\n          <div class=\"col-5\">\r\n            <p class=\"mb-0\">\r\n              [grid_operator_name]</br>\r\n              [grid_operator_house_nr]</br>\r\n              [grid_operator_postcode]\r\n            </p>\r\n            <p class=\"mb-0\">KvK: [grid_operator_kvk]</p>\r\n            <p class=\"mb-0\">Btw nr.: [grid_operator_btw]</p>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</body>\r\n\r\n</html>', NULL, NULL, 'nl', 'ke-pdf', NULL, '2023-11-27 09:07:13.152323', NULL);
INSERT IGNORE INTO `templates_reseller` (`Id`, `reseller_id`, `template_name`, `html_content`, `header_id`, `footer_id`, `language_code`, `CreatedBy`, `ModifiedBy`, `CreatedAt`, `ModifiedAt`) VALUES (43, 197, 'FINALBILL_TEMPLATE_CANCELATION_FEE_AL_NUMBER', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n\r\n<head>\r\n    <title>Billing | Kikker</title>\r\n    <meta charset=\"utf-8\">\r\n    <link rel=\"icon\" href=\"asset/kikker-icon.ico\" />\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\r\n    <link rel=\"stylesheet\" href=\"https://storage.googleapis.com/kikkerprodbucket/static-files/pdf-css/site.css\">\r\n    <link rel=\"stylesheet\" href=\"https://storage.googleapis.com/kikkerprodbucket/static-files/pdf-css/final_bill.css\">\r\n</head>\r\n\r\n<body>\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div class=\"row header mr-0 ml-0\">\r\n                    <div style=\"width: 33%;\">\r\n                    </div>\r\n                    <div class=\"[hide-header-invoice-info] header-invoice-info\">\r\n                        <div class=\"d-flex justify-content-end\">\r\n                            <div class=\"space-span d-inline-block\" style=\"padding-top: 0\">\r\n                                <div class=\"mb-0 d-flex\">\r\n                                    <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\">Klantnummer:</p>\r\n                                    <p class=\"mb-0\">[client_number]</p>\r\n                                </div>\r\n                                <div class=\"mb-0 d-flex\">\r\n                                    <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\"\r\n                                        >Contractnummer:\r\n                                    </p>\r\n                                    <p class=\"mb-0\">[contract_number]</p>\r\n                                </div>\r\n                                <div class=\"mb-0 d-flex [hidden_contract_reference]\" style=\"flex-flow: row;\">\r\n                                    <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\">Contractreferentie: </p>\r\n                                    <p class=\"mb-0\">[contract_reference]</p>\r\n                                </div>\r\n                                <div class=\"mb-0 d-flex\">\r\n                                    <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\"\r\n                                        >Factuurnummer:\r\n                                    </p>\r\n                                    <p class=\"mb-0\">[invoice_number]</p>\r\n                                </div>\r\n                                <div class=\"mb-0 d-flex [company_name_visible]\" style=\"flex-flow: row;\">\r\n                                    <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\">Bedrijfsnaam: </p>\r\n                                    <p class=\"mb-0\">[company_name]</p>\r\n                                </div>\r\n                                <div class=\"mb-0 d-flex\" style=\"flex-flow: row;\">\r\n                                    <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\">Energie intermediair: </p>\r\n                                    <p class=\"mb-0\">[header_reseller_name]</p>\r\n                                </div>\r\n                                <div class=\"mb-0 d-flex\">\r\n                                    <p class=\"text-right vertical-align-top pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\"\r\n                                        >Leveringsadres:</p\r\n                                    >\r\n                                    <p class=\"mb-0\" class=\"d-inline-block\"\r\n                                        >[delivery_address_street] [delivery_address_houseNr] [delivery_address_zipcode]<br><span class=\"text-capitalize\">[delivery_address_city]</span></p\r\n                                    >\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n                <div class=\"row\">\r\n                    <div class=\"col-12\">\r\n                        <p class=\"mb-0\">\r\n                            <span class=\"float-right\">[date_generate_PDF]</span>\r\n                        </p>\r\n                        <p class=\"mt-5 mb-4\">Beste [customer_first_name],</p>\r\n                        <p class=\"mb-4 [final_bill_visible]\">Dit is je eindafrekening over de verbruiksperiode van\r\n                            [final_bill_start_date] tot [final_bill_end_date] voor je leveringsadres\r\n                            [delivery_address_street] [delivery_address_houseNr] te <span\r\n                                class=\"text-capitalize\">[delivery_address_city]</span>. Je ontvangt deze afrekening\r\n                            omdat je contract met [reseller_name] eindigt. In deze eindafrekening berekenen we de kosten\r\n                            tot de einddatum van je contract. Indien je onlangs een nieuw [reseller_name]-contract hebt\r\n                            afgesloten, ontvang je hier apart bericht van. </p>\r\n                        <p class=\"mb-4 [yearly_bill_visible]\">Dit is je jaarafrekening over de verbruiksperiode van\r\n                            [final_bill_start_date] tot [final_bill_end_date] voor je leveringsadres\r\n                            [delivery_address_street] te <span class=\"text-capitalize\">[delivery_address_city]</span>.\r\n                            In deze jaarafrekening vind je een overzicht van je energieverbruik in het afgelopen jaar en\r\n                            wat je hiervoor hebt betaald. </p>\r\n                    </div>\r\n                </div>\r\n                [FINALBILL_TEMPLATE_UNPAID_AMOUNT_INVOICE_ITEM]\r\n                [FINALBILL_TEMPLATE_PAID_AMOUNT_INVOICE_ITEM]\r\n                <div>\r\n                    <p class=\"mb-1 font-weight-bold [yearly_bill_visible] [new_monthly_amount_visible]\"> Je nieuwe\r\n                        termijnbedrag </span>\r\n                    </p>\r\n                    <p class=\"mb-4 [yearly_bill_visible] [new_monthly_amount_visible]\"> Op basis van je verbruik in de\r\n                        afgelopen 12 maanden, hebben we een nieuw termijnbedrag voor je uitgerekend. We passen het\r\n                        termijnbedrag automatisch voor je aan. Ben je het niet eens met je nieuwe termijnbedrag? Dan kun\r\n                        je dit gemakkelijk aanpassen in onze mobiele app. </p>\r\n                </div>\r\n                <div class=\"row monthly-amount-block [yearly_bill_visible] [new_monthly_amount_visible] mt-4\"\r\n                    style=\"background-image: url(\'data:image/png;base64,\');background-size: 100%; background-repeat: no-repeat; background-position: center center;\">\r\n                    <div class=\"col-6\">\r\n                        <span> Oude termijnbedrag </span>\r\n                        <span class=\"float-right\"> € [current_monthly_amount] </span>\r\n                    </div>\r\n                    <div class=\"col-6 pl-5 font-weight-bold\">\r\n                        <span> Nieuwe termijnbedrag </span>\r\n                        <span class=\"float-right\"> € [new_monthly_amount] </span>\r\n                    </div>\r\n                </div>\r\n                <div class=\"mt-4 avoid-break-page\">\r\n                    <p class=\"font-weight-bold mb-1\">Vragen?</p>\r\n                    <p class=\"mb-3\" style=\"text-align: left;\">Je kunt altijd contact met ons opnemen via [reseller_email] of bellen naar\r\n                        [reseller_phone].</p>\r\n                    <p class=\"mb-3\">Met vriendelijke groet, </p>\r\n                    <p class=\"mb-0\">[reseller_name]</p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div class=\"row\">\r\n                    <div class=\"col-12\">\r\n                        <p>Meer informatie over je verbruik of de precieze berekening van je <span class=\"[final_bill_visible]\">eindafrekening</span> <span class=\"[yearly_bill_visible]\">jaarafrekening</span> vind je op de volgende pagina’s.</p>\r\n                        <p class=\"mb-1 font-weight-bold\">Samenvatting van je <span\r\n                                class=\"[final_bill_visible]\">eindafrekening</span>\r\n                            <span class=\"[yearly_bill_visible]\">jaarafrekening</span>\r\n                        </p>\r\n                    </div>\r\n                </div>\r\n                <div class=\"[hide_text_summary]\">[text_summary]</div>\r\n                <div class=\"mt-5 table-first\">\r\n                    <table class=\"table\">\r\n                        <tbody>\r\n                            <tr>\r\n                                <td class=\"pl-2\"> 1. Leveringskosten van [product_type] </td>\r\n                                <td class=\"pl-2 text-right\">[total_delivery_amount]</td>\r\n                            </tr>\r\n                            <tr class=\"[show_price_cap_billing]\">\r\n                                <td class=\"pl-2\"> 2. Tegemoetkoming uit het prijsplafond</td>\r\n                                <td class=\"pl-2 text-right\">[total_price_cap]</td>\r\n                              </tr>\r\n                            <tr>\r\n                                <td class=\"pl-2 [hide_price_cap_billing]\">2. Overheidsheffingen op [product_type], dit dragen we af aan de overheid</td>\r\n                                <td class=\"pl-2 [show_price_cap_billing]\">3. Overheidsheffingen op [product_type], dit dragen we af aan de overheid</td>\r\n                                <td class=\"pl-2 text-right\">[total_tax_amount]</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <td class=\"pl-2 [hide_price_cap_billing]\">3. Netbeheerkosten op [product_type], dit dragen we af aan je netbeheerder</td>\r\n                                <td class=\"pl-2 [show_price_cap_billing]\">4. Netbeheerkosten op [product_type], dit dragen we af aan je netbeheerder</td>\r\n                                <td class=\"pl-2 text-right\">[total_grid_operator_amount]</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <td class=\"pl-2 [hide_price_cap_billing]\">4. Opzegboete voor tussentijdse opzegging</td>\r\n                                <td class=\"pl-2 [show_price_cap_billing]\">5. Opzegboete voor tussentijdse opzegging</td>\r\n                                <td class=\"pl-2 text-right\">[cancelation_fee]</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <td class=\"pl-2 font-weight-bold\"></td>\r\n                                <td class=\"pl-2 text-right  font-weight-bold\">[total_real_amount_incl_cancel_fee]</td>\r\n                            </tr>\r\n                        </tbody>\r\n                    </table>\r\n                </div>\r\n                <div class=\"mt-4 table-first\">\r\n                    <table class=\"table\">\r\n                        <tbody>\r\n                            <tr>\r\n                                <td class=\"pl-2 [hide_price_cap_billing]\">5. In rekening gebrachte termijnbedragen </td>\r\n                                <td class=\"pl-2 [show_price_cap_billing]\">6. In rekening gebrachte termijnbedragen </td>\r\n                                <td class=\"pl-2 text-right\">[total_generated_amount_negative]</td>\r\n                            </tr>\r\n                            <tr class=\"[total_unpaid_amount_class]\">\r\n                                <td class=\"pl-4 font-italic\"> Openstaande termijnbedragen </td>\r\n                                <td class=\"pl-2 text-right\">[total_unpaid_amount]</td>\r\n                            </tr>\r\n                            <tr class=\"[total_collection_cost_amount_class]\">\r\n                                <td class=\"pl-4 font-italic\"> Openstaande incassokosten </td>\r\n                                <td class=\"pl-2 text-right\">[total_collection_cost_amount]</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <td class=\"pl-2 font-weight-bold\"></td>\r\n                                <td class=\"pl-2 text-right  font-weight-bold\">[total_real_generated_amount_negative]\r\n                                </td>\r\n                            </tr>\r\n                        </tbody>\r\n                    </table>\r\n                    <table>\r\n                        <tbody>\r\n                            <tr>\r\n                                <td style=\"height: 15px;\"></td>\r\n                            </tr>\r\n                            <tr>\r\n                                <td class=\"w-100\"></td>\r\n                                <td class=\"pl-2 text-right font-weight-bold text-nowrap t-nowrap\">\r\n                                    <div class=\"border-top-bold position-relative\">\r\n                                        <span class=\"pr-5\">[is_receive]</span>\r\n                                        <span>€ [difference_amount]</span>\r\n                                    </div>\r\n                                </td>\r\n                            </tr>\r\n                        </tbody>\r\n                    </table>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div class=\"[usage_only_gas_elk_visible]\">\r\n                    <p class=\"mb-1 font-weight-bold\"> Berekening van je verbruik </p>\r\n                    <p> Op basis van je meterstanden bepalen wij hoeveel energie je hebt verbruikt. De meterstanden\r\n                        lezen wij uit via je slimme meter, vragen wij bij je op of berekenen we zelf. Onderstaand vind\r\n                        je een overzicht van je verbruik per periode. Omdat tussen periodes soms verschillende tarieven\r\n                        gelden, kan het zijn dat je verschillende periodes ziet. </p>\r\n                </div>\r\n                <div class=\"mt-5 [usage_only_gas_elk_visible]\"> [usage_item_by_ean] </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    <div class=\"[usage_only_gas_elk_visible]\" style=\"page-break-before: always\"></div>\r\n    <div class=\"page [usage_both_gas_elk_visible]\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div>\r\n                    <p class=\"mb-1 font-weight-bold\"> Berekening van je verbruik </p>\r\n                    <p> Op basis van je meterstanden bepalen wij hoeveel energie je hebt verbruikt. De meterstanden\r\n                        lezen wij uit via je slimme meter, vragen wij bij je of berekenen we zelf. Onderstaand vind je\r\n                        een overzicht van je verbruik per periode. Omdat tussen periodes soms verschillende tarieven\r\n                        gelden, kan het zijn dat je verschillende periodes ziet. </p>\r\n                </div>\r\n                <div class=\"mt-5\"> [usage_item_by_ean] </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    <div class=\"[usage_both_gas_elk_visible]\" style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div>\r\n                    <p class=\"mb-4\">Op de volgende pagina’s vind je een nadere specificatie van de kosten die\r\n                        weergegeven zijn op pagina 2.</p>\r\n                    [return_tariff_section]\r\n                    <p class=\"mb-1 font-weight-bold\">1. Leveringskosten voor [product_type]</p>\r\n                    <p class=\"mb-5\"> Onderstaand vind je een specificatie van je leveringskosten voor [product_type].\r\n                        Door je verbruik te vermenigvuldigen met je tarief bepalen we je kosten per contract. </p>\r\n                </div>\r\n                <div class=\"table_fixed_delivery\"> [fixed_delivery_item_dynamic_page] </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n\r\n    [price_cap_section_template]\r\n\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div class=\"row\">\r\n                    <div class=\"col-12\">\r\n                        <p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">2. Overheidsheffingen op [product_type]</p>\r\n                        <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">3. Overheidsheffingen op [product_type]</p>\r\n                        <p style=\"display: [show_new_ode_tax_description]\">Naast de kosten voor het verbruik van\r\n                            [product_type], moet je ook belastingen betalen aan de overheid. Ook deze zijn afhankelijk\r\n                            van je verbruik. Onderstaande kosten dragen wij direct af aan de overheid. Omdat de\r\n                            heffingen jaarlijks (per 1 januari) veranderen zie je onderstaand mogelijk twee\r\n                            berekeningen: een voor de periode vóór en een voor de periode ná 1 januari.</p>\r\n                    </div>\r\n                </div>\r\n                <div class=\"mt-3\"> [tax_item_dynamic_page] </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div class=\"row\">\r\n                    <div class=\"col-12\">\r\n                        <p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">3. Netbeheerkosten voor [product_type]</p>\r\n                        <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">4. Netbeheerkosten voor [product_type]</p>\r\n                        <p class=\"mb-3\">Om van [product_type] gebruik te kunnen maken, dien je aangesloten te zijn op\r\n                            het openbare [product_type]netwerk van je netbeheerder. Hiervoor betaal je een vaste\r\n                            vergoeding die afhankelijk is van je aansluiting. Wij dragen deze vervolgens weer af aan je\r\n                            netbeheerder. Ook hier geldt dat de tarieven jaarlijks per 1 januari wijzigen. Om deze reden\r\n                            zie je onderstaand mogelijk weer twee berekeningen: voor de periode vóór en de periode ná 1\r\n                            januari. </p>\r\n                        <p> Je netbeheerder: <strong>[grid_operator_name]</strong>\r\n                        </p>\r\n                    </div>\r\n                </div>\r\n                <div class=\"mt-3 custom-table table_grid_operator\"> [grid_operator_item_dynamic_page] </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div class=\"row\">\r\n                    <div class=\"col-12\">\r\n                        <p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">4. Opzegboete voor tussentijdse opzegging</p>\r\n                        <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">5. Opzegboete voor tussentijdse opzegging</p>\r\n                        <p>Dit contract had een looptijd voor <span\r\n                                style=\"text-transform: lowercase;\">[contract_duration]</span>, maar is na\r\n                            [day_active_in_our_system] dagen opgezegd. Conform de afgesproken voorwaarden, wordt bij\r\n                            opzegging gedurende de vaste looptijd van het contract een opzegboete in rekening gebracht.\r\n                            Deze opzegboete is afhankelijk van de resterende looptijd van het contract en geldt per\r\n                            product ([product_type]). Voor een resterende looptijd van [remaning_days], bedraagt de\r\n                            opzegboete € [cancelation_fee_summary] per product. Hierbij houden we ons aan de richtlijnen\r\n                            van de Autoriteit Consument en Markt. </p>\r\n                    </div>\r\n                </div>\r\n                <div class=\"mt-5\">\r\n                    <table class=\"table table-custom [cancellation_fee_visible]\">\r\n                        <thead>\r\n                            <th class=\"pl-2 text-uppercase\">OPZEGBOETE VOOR CONTRACT MET RESTERENDE LOOPTIJD MEER DAN\r\n                                [contract_duration_title]</th>\r\n                            <th class=\"pl-2 text-right\">BEDRAG</th>\r\n                        </thead>\r\n                        <tbody>\r\n                            <tr class=\"[cancellation_fee_elk_visible]\">\r\n                                <td class=\"pl-2\"> Opzegboete stroom </td>\r\n                                <td class=\"pl-2 text-right\">€ [cancelation_fee_elk]</td>\r\n                            </tr>\r\n                            <tr class=\"[cancellation_fee_gas_visible]\">\r\n                                <td class=\"pl-2\"> Opzegboete gas </td>\r\n                                <td class=\"pl-2 text-right\">€ [cancelation_fee_gas]</td>\r\n                            </tr>\r\n                        </tbody>\r\n                    </table>\r\n                    <table>\r\n                        <tbody>\r\n                            <tr>\r\n                                <td style=\"height: 15px;\"></td>\r\n                            </tr>\r\n                            <tr>\r\n                                <td class=\"w-100\"></td>\r\n                                <td class=\"pl-2 text-right font-weight-bold text-nowrap t-nowrap\">\r\n                                    <div class=\"border-top-bold position-relative\">\r\n                                        <span class=\"pr-5\">Totaalbedrag opzegboete voor tussentijdse opzegging</span>\r\n                                        <span>€ [cancelation_fee_last_page]</span>\r\n                                    </div>\r\n                                </td>\r\n                            </tr>\r\n                        </tbody>\r\n                    </table>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n\r\n    <div style=\"page-break-before: always\"></div>\r\n\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div class=\"row\">\r\n                    <div class=\"col-12\">\r\n                    	<p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">5. Totaal in rekening gebrachte termijnbedragen</p>\r\n                        <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">6. Totaal in rekening gebrachte termijnbedragen</p>\r\n                        <p>Hier zie je een overzicht van de door ons in rekening gebrachte termijnbedragen in de afgelopen periode (incl. btw). Een negatief termijnbedrag wordt als niet in rekening gebracht beschouwd en daarom als 0 weergegeven.</p>\r\n                    </div>\r\n                </div>\r\n                <div class=\"mt-5\">\r\n                    <table class=\"table table-custom\">\r\n                        <thead>\r\n                            <th class=\"pl-2 charge-item-month-column\">MAAND</th>\r\n                            <th class=\"pl-2 charge-item-invoice-number\">FACTUURNUMME</th>\r\n                            <th class=\"pl-2 text-right\" colspan=\"2\">BEDRAG</th>\r\n                        </thead>\r\n                        <tbody> [charged_item_by_month] </tbody>\r\n                    </table>\r\n                    <table>\r\n                        <tbody>\r\n                            <tr>\r\n                                <td style=\"height: 15px;\"></td>\r\n                            </tr>\r\n                            <tr>\r\n                                <td class=\"w-100\"></td>\r\n                                <td class=\"pl-2 text-right font-weight-bold text-nowrap t-nowrap\">\r\n                                    <div class=\"border-top-bold position-relative\">\r\n                                        <span class=\"pr-5\">Totaal in rekening gebrachte termijnbedragen</span>\r\n                                        <span>[total_generated_amount]</span>\r\n                                    </div>\r\n                                </td>\r\n                            </tr>\r\n                        </tbody>\r\n                    </table>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n\r\n    <div style=\"page-break-before: always\"></div>\r\n\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div class=\"space-span mt-2\">\r\n                    <p class=\"font-weight-bold\">Jouw EAN-codes</p> [elk_gas_eans]\r\n                </div>\r\n                <div class=\"mt-5\">\r\n                    <p class=\"font-weight-bold\">Btw-aangifte</p>\r\n                    <p class=\"mb-0\"> [reseller_name] handelt onder de leveranciersvergunning van Kikker Energie. In het\r\n                        geval je een btw-aangifte moet doen, dien je daarom de gegevens van Kikker Energie te gebruiken.\r\n                        De benodigde informatie van Kikker Energie en je netbeheerder vind je onderstaand: </p>\r\n                </div>\r\n                <div class=\"row mt-4\">\r\n                    <div class=\"col-5\">\r\n                        <p class=\"mb-0\">\r\n                            Kikker Energie B.V.</br>\r\n                            Tolnasingel 12 </br> 2411PV Bodegraven\r\n                        </p>\r\n                        <p class=\"mb-0\">KvK: 71246681</p>\r\n                        <p class=\"mb-0\">Btw nr.: NL858635732B01</p>\r\n                    </div>\r\n                    <div class=\"col-5\">\r\n                        <p class=\"mb-0\"> [grid_operator_name] </br> [grid_operator_house_nr] </br>\r\n                            [grid_operator_postcode] </p>\r\n                        <p class=\"mb-0\">KvK: [grid_operator_kvk]</p>\r\n                        <p class=\"mb-0\">Btw nr.: [grid_operator_btw]</p>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</body>\r\n\r\n</html>', NULL, NULL, 'nl', 'ke-pdf', NULL, '2023-11-27 09:07:13.152323', NULL);
INSERT IGNORE INTO `templates_reseller` (`Id`, `reseller_id`, `template_name`, `html_content`, `header_id`, `footer_id`, `language_code`, `CreatedBy`, `ModifiedBy`, `CreatedAt`, `ModifiedAt`) VALUES (50, 197, 'FINALBILL_TEMPLATE_CANCELATION_FEE_HOURLY', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n\r\n<head>\r\n    <title>Billing | Kikker</title>\r\n    <meta charset=\"utf-8\">\r\n    <link rel=\"icon\" href=\"asset/kikker-icon.ico\" />\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\r\n    <link rel=\"stylesheet\" href=\"https://storage.googleapis.com/kikkerprodbucket/static-files/pdf-css/site.css\">\r\n    <link rel=\"stylesheet\" href=\"https://storage.googleapis.com/kikkerprodbucket/static-files/pdf-css/final_bill.css\">\r\n</head>\r\n<body>\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div class=\"row header mr-0 ml-0\">\r\n                    <div style=\"width: 33%;\">\r\n                    </div>\r\n                    <div class=\"[hide-header-invoice-info] header-invoice-info\">\r\n                        <div class=\"d-flex justify-content-end\">\r\n                            <div class=\"space-span d-inline-block\" style=\"padding-top: 0\">\r\n                                <div class=\"mb-0 d-flex\">\r\n                                    <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\">Klantnummer:</p>\r\n                                    <p class=\"mb-0\">[client_number]</p>\r\n                                </div>\r\n                                <div class=\"mb-0 d-flex\">\r\n                                    <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\"\r\n                                        >Contractnummer:\r\n                                    </p>\r\n                                    <p class=\"mb-0\">[contract_number]</p>\r\n                                </div>\r\n                                <div class=\"mb-0 d-flex [hidden_contract_reference]\" style=\"flex-flow: row;\">\r\n                                    <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\">Contractreferentie: </p>\r\n                                    <p class=\"mb-0\">[contract_reference]</p>\r\n                                </div>\r\n                                <div class=\"mb-0 d-flex\">\r\n                                    <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\"\r\n                                        >Factuurnummer:\r\n                                    </p>\r\n                                    <p class=\"mb-0\">[invoice_number]</p>\r\n                                </div>\r\n                                <div class=\"mb-0 d-flex [company_name_visible]\" style=\"flex-flow: row;\">\r\n                                    <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\">Bedrijfsnaam: </p>\r\n                                    <p class=\"mb-0\">[company_name]</p>\r\n                                </div>\r\n                                <div class=\"mb-0 d-flex\" style=\"flex-flow: row;\">\r\n                                    <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\">Energie intermediair: </p>\r\n                                    <p class=\"mb-0\">[header_reseller_name]</p>\r\n                                </div>\r\n                                <div class=\"mb-0 d-flex\">\r\n                                    <p class=\"text-right vertical-align-top pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\"\r\n                                        >Leveringsadres:</p\r\n                                    >\r\n                                    <p class=\"mb-0\" class=\"d-inline-block\"\r\n                                        >[delivery_address_street] [delivery_address_houseNr] [delivery_address_zipcode]<br><span class=\"text-capitalize\">[delivery_address_city]</span></p\r\n                                    >\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n                <div class=\"row\">\r\n                    <div class=\"col-12\">\r\n                        <p class=\"mb-0\">\r\n                            <span class=\"float-right\">[date_generate_PDF]</span>\r\n                        </p>\r\n                        <p class=\"mt-5 mb-4\">Beste [customer_first_name],</p>\r\n                        <p class=\"mb-4 [final_bill_visible]\">Dit is je eindafrekening over de verbruiksperiode van\r\n                            [final_bill_start_date] tot [final_bill_end_date] voor je leveringsadres\r\n                            [delivery_address_street] [delivery_address_houseNr] te <span\r\n                                class=\"text-capitalize\">[delivery_address_city]</span>. Je ontvangt deze afrekening\r\n                            omdat je contract met [reseller_name] eindigt. In deze eindafrekening berekenen we de kosten\r\n                            tot de einddatum van je contract. Indien je onlangs een nieuw [reseller_name]-contract hebt\r\n                            afgesloten, ontvang je hier apart bericht van. </p>\r\n                        <p class=\"mb-4 [yearly_bill_visible]\">Dit is je jaarafrekening over de verbruiksperiode van\r\n                            [final_bill_start_date] tot [final_bill_end_date] voor je leveringsadres\r\n                            [delivery_address_street] te <span class=\"text-capitalize\">[delivery_address_city]</span>.\r\n                            In deze jaarafrekening vind je een overzicht van je energieverbruik in het afgelopen jaar en\r\n                            wat je hiervoor hebt betaald. </p>\r\n                    </div>\r\n                </div>\r\n                [FINALBILL_TEMPLATE_UNPAID_AMOUNT_INVOICE_ITEM]\r\n                [FINALBILL_TEMPLATE_PAID_AMOUNT_INVOICE_ITEM]\r\n                <div>\r\n                    <p class=\"mb-1 font-weight-bold [yearly_bill_visible] [new_monthly_amount_visible]\"> Je nieuwe\r\n                        termijnbedrag </span>\r\n                    </p>\r\n                    <p class=\"mb-4 [yearly_bill_visible] [new_monthly_amount_visible]\"> Op basis van je verbruik in de\r\n                        afgelopen 12 maanden, hebben we een nieuw termijnbedrag voor je uitgerekend. We passen het\r\n                        termijnbedrag automatisch voor je aan. Ben je het niet eens met je nieuwe termijnbedrag? Dan kun\r\n                        je dit gemakkelijk aanpassen in onze mobiele app. </p>\r\n                </div>\r\n                <div class=\"row monthly-amount-block [yearly_bill_visible] [new_monthly_amount_visible] mt-4\"\r\n                    style=\"background-image: url(\'data:image/png;base64,\');background-size: 100%; background-repeat: no-repeat; background-position: center center;\">\r\n                    <div class=\"col-6\">\r\n                        <span> Oude termijnbedrag </span>\r\n                        <span class=\"float-right\"> € [current_monthly_amount] </span>\r\n                    </div>\r\n                    <div class=\"col-6 pl-5 font-weight-bold\">\r\n                        <span> Nieuwe termijnbedrag </span>\r\n                        <span class=\"float-right\"> € [new_monthly_amount] </span>\r\n                    </div>\r\n                </div>\r\n                <div class=\"mt-4\">\r\n                    <p class=\"font-weight-bold mb-1\">Vragen?</p>\r\n                    <p class=\"mb-3\">Je kunt altijd contact met ons opnemen via [reseller_email] of bellen naar\r\n                        [reseller_phone].</p>\r\n                    <p class=\"mb-3\">Met vriendelijke groet, </p>\r\n                    <p class=\"mb-0\">[reseller_name]</p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div class=\"row\">\r\n                    <div class=\"col-12\">\r\n                        <p>Meer informatie over je verbruik of de precieze berekening van je <span class=\"[final_bill_visible]\">eindafrekening</span> <span class=\"[yearly_bill_visible]\">jaarafrekening</span> vind je op de volgende pagina’s.</p>\r\n                        <p class=\"mb-1 font-weight-bold\">Samenvatting van je <span\r\n                                class=\"[final_bill_visible]\">eindafrekening</span>\r\n                            <span class=\"[yearly_bill_visible]\">jaarafrekening</span>\r\n                        </p>\r\n                    </div>\r\n                </div>\r\n                <div class=\"[hide_text_summary]\">[text_summary]</div>\r\n                <div class=\"mt-5 table-first\">\r\n                    <table class=\"table\">\r\n                        <tbody>\r\n                            <tr>\r\n                                <td class=\"pl-2\"> 1. Leveringskosten van [product_type] </td>\r\n                                <td class=\"pl-2 text-right\">[total_delivery_amount]</td>\r\n                            </tr>\r\n                            <tr class=\"[show_price_cap_billing]\">\r\n                                <td class=\"pl-2\"> 2. Tegemoetkoming uit het prijsplafond</td>\r\n                                <td class=\"pl-2 text-right\">[total_price_cap]</td>\r\n                              </tr>\r\n                            <tr>\r\n                                <td class=\"pl-2 [hide_price_cap_billing]\">2. Overheidsheffingen op [product_type], dit dragen we af aan de overheid</td>\r\n                                <td class=\"pl-2 [show_price_cap_billing]\">3. Overheidsheffingen op [product_type], dit dragen we af aan de overheid</td>\r\n                                <td class=\"pl-2 text-right\">[total_tax_amount]</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <td class=\"pl-2 [hide_price_cap_billing]\">3. Netbeheerkosten op [product_type], dit dragen we af aan je netbeheerder</td>\r\n                                <td class=\"pl-2 [show_price_cap_billing]\">4. Netbeheerkosten op [product_type], dit dragen we af aan je netbeheerder</td>\r\n                                <td class=\"pl-2 text-right\">[total_grid_operator_amount]</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <td class=\"pl-2 [hide_price_cap_billing]\">4. Opzegboete voor tussentijdse opzegging</td>\r\n                                <td class=\"pl-2 [show_price_cap_billing]\">5. Opzegboete voor tussentijdse opzegging</td>\r\n                                <td class=\"pl-2 text-right\">[cancelation_fee]</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <td class=\"pl-2 font-weight-bold\"></td>\r\n                                <td class=\"pl-2 text-right  font-weight-bold\">[total_real_amount_incl_cancel_fee]</td>\r\n                            </tr>\r\n                        </tbody>\r\n                    </table>\r\n                </div>\r\n                <div class=\"mt-4 table-first\">\r\n                    <table class=\"table\">\r\n                        <tbody>\r\n                            <tr>\r\n                                <td class=\"pl-2 [hide_price_cap_billing]\">5. In rekening gebrachte termijnbedragen </td>\r\n                                <td class=\"pl-2 [show_price_cap_billing]\">6. In rekening gebrachte termijnbedragen </td>\r\n                                <td class=\"pl-2 text-right\">[total_generated_amount_negative]</td>\r\n                            </tr>\r\n                            <tr class=\"[total_unpaid_amount_class]\">\r\n                                <td class=\"pl-4 font-italic\"> Openstaande termijnbedragen </td>\r\n                                <td class=\"pl-2 text-right\">[total_unpaid_amount]</td>\r\n                            </tr>\r\n                            <tr class=\"[total_collection_cost_amount_class]\">\r\n                                <td class=\"pl-4 font-italic\"> Openstaande incassokosten </td>\r\n                                <td class=\"pl-2 text-right\">[total_collection_cost_amount]</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <td class=\"pl-2 font-weight-bold\"></td>\r\n                                <td class=\"pl-2 text-right  font-weight-bold\">[total_real_generated_amount_negative]\r\n                                </td>\r\n                            </tr>\r\n                        </tbody>\r\n                    </table>\r\n                    <table>\r\n                        <tbody>\r\n                            <tr>\r\n                                <td style=\"height: 15px;\"></td>\r\n                            </tr>\r\n                            <tr>\r\n                                <td class=\"w-100\"></td>\r\n                                <td class=\"pl-2 text-right font-weight-bold text-nowrap t-nowrap\">\r\n                                    <div class=\"border-top-bold position-relative\">\r\n                                        <span class=\"pr-5\">[is_receive]</span>\r\n                                        <span>€ [difference_amount]</span>\r\n                                    </div>\r\n                                </td>\r\n                            </tr>\r\n                        </tbody>\r\n                    </table>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div class=\"[usage_only_gas_elk_visible]\">\r\n                    <p class=\"mb-1 font-weight-bold\"> Berekening van je verbruik </p>\r\n                   <p class=\"mb-5\">\r\n            Je hebt een contract waarbij je dynamische tarieven betaalt [dynamic_based_on_type_of_product_in_contract]. Hierdoor berekenen we jouw verbruik door [dynamic_based_on_type_of_product_in_contract] het netto verbruik (verbruik minus eventuele teruglevering) bij elkaar op te tellen. In onderstaand overzicht zie je voor de volledigheid ook een overzicht van jouw meterstanden (en het daaruit resulterende verbruik) per periode.\r\n          </p>\r\n                </div>\r\n                <div class=\"mt-5 [usage_only_gas_elk_visible]\"> [usage_item_by_ean] </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    <div class=\"[usage_only_gas_elk_visible]\" style=\"page-break-before: always\"></div>\r\n    <div class=\"page [usage_both_gas_elk_visible]\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div>\r\n                    <p class=\"mb-1 font-weight-bold\"> Berekening van je verbruik </p>\r\n                    <p class=\"mb-5\">\r\n            Je hebt een contract waarbij je dynamische tarieven betaalt [dynamic_based_on_type_of_product_in_contract]. Hierdoor berekenen we jouw verbruik door [dynamic_based_on_type_of_product_in_contract] het netto verbruik (verbruik minus eventuele teruglevering) bij elkaar op te tellen. In onderstaand overzicht zie je voor de volledigheid ook een overzicht van jouw meterstanden (en het daaruit resulterende verbruik) per periode.\r\n          </p>\r\n                </div>\r\n                <div class=\"mt-5\"> [usage_item_by_ean] </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    <div class=\"[usage_both_gas_elk_visible]\" style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div>\r\n                    <p class=\"mb-4\">Op de volgende pagina’s vind je een nadere specificatie van de kosten die\r\n                        weergegeven zijn op pagina 2.</p>\r\n                    [return_tariff_section]\r\n                    <p class=\"mb-1 font-weight-bold\">1. Leveringskosten voor [product_type]</p>\r\n                              <p class=\"mb-1\">\r\n            Met jouw contract betaal je dynamische tarieven. Omdat wij niet alle tarieven per uur/dag op de <span class=\"[final_bill_visible]\">eindafrekening</span> <span class=\"[yearly_bill_visible]\">jaarafrekening</span> kunnen tonen, berekenen wij eerst jouw gewogen gemiddelde tarief per maand door jouw verbruik per uur/dag te vermenigvuldigen met de uur/dagprijs en dit vervolgens te delen door jouw verbruik in de maand. Zo kunnen we een helder tarief tonen op de <span class=\"[final_bill_visible]\">eindafrekening</span> <span class=\"[yearly_bill_visible]\">jaarafrekening</span>, maar betaal je alsnog gewoon de uur/dagprijs.\r\n          </p>\r\n          <p class=\"mb-5\">\r\n            Een specificatie van hoe wij jouw gewogen gemiddelde tarief berekenen vind je terug in de Mijn [reseller_name] Online.\r\n          </p>\r\n                </div>\r\n                <div class=\"table_fixed_delivery\"> [fixed_delivery_item_dynamic_page] </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n\r\n    [price_cap_section_template]\r\n\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div class=\"row\">\r\n                    <div class=\"col-12\">\r\n                        <p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">2. Overheidsheffingen op [product_type]</p>\r\n                        <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">3. Overheidsheffingen op [product_type]</p>\r\n                        <p style=\"display: [show_new_ode_tax_description]\">Naast de kosten voor het verbruik van\r\n                            [product_type], moet je ook belastingen betalen aan de overheid. Ook deze zijn afhankelijk\r\n                            van je verbruik. Onderstaande kosten dragen wij direct af aan de overheid. Omdat de\r\n                            heffingen jaarlijks (per 1 januari) veranderen zie je onderstaand mogelijk twee\r\n                            berekeningen: een voor de periode vóór en een voor de periode ná 1 januari.</p>\r\n                    </div>\r\n                </div>\r\n                <div class=\"mt-3\"> [tax_item_dynamic_page] </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div class=\"row\">\r\n                    <div class=\"col-12\">\r\n                        <p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">3. Netbeheerkosten voor [product_type]</p>\r\n                        <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">4. Netbeheerkosten voor [product_type]</p>\r\n                        <p class=\"mb-3\">Om van [product_type] gebruik te kunnen maken, dien je aangesloten te zijn op\r\n                            het openbare [product_type]netwerk van je netbeheerder. Hiervoor betaal je een vaste\r\n                            vergoeding die afhankelijk is van je aansluiting. Wij dragen deze vervolgens weer af aan je\r\n                            netbeheerder. Ook hier geldt dat de tarieven jaarlijks per 1 januari wijzigen. Om deze reden\r\n                            zie je onderstaand mogelijk weer twee berekeningen: voor de periode vóór en de periode ná 1\r\n                            januari. </p>\r\n                        <p> Je netbeheerder: <strong>[grid_operator_name]</strong>\r\n                        </p>\r\n                    </div>\r\n                </div>\r\n                <div class=\"mt-3 custom-table table_grid_operator\"> [grid_operator_item_dynamic_page] </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div class=\"row\">\r\n                    <div class=\"col-12\">\r\n                        <p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">4. Opzegboete voor tussentijdse opzegging</p>\r\n                        <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">5. Opzegboete voor tussentijdse opzegging</p>\r\n                        <p>Dit contract had een looptijd voor <span\r\n                                style=\"text-transform: lowercase;\">[contract_duration]</span>, maar is na\r\n                            [day_active_in_our_system] dagen opgezegd. Conform de afgesproken voorwaarden, wordt bij\r\n                            opzegging gedurende de vaste looptijd van het contract een opzegboete in rekening gebracht.\r\n                            Deze opzegboete is afhankelijk van de resterende looptijd van het contract en geldt per\r\n                            product ([product_type]). Voor een resterende looptijd van [remaning_days], bedraagt de\r\n                            opzegboete € [cancelation_fee_summary] per product. Hierbij houden we ons aan de richtlijnen\r\n                            van de Autoriteit Consument en Markt. </p>\r\n                    </div>\r\n                </div>\r\n                <div class=\"mt-5\">\r\n                    <table class=\"table table-custom [cancellation_fee_visible]\">\r\n                        <thead>\r\n                            <th class=\"pl-2 text-uppercase\">OPZEGBOETE VOOR CONTRACT MET RESTERENDE LOOPTIJD MEER DAN\r\n                                [contract_duration_title]</th>\r\n                            <th class=\"pl-2 text-right\">BEDRAG</th>\r\n                        </thead>\r\n                        <tbody>\r\n                            <tr class=\"[cancellation_fee_elk_visible]\">\r\n                                <td class=\"pl-2\"> Opzegboete stroom </td>\r\n                                <td class=\"pl-2 text-right\">€ [cancelation_fee_elk]</td>\r\n                            </tr>\r\n                            <tr class=\"[cancellation_fee_gas_visible]\">\r\n                                <td class=\"pl-2\"> Opzegboete gas </td>\r\n                                <td class=\"pl-2 text-right\">€ [cancelation_fee_gas]</td>\r\n                            </tr>\r\n                        </tbody>\r\n                    </table>\r\n                    <table>\r\n                        <tbody>\r\n                            <tr>\r\n                                <td style=\"height: 15px;\"></td>\r\n                            </tr>\r\n                            <tr>\r\n                                <td class=\"w-100\"></td>\r\n                                <td class=\"pl-2 text-right font-weight-bold text-nowrap t-nowrap\">\r\n                                    <div class=\"border-top-bold position-relative\">\r\n                                        <span class=\"pr-5\">Totaalbedrag opzegboete voor tussentijdse opzegging</span>\r\n                                        <span>€ [cancelation_fee_last_page]</span>\r\n                                    </div>\r\n                                </td>\r\n                            </tr>\r\n                        </tbody>\r\n                    </table>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n\r\n    <div style=\"page-break-before: always\"></div>\r\n\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div class=\"row\">\r\n                    <div class=\"col-12\">\r\n                    <p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">5. Totaal in rekening gebrachte termijnbedragen</p>\r\n                        <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">6. Totaal in rekening gebrachte termijnbedragen</p>\r\n                        <p>Hier zie je een overzicht van de door ons in rekening gebrachte termijnbedragen in de afgelopen periode (incl. btw). Een negatief termijnbedrag wordt als niet in rekening gebracht beschouwd en daarom als 0 weergegeven.</p>\r\n                    </div>\r\n                </div>\r\n                <div class=\"mt-5\">\r\n                    <table class=\"table table-custom\">\r\n                        <thead>\r\n                            <th class=\"pl-2 charge-item-month-column\">MAAND</th>\r\n                            <th class=\"pl-2 charge-item-invoice-number\">FACTUURNUMME</th>\r\n                            <th class=\"pl-2 text-right\" colspan=\"2\">BEDRAG</th>\r\n                        </thead>\r\n                        <tbody> [charged_item_by_month] </tbody>\r\n                    </table>\r\n                    <table>\r\n                        <tbody>\r\n                            <tr>\r\n                                <td style=\"height: 15px;\"></td>\r\n                            </tr>\r\n                            <tr>\r\n                                <td class=\"w-100\"></td>\r\n                                <td class=\"pl-2 text-right font-weight-bold text-nowrap t-nowrap\">\r\n                                    <div class=\"border-top-bold position-relative\">\r\n                                        <span class=\"pr-5\">Totaal in rekening gebrachte termijnbedragen</span>\r\n                                        <span>[total_generated_amount]</span>\r\n                                    </div>\r\n                                </td>\r\n                            </tr>\r\n                        </tbody>\r\n                    </table>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n\r\n    <div style=\"page-break-before: always\"></div>\r\n\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div class=\"space-span mt-2\">\r\n                    <p class=\"font-weight-bold\">Jouw EAN-codes</p> [elk_gas_eans]\r\n                </div>\r\n                <div class=\"mt-5\">\r\n                    <p class=\"font-weight-bold\">Btw-aangifte</p>\r\n                    <p class=\"mb-0\"> [reseller_name] handelt onder de leveranciersvergunning van Kikker Energie. In het\r\n                        geval je een btw-aangifte moet doen, dien je daarom de gegevens van Kikker Energie te gebruiken.\r\n                        De benodigde informatie van Kikker Energie en je netbeheerder vind je onderstaand: </p>\r\n                </div>\r\n                <div class=\"row mt-4\">\r\n                    <div class=\"col-5\">\r\n                        <p class=\"mb-0\">\r\n                            Kikker Energie B.V.</br>\r\n                            Tolnasingel 12 </br> 2411PV Bodegraven\r\n                        </p>\r\n                        <p class=\"mb-0\">KvK: 71246681</p>\r\n                        <p class=\"mb-0\">Btw nr.: NL858635732B01</p>\r\n                    </div>\r\n                    <div class=\"col-5\">\r\n                        <p class=\"mb-0\"> [grid_operator_name] </br> [grid_operator_house_nr] </br>\r\n                            [grid_operator_postcode] </p>\r\n                        <p class=\"mb-0\">KvK: [grid_operator_kvk]</p>\r\n                        <p class=\"mb-0\">Btw nr.: [grid_operator_btw]</p>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</body>\r\n\r\n</html>', NULL, NULL, 'nl', 'ke-pdf', NULL, '2023-11-27 09:07:13.152323', NULL);
INSERT IGNORE INTO `templates_reseller` (`Id`, `reseller_id`, `template_name`, `html_content`, `header_id`, `footer_id`, `language_code`, `CreatedBy`, `ModifiedBy`, `CreatedAt`, `ModifiedAt`) VALUES (57, 197, 'FINALBILL_TEMPLATE_CHARGED_ITEM', '<tr class=\"green-background\">\r\n  <td class=\"pl-2 charge-item-month-column\"> [charge_item_month] </td>\r\n  <td class=\"pl-2 charge-item-invoice-number\"> [charge_item_invoice_number] </td>\r\n  <td class=\"pl-2 text-right\" style=\"padding-bottom: 0px\">\r\n    <span class=\"[tag_collection_cost_invoice_class]\" style=\"background: #f5d3d5;border: 1px solid #ecc4c7; \r\n                    padding: 0px 10px 1px 10px; \r\n                    border-radius: 7px; \r\n                    font-weight: 500;\r\n                    margin-left: 5px;\r\n                    margin-bottom: 4.8px;\r\n                    color: #7d3f48;\r\n                    display: inline-block;\">incassokosten</span>\r\n                    \r\n    <span class=\"[tag_credit_invoice_class]\" style=\"background: #C1E1F3;border: 1px solid #acd6ee; \r\n                    padding: 0px 10px 1px 10px; \r\n                    border-radius: 7px; \r\n                    font-weight: 500;\r\n                    margin-left: 5px;\r\n                    margin-bottom: 4.8px;\r\n                    color: #1658a6;\r\n                    display: inline-block;\">credit</span>\r\n    <span class=\"[tag_unpaid_invoice_class]\" style=\"background: #FFF1C9;border: 1px solid #f8d2a2; \r\n                    padding: 0px 10px 1px 10px; \r\n                    border-radius: 7px; \r\n                    font-weight: 500;\r\n                    margin-left: 5px;\r\n                    margin-bottom: 4.8px;\r\n                    color: #C1822F;\r\n                    display: inline-block;\">nog niet voldaan</span>\r\n    <span class=\"[tag_payment_agreemment_invoice_class]\" style=\"background: #FFF1C9;border: 1px solid #f8d2a2; \r\n                    padding: 0px 10px 1px 10px; \r\n                    border-radius: 7px; \r\n                    font-weight: 500;\r\n                    margin-left: 5px;\r\n                    margin-bottom: 4.8px;\r\n                    color: #C1822F;\r\n                    display: inline-block;\">betalingsregeling</span>\r\n    <span class=\"[tag_subsidy_invoice_class]\" style=\"background: #FFF1C9;border: 1px solid #f8d2a2; \r\n                  padding: 0px 10px 1px 10px; \r\n                  border-radius: 7px; \r\n                  font-weight: 500;\r\n                  margin-left: 5px;\r\n                  margin-bottom: 4.8px;\r\n                  color: #C1822F;\r\n                  display: inline-block;\">Energiecompensatie &nbsp;[tag_subsidy_invoice_amount]</span>\r\n  </td>\r\n  <td class=\"pl-2 text-right\" style=\"min-width: 90px; width: 90px\">\r\n    <span style=\"white-space: nowrap;\">[charge_item_amount] </span>\r\n  </td>\r\n</tr>', NULL, NULL, 'nl', 'ke-pdf', NULL, '2023-11-27 09:07:13.152323', NULL);
INSERT IGNORE INTO `templates_reseller` (`Id`, `reseller_id`, `template_name`, `html_content`, `header_id`, `footer_id`, `language_code`, `CreatedBy`, `ModifiedBy`, `CreatedAt`, `ModifiedAt`) VALUES (64, 197, 'FINALBILL_TEMPLATE_EANS', '<p class=\"mb-0 d-flex ean-code\">\r\n                    <span class=\"d-inline-block pr-3\">[product_type]:</span>\r\n                    <span>[ean]</span>\r\n                </p> ', NULL, NULL, 'nl', 'ke-pdf', NULL, '2023-11-27 09:07:13.152323', NULL);
INSERT IGNORE INTO `templates_reseller` (`Id`, `reseller_id`, `template_name`, `html_content`, `header_id`, `footer_id`, `language_code`, `CreatedBy`, `ModifiedBy`, `CreatedAt`, `ModifiedAt`) VALUES (71, 197, 'FINALBILL_TEMPLATE_FIXED_DELIVERY', '<tr class=\"[fixed_delivery_item_detail]\">\r\n    <td class=\"pl-2\">\r\n        [fixed_delivery_item_name]\r\n    </td>\r\n    <td class=\"pl-2\">[fixed_delivery_usage] [product_type_unit]</td>\r\n    <td class=\"pl-2\">[fixed_delivery_tariff]</td>\r\n    <td class=\"pl-2 text-right\">[fixed_delivery_amount]</td>\r\n</tr>\r\n\r\n<tr style=\"background-color: transparent !important\" class=\"background-none [fixed_delivery_item_total]\">\r\n    <td style=\"background-color: transparent !important\" class=\"pl-2\"></td>\r\n    <td style=\"background-color: transparent !important\" class=\"pl-2\"></td>\r\n    <td style=\"background-color: transparent !important\" class=\"pl-2\"></td>\r\n    <td style=\"background-color: transparent !important\" class=\"pl-2 font-weight-bold text-right\">[fixed_delivery_total]</td>\r\n</tr>', NULL, NULL, 'nl', 'ke-pdf', NULL, '2023-11-27 09:07:13.152323', NULL);
INSERT IGNORE INTO `templates_reseller` (`Id`, `reseller_id`, `template_name`, `html_content`, `header_id`, `footer_id`, `language_code`, `CreatedBy`, `ModifiedBy`, `CreatedAt`, `ModifiedAt`) VALUES (78, 197, 'FINALBILL_TEMPLATE_FIXED_DELIVERY_DYNAMIC_PAGE', '<table class=\"table table-custom mb-0 table_fixed_delivery\">\r\n  <thead class=\"[fixed_delivery_item_header_visible]\">\r\n    <th class=\"pl-2 th-elk text-nowrap\" style=\"overflow: visible !important;background-color: transparent !important\"> [reseller_name] [is_green_energy] [product_type] [reseller_name] [contract_duration] <span class=\"[multil_ean_number_visible]\">\r\n        <br>EAN [multil_ean_number] </span>\r\n      <br> ([start_date] / [end_date]) | [fixed_delivery_btw]% BTW\r\n    </th>\r\n    <th class=\"pl-2 text-right\" style=\"vertical-align: bottom;overflow: visible !important;background-color: transparent !important\">\r\n      <br>\r\n      <span class=\"float-left\">AANTAL</span>\r\n      <span class=\"d-inline-block pr-4\">x</span>\r\n    </th>\r\n    <th class=\"pl-2 text-right\" style=\"vertical-align: bottom;background-color: transparent !important\">\r\n      <span class=\"float-left\">TARIEF</span>\r\n      <br>\r\n      <span class=\"float-left\">EXCL. BTW</span>\r\n      <span class=\"d-inline-block pr-4\">=</span>\r\n    </th>\r\n    <th class=\"pl-2 text-right\" style=\"vertical-align: bottom;\">BEDRAG <br> EXCL. BTW </th>\r\n  </thead>\r\n  <tbody> [fixed_delivery_item] <tr class=\"[fixed_delivery_item_total_visible] tr-total-vat\">\r\n      <td colspan=\"5\">\r\n        <div class=\"text-right\" style=\"margin-right: -4px;\">\r\n          <div class=\"text-nowrap\"> Subtotaal <span class=\"d-inline-block\" style=\"width: 140px;\"> [delivery_sub_total] </span>\r\n          </div>\r\n          <div class=\"text-tax-color text-nowrap [hide_delivery_vat_1]\"> btw [delivery_btw_1]% over [delivery_net_month_1] <span class=\"d-inline-block\" style=\"width: 140px;\"> [delivery_btw_amount_1] </span>\r\n          </div>\r\n          <div class=\"text-tax-color text-nowrap [hide_delivery_vat_2]\"> btw [delivery_btw_2]% over [delivery_net_month_2] <span class=\"d-inline-block\" style=\"width: 140px;\"> [delivery_btw_amount_2] </span>\r\n          </div>\r\n          <div class=\"d-inline-block border-top-bold-td text-nowrap font-weight-bold\"> Totaalbedrag voor leveringskosten voor [total_product_type] <span class=\"d-inline-block\" style=\"width: 140px;\"> [fixed_delivery_total] </span>\r\n          </div>\r\n        </div>\r\n      </td>\r\n    </tr>\r\n  </tbody>\r\n</table>', NULL, NULL, 'nl', 'ke-pdf', NULL, '2023-11-27 09:07:13.152323', NULL);
