INSERT IGNORE INTO `templates_reseller` (`Id`, `reseller_id`, `template_name`, `html_content`, `header_id`, `footer_id`, `language_code`, `CreatedBy`, `ModifiedBy`, `CreatedAt`, `ModifiedAt`) VALUES (120, 197, 'FINALBILL_TEMPLATE_FOOTER', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n\r\n<head>\r\n  <title>Billing | Kikker</title>\r\n  <meta charset=\"utf-8\">\r\n  <link rel=\"icon\" href=\"asset/kikker-icon.ico\" />\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\r\n  <link rel=\"stylesheet\" href=\"https://storage.googleapis.com/kikkerprodbucket/static-files/pdf-css/site.css\">\r\n</head>\r\n\r\n<style>\r\n    .footer {\r\n        position: relative;\r\n        max-width: 100% !important;\r\n        width: 620px;\r\n        height: 75px;\r\n        margin-bottom: 18px;\r\n    }\r\n\r\n    .footer * {\r\n        font-size: 12px;\r\n        white-space: nowrap;\r\n    }\r\n\r\n    .footer-paging {\r\n        position: absolute;\r\n        bottom: 70px;\r\n        right: -95px;\r\n        transform: rotate(270deg);\r\n        width: 90px;\r\n        color: #7b7889;\r\n    }\r\n\r\n    .reseller-logo {\r\n        max-width: 80px;\r\n        max-height: 80px;\r\n    }\r\n\r\n    .reseller-logo img {\r\n        max-width: 80px;\r\n        max-height: 80px;\r\n    }\r\n\r\n    .footer-info {\r\n        display: flex;\r\n        flex-direction: row;\r\n        width: 630px;\r\n        align-items: end;\r\n        line-height: 1.3;\r\n        margin-top: 13px;\r\n    }\r\n    \r\n    .font-weight-bold {\r\n        font-weight:700!important\r\n    }\r\n</style>\r\n\r\n<body>\r\n    <div class=\"[hide_footer] footer\">\r\n        <div class=\"[hide_footer_reseler] footer-info\">\r\n            <div style=\"width: 24%;\">\r\n                <div>\r\n                    <span class=\"font-weight-bold\">[footer_reseller_name]</span><br>\r\n                    [footer_reseller_contact_street] [footer_reseller_contact_house_number] [footer_reseller_contact_house_number_extension]<br>\r\n                    [footer_reseller_contact_zipcode] [footer_reseller_contact_city]\r\n                </div>\r\n            </div>\r\n            <div class=\"row mx-0 pr-3\" style=\"width: 47%;\">\r\n                <div class=\"d-flex align-items-end text-left font-weight-bold\" style=\"width: 35px;\">KvK<br>BTW</div>\r\n                <div class=\"d-flex align-items-end text-left\" style=\"width: calc(100% - 40px);\">[footer_reseller_kvk]<br>[footer_reseller_btw]</div>\r\n            </div>\r\n            <div class=\"row mx-0 pr-3\">\r\n                <div class=\"font-weight-bold\" style=\"width: 43px;\">Tel<br>E-mail</div>\r\n                <div style=\"width: calc(100% - 55px);\">[footer_reseller_contact_phone]<br>[footer_reseller_contact_email]</div>\r\n            </div>\r\n        </div>\r\n        <div class=\"footer-paging\">\r\n            [page_number] van [total_page]\r\n        </div>\r\n    </div>\r\n</body>\r\n\r\n</html>', NULL, NULL, 'nl', 'ke-pdf', NULL, '2023-11-27 09:07:13.152323', NULL);
INSERT IGNORE INTO `templates_reseller` (`Id`, `reseller_id`, `template_name`, `html_content`, `header_id`, `footer_id`, `language_code`, `CreatedBy`, `ModifiedBy`, `CreatedAt`, `ModifiedAt`) VALUES (127, 197, 'FINALBILL_TEMPLATE_GRID_OPERATOR_COST', '<tr>\r\n    <td class=\"pl-2\">\r\n        [grid_operator_name]\r\n    </td>\r\n    <td class=\"pl-2\">[grid_operator_by_ean_usage] dagen</td>\r\n    <td class=\"pl-2\">€ [grid_operator_by_ean_tariff]</td>\r\n    <td class=\"pl-2 text-right text-nowrap\">€ [grid_operator_by_ean_amount]</td>\r\n</tr>\r\n<tr style=\"background-color: transparent !important;\" class=\"background-none\">\r\n    <td style=\"background-color: transparent !important;\" class=\"pl-2\"></td>\r\n    <td style=\"background-color: transparent !important;\" class=\"pl-2\"></td>\r\n    <td style=\"background-color: transparent !important;\" class=\"pl-2\"></td>\r\n    <td style=\"background-color: transparent !important;\" class=\"pl-2 font-weight-bold text-right text-nowrap\">€ [grid_operator_by_ean_total]</td>\r\n</tr>\r\n', NULL, NULL, 'nl', 'ke-pdf', NULL, '2023-11-27 09:07:13.152323', NULL);
INSERT IGNORE INTO `templates_reseller` (`Id`, `reseller_id`, `template_name`, `html_content`, `header_id`, `footer_id`, `language_code`, `CreatedBy`, `ModifiedBy`, `CreatedAt`, `ModifiedAt`) VALUES (134, 197, 'FINALBILL_TEMPLATE_GRID_OPERATOR_COST_DYNAMIC_PAGE', '<table class=\"table table-custom mb-0\" cellspacing=\"0\" cellpadding=\"0\">\r\n  <thead>\r\n    <th class=\"pl-2\"> NETBEHEERKOSTEN VOOR [product_type] <span class=\"[multil_ean_number_visible]\">\r\n        <br>EAN[multil_ean_number] </span>\r\n      <br>\r\n      <span>([start_date] / [end_date]) | [vat]% BTW</span>\r\n    </th>\r\n    <th class=\"pl-2 text-right\" style=\"vertical-align: bottom;\">\r\n      <br>\r\n      <span class=\"float-left\">AANTAL</span>\r\n      <span class=\"d-inline-block pr-4\">x</span>\r\n    </th>\r\n    <th class=\"pl-2 text-right\" style=\"vertical-align: bottom;\">\r\n      <span class=\"float-left\">TARIEF</span>\r\n      <br>\r\n      <span class=\"float-left\">EXCL. BTW</span>\r\n      <span class=\"d-inline-block pr-4\">=</span>\r\n    </th>\r\n    <th class=\"pl-2 text-right\" style=\"vertical-align: bottom;\"> BEDRAG <br> EXCL. BTW </th>\r\n  </thead>\r\n  <tbody> [grid_operator_item] <tr class=\"[grid_operator_item_total_visible] tr-total-vat\">\r\n      <td colspan=\"4\">\r\n        <div class=\"text-right\" style=\"margin-right: -4px;\">\r\n          <div class=\"text-nowrap\"> Subtotaal <span class=\"d-inline-block\" style=\"width: 140px;\"> [sub_total] </span>\r\n          </div>\r\n          <div class=\"text-tax-color text-nowrap [hide_vat_1]\"> btw [btw_1]% over [net_month_1] <span class=\"d-inline-block\" style=\"width: 140px;\"> [btw_amount_1] </span>\r\n          </div>\r\n          <div class=\"text-tax-color text-nowrap [hide_vat_2]\"> btw [btw_2]% over [net_month_2] <span class=\"d-inline-block\" style=\"width: 140px;\"> [btw_amount_2] </span>\r\n          </div>\r\n          <div class=\"d-inline-block border-top-bold-td text-nowrap font-weight-bold\"> Totaalbedrag voor netbeheerkosten voor [total_product_type] <span class=\"d-inline-block\" style=\"width: 140px;\"> [grid_operator_total] </span>\r\n          </div>\r\n        </div>\r\n      </td>\r\n    </tr>\r\n  </tbody>\r\n</table>', NULL, NULL, 'nl', 'ke-pdf', NULL, '2023-11-27 09:07:13.152323', NULL);
INSERT IGNORE INTO `templates_reseller` (`Id`, `reseller_id`, `template_name`, `html_content`, `header_id`, `footer_id`, `language_code`, `CreatedBy`, `ModifiedBy`, `CreatedAt`, `ModifiedAt`) VALUES (148, 197, 'FINALBILL_TEMPLATE_HOURLY', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n\r\n<head>\r\n    <title>Billing | Kikker</title>\r\n    <meta charset=\"utf-8\">\r\n    <link rel=\"icon\" href=\"asset/kikker-icon.ico\" />\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\r\n    <link rel=\"stylesheet\" href=\"https://storage.googleapis.com/kikkerprodbucket/static-files/pdf-css/site.css\">\r\n    <link rel=\"stylesheet\" href=\"https://storage.googleapis.com/kikkerprodbucket/static-files/pdf-css/final_bill.css\">\r\n</head>\r\n<body>\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div class=\"row header mr-0 ml-0\">\r\n                    <div style=\"width: 33%;\">\r\n                    </div>\r\n                    <div class=\"[hide-header-invoice-info] header-invoice-info\">\r\n                        <div class=\"d-flex justify-content-end\">\r\n                            <div class=\"space-span d-inline-block\" style=\"padding-top: 0\">\r\n                                <div class=\"mb-0 d-flex\">\r\n                                    <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\">Klantnummer:</p>\r\n                                    <p class=\"mb-0\">[client_number]</p>\r\n                                </div>\r\n                                <div class=\"mb-0 d-flex\">\r\n                                    <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\"\r\n                                        >Contractnummer:\r\n                                    </p>\r\n                                    <p class=\"mb-0\">[contract_number]</p>\r\n                                </div>\r\n                                <div class=\"mb-0 d-flex [hidden_contract_reference]\" style=\"flex-flow: row;\">\r\n                                    <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\">Contractreferentie: </p>\r\n                                    <p class=\"mb-0\">[contract_reference]</p>\r\n                                </div>\r\n                                <div class=\"mb-0 d-flex\">\r\n                                    <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\"\r\n                                        >Factuurnummer:\r\n                                    </p>\r\n                                    <p class=\"mb-0\">[invoice_number]</p>\r\n                                </div>\r\n                                <div class=\"mb-0 d-flex [company_name_visible]\" style=\"flex-flow: row;\">\r\n                                    <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\">Bedrijfsnaam: </p>\r\n                                    <p class=\"mb-0\">[company_name]</p>\r\n                                </div>\r\n                                <div class=\"mb-0 d-flex\" style=\"flex-flow: row;\">\r\n                                    <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\">Energie intermediair: </p>\r\n                                    <p class=\"mb-0\">[header_reseller_name]</p>\r\n                                </div>\r\n                                <div class=\"mb-0 d-flex\">\r\n                                    <p class=\"text-right vertical-align-top pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\"\r\n                                        >Leveringsadres:</p\r\n                                    >\r\n                                    <p class=\"mb-0\" class=\"d-inline-block\"\r\n                                        >[delivery_address_street] [delivery_address_houseNr] [delivery_address_zipcode]<br><span class=\"text-capitalize\">[delivery_address_city]</span></p\r\n                                    >\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n                <div class=\"row\">\r\n                    <div class=\"col-12\">\r\n                        <p class=\"mb-5\">\r\n                            <span class=\"float-right\">[date_generate_PDF]</span>\r\n                        </p>\r\n                        <p class=\"mb-4\">Beste [customer_first_name],</p>\r\n                        <p class=\"mb-4 [final_bill_visible]\">Dit is je eindafrekening over de verbruiksperiode van\r\n                            [final_bill_start_date] tot [final_bill_end_date] voor je leveringsadres\r\n                            [delivery_address_street] [delivery_address_houseNr] te <span\r\n                                class=\"text-capitalize\">[delivery_address_city]</span>. Je ontvangt deze afrekening\r\n                            omdat je contract met [reseller_name] eindigt. In deze eindafrekening berekenen we de kosten\r\n                            tot de einddatum van je contract. Indien je onlangs een nieuw [reseller_name]-contract hebt\r\n                            afgesloten, ontvang je hier apart bericht van. </p>\r\n                        <p class=\"mb-4 [yearly_bill_visible]\">Dit is je jaarafrekening over de verbruiksperiode van\r\n                            [final_bill_start_date] tot [final_bill_end_date] voor je leveringsadres\r\n                            [delivery_address_street] [delivery_address_houseNr] te <span\r\n                                class=\"text-capitalize\">[delivery_address_city]</span>. In deze jaarafrekening vind je\r\n                            een overzicht van je energieverbruik in het afgelopen jaar en wat je hiervoor hebt betaald.\r\n                        </p>\r\n                    </div>\r\n                </div>\r\n                [FINALBILL_TEMPLATE_UNPAID_AMOUNT_INVOICE_ITEM]\r\n                [FINALBILL_TEMPLATE_PAID_AMOUNT_INVOICE_ITEM]\r\n                <div>\r\n                    <p class=\"mb-1 font-weight-bold [yearly_bill_visible] [new_monthly_amount_visible]\"> Je nieuwe\r\n                        termijnbedrag </span>\r\n                    </p>\r\n                    <p class=\"mb-4 [yearly_bill_visible] [new_monthly_amount_visible]\"> Op basis van je verbruik in de\r\n                        afgelopen 12 maanden, hebben we een nieuw termijnbedrag voor je uitgerekend. We passen het\r\n                        termijnbedrag automatisch voor je aan. Ben je het niet eens met je nieuwe termijnbedrag? Dan kun\r\n                        je dit gemakkelijk aanpassen in onze mobiele app. </p>\r\n                </div>\r\n                <div class=\"row monthly-amount-block [yearly_bill_visible] [new_monthly_amount_visible] mt-4\"\r\n                    style=\"background-image: url(\'data:image/png;base64,\');background-size: 100%; background-repeat: no-repeat; background-position: center center;\">\r\n                    <div class=\"col-6\">\r\n                        <span> Oude termijnbedrag </span>\r\n                        <span class=\"float-right\"> € [current_monthly_amount] </span>\r\n                    </div>\r\n                    <div class=\"col-6 pl-5 font-weight-bold\">\r\n                        <span> Nieuwe termijnbedrag </span>\r\n                        <span class=\"float-right\"> € [new_monthly_amount] </span>\r\n                    </div>\r\n                </div>\r\n                <div class=\"mt-4\">\r\n                    <p class=\"font-weight-bold mb-1\">Vragen?</p>\r\n                    <p class=\"mb-3\">Je kunt altijd contact met ons opnemen via [reseller_email] of bellen naar\r\n                        [reseller_phone]</p>\r\n                    <p class=\"mb-3\">Met vriendelijke groet, </p>\r\n                    <p class=\"mb-0\">[reseller_name]</p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n            <div>\r\n                <p>Meer informatie over je verbruik of de precieze berekening van je <span class=\"[final_bill_visible]\">eindafrekening</span> <span class=\"[yearly_bill_visible]\">jaarafrekening</span> vind je op de volgende pagina’s.</p>\r\n                <div class=\"mb-1 font-weight-bold\">Samenvatting van je <span\r\n                        class=\"[final_bill_visible]\">eindafrekening</span>\r\n                    <span class=\"[yearly_bill_visible]\">jaarafrekening</span>\r\n                </div>\r\n                <div class=\"[hide_text_summary]\">[text_summary]</div>\r\n                <div class=\"mt-5\">\r\n                    <table class=\"table table-first\">\r\n                        <tbody>\r\n                            <tr>\r\n                                <td class=\"pl-2\"> 1. Leveringskosten van [product_type] </td>\r\n                                <td class=\"pl-2 text-right\">[total_delivery_amount]</td>\r\n                            </tr>\r\n                            <tr class=\"[show_price_cap_billing]\">\r\n                                <td class=\"pl-2\"> 2. Tegemoetkoming uit het prijsplafond</td>\r\n                                <td class=\"pl-2 text-right\">[total_price_cap]</td>\r\n                              </tr>\r\n                            <tr>\r\n                                <td class=\"pl-2 [hide_price_cap_billing]\"> 2. Overheidsheffingen op [product_type], dit dragen we af aan de overheid </td>\r\n                                <td class=\"pl-2 [show_price_cap_billing]\"> 3. Overheidsheffingen op [product_type], dit dragen we af aan de overheid </td>\r\n                                <td class=\"pl-2 text-right\">[total_tax_amount]</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <td class=\"pl-2 [hide_price_cap_billing]\"> 3. Netbeheerkosten op [product_type], dit dragen we af aan je\r\n                                    netbeheerder</td>\r\n                                <td class=\"pl-2 [show_price_cap_billing]\"> 4. Netbeheerkosten op [product_type], dit dragen we af aan je\r\n                                    netbeheerder </td>\r\n                                <td class=\"pl-2 text-right\">[total_grid_operator_amount]</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <td class=\"pl-2 font-weight-bold\"></td>\r\n                                <td class=\"pl-2 text-right  font-weight-bold\">[total_real_amount_incl_cancel_fee]</td>\r\n                            </tr>\r\n                        </tbody>\r\n                    </table>\r\n                </div>\r\n                <div class=\"mt-5\">\r\n                    <table class=\"table table-first\">\r\n                        <tbody>\r\n                            <tr>\r\n                                <td class=\"pl-2 [hide_price_cap_billing]\"> 4. In rekening gebrachte termijnbedragen </td>\r\n                                <td class=\"pl-2 [show_price_cap_billing]\"> 5. In rekening gebrachte termijnbedragen </td>\r\n                                <td class=\"pl-2 text-right\">[total_generated_amount_negative]</td>\r\n                            </tr>\r\n                            <tr class=\"[total_unpaid_amount_class]\">\r\n                                <td class=\"pl-4 font-italic\"> Openstaande termijnbedragen </td>\r\n                                <td class=\"pl-2 text-right\">[total_unpaid_amount]</td>\r\n                            </tr>\r\n                            <tr class=\"[total_collection_cost_amount_class]\">\r\n                                <td class=\"pl-4 font-italic\"> Openstaande incassokosten </td>\r\n                                <td class=\"pl-2 text-right\">[total_collection_cost_amount]</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <td class=\"pl-2 font-weight-bold\"></td>\r\n                                <td class=\"pl-2 text-right  font-weight-bold\">[total_real_generated_amount_negative]\r\n                                </td>\r\n                            </tr>\r\n                        </tbody>\r\n                    </table>\r\n                    <table>\r\n                        <tbody>\r\n                            <tr>\r\n                                <td class=\"w-100\"></td>\r\n                                <td class=\"pl-2 text-right font-weight-bold text-nowrap t-nowrap\">\r\n                                    <div class=\"border-top-bold position-relative\">\r\n                                        <span class=\"pr-5\">[is_receive]</span>\r\n                                        <span>€ [difference_amount]</span>\r\n                                    </div>\r\n                                </td>\r\n                            </tr>\r\n                        </tbody>\r\n                    </table>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div class=\"[usage_only_gas_elk_visible]\">\r\n                    <p class=\"mb-1 font-weight-bold\"> Berekening van je verbruik </p>\r\n                           <p class=\"mb-5\">\r\n            Je hebt een contract waarbij je dynamische tarieven betaalt [dynamic_based_on_type_of_product_in_contract]. Hierdoor berekenen we jouw verbruik door [dynamic_based_on_type_of_product_in_contract] het netto verbruik (verbruik minus eventuele teruglevering) bij elkaar op te tellen. In onderstaand overzicht zie je voor de volledigheid ook een overzicht van jouw meterstanden (en het daaruit resulterende verbruik) per periode.\r\n          </p>\r\n                </div>\r\n                <div class=\"[usage_only_gas_elk_visible]\"> [usage_item_by_ean] </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    <div class=\"[usage_only_gas_elk_visible]\" style=\"page-break-before: always\"></div>\r\n    <div class=\"page [usage_both_gas_elk_visible]\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div>\r\n                    <p class=\"mb-1 font-weight-bold\"> Berekening van je verbruik </p>\r\n                       <p class=\"mb-5\">\r\n            Je hebt een contract waarbij je dynamische tarieven betaalt [dynamic_based_on_type_of_product_in_contract]. Hierdoor berekenen we jouw verbruik door [dynamic_based_on_type_of_product_in_contract] het netto verbruik (verbruik minus eventuele teruglevering) bij elkaar op te tellen. In onderstaand overzicht zie je voor de volledigheid ook een overzicht van jouw meterstanden (en het daaruit resulterende verbruik) per periode.\r\n          </p>\r\n                </div>\r\n                <div> [usage_item_by_ean] </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    <div class=\"[usage_both_gas_elk_visible]\" style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div>\r\n                    <p class=\"mb-4\">Op de volgende pagina’s vind je een nadere specificatie van de kosten die\r\n                        weergegeven zijn op pagina 2.</p>\r\n                    [return_tariff_section]\r\n                    <p class=\"mb-1 font-weight-bold\">1. Leveringskosten voor [product_type]</p>\r\n                     <p class=\"mb-1\">\r\n            Met jouw contract betaal je dynamische tarieven. Omdat wij niet alle tarieven per uur/dag op de <span class=\"[final_bill_visible]\">eindafrekening</span> <span class=\"[yearly_bill_visible]\">jaarafrekening</span> kunnen tonen, berekenen wij eerst jouw gewogen gemiddelde tarief per maand door jouw verbruik per uur/dag te vermenigvuldigen met de uur/dagprijs en dit vervolgens te delen door jouw verbruik in de maand. Zo kunnen we een helder tarief tonen op de <span class=\"[final_bill_visible]\">eindafrekening</span> <span class=\"[yearly_bill_visible]\">jaarafrekening</span>, maar betaal je alsnog gewoon de uur/dagprijs.\r\n          </p>\r\n          <p class=\"mb-5\">\r\n            Een specificatie van hoe wij jouw gewogen gemiddelde tarief berekenen vind je terug in de Mijn [reseller_name] Online.\r\n          </p>\r\n                </div>\r\n                <div class=\"table_fixed_delivery\"> [fixed_delivery_item_dynamic_page] </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n\r\n    [price_cap_section_template]\r\n\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div class=\"row\">\r\n                    <div class=\"col-12\">\r\n                        <p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">2. Overheidsheffingen op [product_type]</p>\r\n                        <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">3. Overheidsheffingen op [product_type]</p>\r\n                        <p style=\"display: [show_new_ode_tax_description]\">Naast de kosten voor het verbruik van\r\n                            [product_type], moet je ook belastingen betalen aan de overheid. Ook deze zijn afhankelijk\r\n                            van je verbruik. Onderstaande kosten dragen wij direct af aan de overheid. Omdat de\r\n                            heffingen jaarlijks (per 1 januari) veranderen zie je onderstaand mogelijk twee\r\n                            berekeningen: een voor de periode vóór en een voor de periode ná 1 januari.</p>\r\n                    </div>\r\n                </div>\r\n                <div class=\"mt-3\"> [tax_item_dynamic_page] </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div class=\"row\">\r\n                    <div class=\"col-12\">\r\n                        <p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">3. Netbeheerkosten voor [product_type]</p>\r\n                        <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">4. Netbeheerkosten voor [product_type]</p>\r\n                        <p class=\"mb-3\">Om van [product_type] gebruik te kunnen maken, dien je aangesloten te zijn op\r\n                            het openbare [product_type]netwerk van je netbeheerder. Hiervoor betaal je een vaste\r\n                            vergoeding die afhankelijk is van je aansluiting. Wij dragen deze vervolgens weer af aan je\r\n                            netbeheerder. Ook hier geldt dat de tarieven jaarlijks per 1 januari wijzigen. Om deze reden\r\n                            zie je onderstaand mogelijk weer twee berekeningen: voor de periode vóór en de periode ná 1\r\n                            januari. </p>\r\n                        <p> Je netbeheerder: <strong>[grid_operator_name]</strong>\r\n                        </p>\r\n                    </div>\r\n                </div>\r\n                <div class=\"mt-3 custom-table table_grid_operator\"> [grid_operator_item_dynamic_page] </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div class=\"row\">\r\n                    <div class=\"col-12\">\r\n                    	<p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">4. Totaal in rekening gebrachte termijnbedragen</p>\r\n                        <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">5. Totaal in rekening gebrachte termijnbedragen</p>\r\n                        <p class=\"mb-1\">Hier zie je een overzicht van de door ons in rekening gebrachte termijnbedragen in de afgelopen periode (incl. btw). Een negatief termijnbedrag wordt als niet in rekening gebracht beschouwd en daarom als 0 weergegeven.</p>\r\n                    </div>\r\n                </div>\r\n                <div class=\"mt-5\">\r\n                    <table class=\"table table-custom\">\r\n                        <thead>\r\n                            <th class=\"pl-2 charge-item-month-column\">MAAND</th>\r\n                            <th class=\"pl-2 charge-item-invoice-number\">FACTUURNUMMER</th>\r\n                            <th class=\"pl-2 text-right\" colspan=\"2\">BEDRAG</th>\r\n                        </thead>\r\n                        <tbody> [charged_item_by_month] </tbody>\r\n                    </table>\r\n                    <table>\r\n                        <tbody>\r\n                            <tr>\r\n                                <td style=\"height: 15px;\"></td>\r\n                            </tr>\r\n                            <tr>\r\n                                <td class=\"w-100\"></td>\r\n                                <td class=\"pl-2 text-right font-weight-bold text-nowrap t-nowrap\">\r\n                                    <div class=\"border-top-bold position-relative\">\r\n                                        <span class=\"pr-5\">Totaal in rekening gebrachte termijnbedragen</span>\r\n                                        <span>[total_generated_amount]</span>\r\n                                    </div>\r\n                                </td>\r\n                            </tr>\r\n                        </tbody>\r\n                    </table>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div>\r\n                    <p class=\"font-weight-bold\">Jouw EAN-codes</p> [elk_gas_eans]\r\n                </div>\r\n                <div class=\"mt-5\">\r\n                    <p class=\"font-weight-bold\">Btw-aangifte</p>\r\n                    <p class=\"mb-0\">\r\n                        [reseller_name] handelt onder de leveranciersvergunning van Kikker Energie. In het geval je een\r\n                        btw-aangifte moet doen, dien je daarom de gegevens van Kikker Energie te gebruiken. De benodigde\r\n                        informatie van Kikker Energie en je netbeheerder vind je onderstaand:\r\n                    </p>\r\n                </div>\r\n                <div class=\"row mt-4\">\r\n                    <div class=\"col-5\">\r\n                        <p class=\"mb-0\">\r\n                            Kikker Energie B.V.</br>\r\n                            Tolnasingel 12 </br> 2411PV Bodegraven\r\n                        </p>\r\n                        <p class=\"mb-0\">KvK: 71246681</p>\r\n                        <p class=\"mb-0\">Btw nr.: NL858635732B01</p>\r\n                    </div>\r\n                    <div class=\"col-5\">\r\n                        <p class=\"mb-0\"> [grid_operator_name] </br> [grid_operator_house_nr] </br>\r\n                            [grid_operator_postcode] </p>\r\n                        <p class=\"mb-0\">KvK: [grid_operator_kvk]</p>\r\n                        <p class=\"mb-0\">Btw nr.: [grid_operator_btw]</p>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</body>\r\n\r\n</html>\r\n', NULL, NULL, 'nl', 'ke-pdf', NULL, '2023-11-27 09:07:13.152323', NULL);
INSERT IGNORE INTO `templates_reseller` (`Id`, `reseller_id`, `template_name`, `html_content`, `header_id`, `footer_id`, `language_code`, `CreatedBy`, `ModifiedBy`, `CreatedAt`, `ModifiedAt`) VALUES (155, 197, 'FINALBILL_TEMPLATE_MAIN_CANCELATION_FEE_KFM', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n  <head>\r\n    <title>Billing | Kikker</title>\r\n    <meta charset=\"utf-8\">\r\n    <link rel=\"icon\" href=\"asset/kikker-icon.ico\" />\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\r\n    <link rel=\"stylesheet\" href=\"https://storage.googleapis.com/kikkerprodbucket/static-files/pdf-css/site.css\">\r\n    <link rel=\"stylesheet\" href=\"https://storage.googleapis.com/kikkerprodbucket/static-files/pdf-css/final_bill.css\">\r\n  </head>\r\n  \r\n  <body>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div class=\"row header mr-0 ml-0\">\r\n              <div style=\"width: 33%;\">\r\n              </div>\r\n              <div class=\"[hide-header-invoice-info] header-invoice-info\">\r\n                  <div class=\"d-flex justify-content-end\">\r\n                      <div class=\"space-span d-inline-block\" style=\"padding-top: 0\">\r\n                          <div class=\"mb-0 d-flex\">\r\n                              <p class=\"text-right pr-3 mb-0\" style=\"min-width: 170px;width: 170px;\">Klantnummer:</p>\r\n                              <p class=\"mb-0\">[client_number]</p>\r\n                          </div>\r\n                          <div class=\"mb-0 d-flex\">\r\n                              <p class=\"text-right pr-3 mb-0\" style=\"min-width: 170px;width: 170px;\"\r\n                                  >Contractnummer:\r\n                              </p>\r\n                              <p class=\"mb-0\">[contract_number]</p>\r\n                          </div>\r\n                          <div class=\"mb-0 d-flex [hidden_contract_reference]\" style=\"flex-flow: row;\">\r\n                              <p class=\"text-right pr-3 mb-0\" style=\"min-width: 170px;width: 170px;\">Contractreferentie: </p>\r\n                              <p class=\"mb-0\">[contract_reference]</p>\r\n                          </div>\r\n                          <div class=\"mb-0 d-flex\">\r\n                              <p class=\"text-right pr-3 mb-0\" style=\"min-width: 170px;width: 170px;\"\r\n                                  >Factuurnummer:\r\n                              </p>\r\n                              <p class=\"mb-0\">[invoice_number]</p>\r\n                          </div>\r\n                          <div class=\"mb-0 d-flex [company_name_visible]\" style=\"flex-flow: row;\">\r\n                              <p class=\"text-right pr-3 mb-0\" style=\"min-width: 170px;width: 170px;\">Bedrijfsnaam: </p>\r\n                              <p class=\"mb-0\">[company_name]</p>\r\n                          </div>\r\n                          <div class=\"mb-0 d-flex\" style=\"flex-flow: row;\">\r\n                              <p class=\"text-right pr-3 mb-0\" style=\"min-width: 170px;width: 170px;\">Energie intermediair: </p>\r\n                              <p class=\"mb-0\">[header_reseller_name]</p>\r\n                          </div>\r\n                          <div class=\"mb-0 d-flex\">\r\n                              <p class=\"text-right vertical-align-top pr-3 mb-0\" style=\"min-width: 170px;width: 170px;\"\r\n                                  >Leveringsadres:</p\r\n                              >\r\n                              <p class=\"mb-0\" class=\"d-inline-block\"\r\n                                  >[delivery_address_street] [delivery_address_houseNr] [delivery_address_zipcode]<br><span class=\"text-capitalize\">[delivery_address_city]</span></p\r\n                              >\r\n                          </div>\r\n                      </div>\r\n                  </div>\r\n              </div>\r\n          </div>\r\n          <div class=\"row\">\r\n            <div class=\"col-12\">\r\n                <p class=\"mb-0\">\r\n                <span class=\"float-right\">[date_generate_PDF]</span>\r\n              </p>\r\n              <p class=\"mt-5 mb-4\">Beste [customer_first_name],</p>\r\n              <p class=\"mb-4 [final_bill_visible]\">Dit is je eindafrekening over de verbruiksperiode van [final_bill_start_date] tot [final_bill_end_date] voor je leveringsadres [delivery_address_street] [delivery_address_houseNr] te <span class=\"text-capitalize\">[delivery_address_city]</span>. Je ontvangt deze afrekening omdat je contract met [reseller_name] eindigt. In deze eindafrekening berekenen we de kosten tot de einddatum van je contract. Indien je onlangs een nieuw [reseller_name]-contract hebt afgesloten, ontvang je hier apart bericht van. </p>\r\n              <p class=\"mb-4 [yearly_bill_visible]\">Dit is je jaarafrekening over de verbruiksperiode van [final_bill_start_date] tot [final_bill_end_date] voor je leveringsadres [delivery_address_street] te <span class=\"text-capitalize\">[delivery_address_city]</span>. In deze jaarafrekening vind je een overzicht van je energieverbruik in het afgelopen jaar en wat je hiervoor hebt betaald. </p>\r\n            </div>\r\n          </div>\r\n          [FINALBILL_TEMPLATE_UNPAID_AMOUNT_INVOICE_ITEM]\r\n          [FINALBILL_TEMPLATE_PAID_AMOUNT_INVOICE_ITEM]\r\n          <div>\r\n            <p class=\"mb-1 font-weight-bold [yearly_bill_visible] [new_monthly_amount_visible]\"> Je nieuwe termijnbedrag </span>\r\n            </p>\r\n            <p class=\"mb-4 [yearly_bill_visible] [new_monthly_amount_visible]\"> Op basis van je verbruik in de afgelopen 12 maanden, hebben we een nieuw termijnbedrag voor je uitgerekend. We passen het termijnbedrag automatisch voor je aan. Ben je het niet eens met je nieuwe termijnbedrag? Dan kun je dit gemakkelijk aanpassen in onze mobiele app. </p>\r\n          </div>\r\n          <div class=\"row monthly-amount-block [yearly_bill_visible] [new_monthly_amount_visible] mt-4\" style=\"background-image: url(\'data:image/png;base64,\');background-size: 100%; background-repeat: no-repeat; background-position: center center;\">\r\n            <div class=\"col-6\">\r\n              <span> Oude termijnbedrag </span>\r\n              <span class=\"float-right\"> € [current_monthly_amount] </span>\r\n            </div>\r\n            <div class=\"col-6 pl-5 font-weight-bold\">\r\n              <span> Nieuwe termijnbedrag </span>\r\n              <span class=\"float-right\"> € [new_monthly_amount] </span>\r\n            </div>\r\n          </div>\r\n          <div class=\"mt-4 avoid-break-page\">\r\n            <p class=\"font-weight-bold mb-1\">Vragen?</p>\r\n            <p class=\"mb-3\" style=\"text-align: left;\">Je kunt altijd contact met ons opnemen via [reseller_email] of bellen naar [reseller_phone].</p>\r\n            <p class=\"mb-3\">Met vriendelijke groet, </p>\r\n            <p class=\"mb-0\">[reseller_name]</p>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div class=\"row\">\r\n            <div class=\"col-12\">\r\n              <p>Meer informatie over je verbruik of de precieze berekening van je <span class=\"[final_bill_visible]\">eindafrekening</span> <span class=\"[yearly_bill_visible]\">jaarafrekening</span> vind je op de volgende pagina’s.</p>\r\n              <p class=\"mb-1 font-weight-bold\">Samenvatting van je <span class=\"[final_bill_visible]\">eindafrekening</span>\r\n                <span class=\"[yearly_bill_visible]\">jaarafrekening</span>\r\n              </p>\r\n            </div>\r\n          </div>\r\n          <div class=\"[hide_text_summary]\">[text_summary]</div>\r\n          <div class=\"mt-5 table-first\">\r\n            <table class=\"table\">\r\n              <tbody>\r\n                <tr>\r\n                  <td class=\"pl-2\"> 1. Leveringskosten van [product_type] </td>\r\n                  <td class=\"pl-2 text-right\">[total_delivery_amount]</td>\r\n                </tr>\r\n                <tr class=\"[show_price_cap_billing]\">\r\n                  <td class=\"pl-2\"> 2. Tegemoetkoming uit het prijsplafond</td>\r\n                  <td class=\"pl-2 text-right\">[total_price_cap]</td>\r\n                </tr>\r\n                <tr>\r\n                  <td class=\"pl-2 [hide_price_cap_billing]\"> 2. Overheidsheffingen op [product_type], dit dragen we af aan de overheid </td>\r\n                  <td class=\"pl-2 [show_price_cap_billing]\"> 3. Overheidsheffingen op [product_type], dit dragen we af aan de overheid </td>\r\n                  <td class=\"pl-2 text-right\">[total_tax_amount]</td>\r\n                </tr>\r\n                <tr>\r\n                  <td class=\"pl-2 [hide_price_cap_billing]\"> 3. Netbeheerkosten op [product_type], dit dragen we af aan je netbeheerder </td>\r\n                  <td class=\"pl-2 [show_price_cap_billing]\"> 4. Netbeheerkosten op [product_type], dit dragen we af aan je netbeheerder </td>\r\n                  <td class=\"pl-2 text-right\">[total_grid_operator_amount]</td>\r\n                </tr>\r\n                <tr>\r\n                  <td class=\"pl-2 [hide_price_cap_billing]\"> 4. Opzegboete voor tussentijdse opzegging </td>\r\n                  <td class=\"pl-2 [show_price_cap_billing]\"> 5. Opzegboete voor tussentijdse opzegging </td>\r\n                  <td class=\"pl-2 text-right\">[cancelation_fee]</td>\r\n                </tr>\r\n                <tr>\r\n                  <td class=\"pl-2 font-weight-bold\"></td>\r\n                  <td class=\"pl-2 text-right  font-weight-bold\">[total_real_amount_incl_cancel_fee]</td>\r\n                </tr>\r\n              </tbody>\r\n            </table>\r\n          </div>\r\n          <div class=\"mt-4 table-first\">\r\n            <table class=\"table\">\r\n              <tbody>\r\n                <tr>\r\n                  <td class=\"pl-2 [hide_price_cap_billing]\"> 5. In rekening gebrachte termijnbedragen </td>\r\n                  <td class=\"pl-2 [show_price_cap_billing]\"> 6. In rekening gebrachte termijnbedragen </td>\r\n                  <td class=\"pl-2 text-right\">[total_generated_amount_negative]</td>\r\n                </tr>\r\n                <tr class=\"[total_unpaid_amount_class]\">\r\n                  <td class=\"pl-4 font-italic\"> Openstaande termijnbedragen </td>\r\n                  <td class=\"pl-2 text-right\">[total_unpaid_amount]</td>\r\n                </tr>\r\n                <tr class=\"[total_collection_cost_amount_class]\">\r\n                  <td class=\"pl-4 font-italic\"> Openstaande incassokosten </td>\r\n                  <td class=\"pl-2 text-right\">[total_collection_cost_amount]</td>\r\n                </tr>\r\n                <tr>\r\n                  <td class=\"pl-2 font-weight-bold\"></td>\r\n                  <td class=\"pl-2 text-right  font-weight-bold\">[total_real_generated_amount_negative]</td>\r\n                </tr>\r\n              </tbody>\r\n            </table>\r\n            <table>\r\n              <tbody>\r\n                <tr>\r\n                  <td style=\"height: 15px;\"></td>\r\n                </tr>\r\n                <tr>\r\n                  <td class=\"w-100\"></td>\r\n                  <td class=\"pl-2 text-right font-weight-bold text-nowrap t-nowrap\">\r\n                    <div class=\"border-top-bold position-relative\">\r\n                      <span class=\"pr-5\">[is_receive]</span>\r\n                      <span>€ [difference_amount]</span>\r\n                    </div>\r\n                  </td>\r\n                </tr>\r\n              </tbody>\r\n            </table>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div class=\"[usage_only_gas_elk_visible]\">\r\n            <p class=\"mb-1 font-weight-bold\"> Berekening van je verbruik </p>\r\n            <p> Op basis van je meterstanden bepalen wij hoeveel energie je hebt verbruikt. De meterstanden lezen wij uit via je slimme meter, vragen wij bij je op of berekenen we zelf. Onderstaand vind je een overzicht van je verbruik per periode. Omdat tussen periodes soms verschillende tarieven gelden, kan het zijn dat je verschillende periodes ziet. </p>\r\n          </div>\r\n          <div class=\"mt-5 [usage_only_gas_elk_visible]\"> [usage_item_by_ean] </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div class=\"[usage_only_gas_elk_visible]\" style=\"page-break-before: always\"></div>\r\n    <div class=\"page [usage_both_gas_elk_visible]\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div>\r\n            <p class=\"mb-1 font-weight-bold\"> Berekening van je verbruik </p>\r\n            <p> Op basis van je meterstanden bepalen wij hoeveel energie je hebt verbruikt. De meterstanden lezen wij uit via je slimme meter, vragen wij bij je of berekenen we zelf. Onderstaand vind je een overzicht van je verbruik per periode. Omdat tussen periodes soms verschillende tarieven gelden, kan het zijn dat je verschillende periodes ziet. </p>\r\n          </div>\r\n          <div class=\"mt-5\"> [usage_item_by_ean] </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div class=\"[usage_both_gas_elk_visible]\" style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div>\r\n            <p class=\"mb-4\">Op de volgende pagina’s vind je een nadere specificatie van de kosten die weergegeven zijn op pagina 2.</p>\r\n            [return_tariff_section]\r\n            <p class=\"mb-1 font-weight-bold\">1. Leveringskosten voor [product_type]</p>\r\n            <p class=\"mb-5\"> Onderstaand vind je een specificatie van je leveringskosten voor [product_type]. Door je verbruik te vermenigvuldigen met je tarief bepalen we je kosten per contract. </p>\r\n          </div>\r\n          <div class=\"table_fixed_delivery\"> [fixed_delivery_item_dynamic_page] </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    [price_cap_section_template]\r\n\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div class=\"row\">\r\n            <div class=\"col-12\">\r\n              <p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">2. Overheidsheffingen op [product_type]</p>\r\n              <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">3. Overheidsheffingen op [product_type]</p>\r\n           <p style=\"display: [show_new_ode_tax_description]\">Naast de kosten voor het verbruik van [product_type], moet je ook belastingen betalen aan de overheid. Ook deze zijn afhankelijk van je verbruik. Onderstaande kosten dragen wij direct af aan de overheid. Omdat de heffingen jaarlijks (per 1 januari) veranderen zie je onderstaand mogelijk twee berekeningen: een voor de periode vóór en een voor de periode ná 1 januari.</p>\r\n            </div>\r\n          </div>\r\n          <div class=\"mt-3\"> [tax_item_dynamic_page] </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div class=\"row\">\r\n            <div class=\"col-12\">\r\n              <p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">3. Netbeheerkosten voor [product_type]</p>\r\n              <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">4. Netbeheerkosten voor [product_type]</p>\r\n              <p class=\"mb-3\">Om van [product_type] gebruik te kunnen maken, dien je aangesloten te zijn op het openbare [product_type]netwerk van je netbeheerder. Hiervoor betaal je een vaste vergoeding die afhankelijk is van je aansluiting. Wij dragen deze vervolgens weer af aan je netbeheerder. Ook hier geldt dat de tarieven jaarlijks per 1 januari wijzigen. Om deze reden zie je onderstaand mogelijk weer twee berekeningen: voor de periode vóór en de periode ná 1 januari. </p>\r\n              <p> Je netbeheerder: <strong>[grid_operator_name]</strong>\r\n              </p>\r\n            </div>\r\n          </div>\r\n          <div class=\"mt-3 custom-table table_grid_operator\"> [grid_operator_item_dynamic_page] </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div class=\"row\">\r\n            <div class=\"col-12\">\r\n              <p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">4. Opzegboete voor tussentijdse opzegging</p>\r\n              <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">5. Opzegboete voor tussentijdse opzegging</p>\r\n              <p>Dit contract had een looptijd voor <span style=\"text-transform: lowercase;\">[contract_duration]</span>, maar is na [day_active_in_our_system] dagen opgezegd. Conform de afgesproken voorwaarden, wordt bij opzegging gedurende de vaste looptijd van het contract een opzegboete in rekening gebracht. Deze opzegboete is afhankelijk van de resterende looptijd van het contract en geldt per product ([product_type]). Voor een resterende looptijd van [remaning_days], bedraagt de opzegboete € [cancelation_fee_summary] per product. Hierbij houden we ons aan de richtlijnen van de Autoriteit Consument en Markt. </p>\r\n            </div>\r\n          </div>\r\n          <div class=\"mt-5\">\r\n            <table class=\"table table-custom [cancellation_fee_visible]\">\r\n              <thead>\r\n                <th class=\"pl-2 text-uppercase\">OPZEGBOETE VOOR CONTRACT MET RESTERENDE LOOPTIJD MEER DAN [contract_duration_title]</th>\r\n                <th class=\"pl-2 text-right\">BEDRAG</th>\r\n              </thead>\r\n              <tbody>\r\n                <tr class=\"[cancellation_fee_elk_visible]\">\r\n                  <td class=\"pl-2\"> Opzegboete stroom </td>\r\n                  <td class=\"pl-2 text-right\">€ [cancelation_fee_elk]</td>\r\n                </tr>\r\n                <tr class=\"[cancellation_fee_gas_visible]\">\r\n                  <td class=\"pl-2\"> Opzegboete gas </td>\r\n                  <td class=\"pl-2 text-right\">€ [cancelation_fee_gas]</td>\r\n                </tr>\r\n              </tbody>\r\n            </table>\r\n            <table>\r\n              <tbody>\r\n                <tr>\r\n                  <td style=\"height: 15px;\"></td>\r\n                </tr>\r\n                <tr>\r\n                  <td class=\"w-100\"></td>\r\n                  <td class=\"pl-2 text-right font-weight-bold text-nowrap t-nowrap\">\r\n                    <div class=\"border-top-bold position-relative\">\r\n                      <span class=\"pr-5\">Totaalbedrag opzegboete voor tussentijdse opzegging</span>\r\n                      <span>€ [cancelation_fee_last_page]</span>\r\n                    </div>\r\n                  </td>\r\n                </tr>\r\n              </tbody>\r\n            </table>\r\n          </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n          <div class=\"content\">\r\n            <div class=\"row\">\r\n              <div class=\"col-12\">\r\n              	<p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">5. Totaal in rekening gebrachte termijnbedragen</p>\r\n                <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">6. Totaal in rekening gebrachte termijnbedragen</p>\r\n                <p>Hier zie je een overzicht van de door ons in rekening gebrachte termijnbedragen in de afgelopen periode (incl. btw). Een negatief termijnbedrag wordt als niet in rekening gebracht beschouwd en daarom als 0 weergegeven.</p>\r\n              </div>\r\n            </div>\r\n            <div class=\"mt-5\">\r\n              <table class=\"table table-custom\">\r\n                <thead>\r\n                  <th class=\"pl-2 charge-item-month-column\">MAAND</th>\r\n                  <th class=\"pl-2 charge-item-invoice-number\">FACTUURNUMMER</th>\r\n                  <th class=\"pl-2 text-right\" colspan=\"2\">BEDRAG</th>\r\n                </thead>\r\n                <tbody> [charged_item_by_month] </tbody>\r\n              </table>\r\n              <table>\r\n                <tbody>\r\n                  <tr>\r\n                    <td style=\"height: 15px;\"></td>\r\n                  </tr>\r\n                  <tr>\r\n                    <td class=\"w-100\"></td>\r\n                    <td class=\"pl-2 text-right font-weight-bold text-nowrap t-nowrap\">\r\n                      <div class=\"border-top-bold position-relative\">\r\n                        <span class=\"pr-5\">Totaal in rekening gebrachte termijnbedragen</span>\r\n                        <span>[total_generated_amount]</span>\r\n                      </div>\r\n                    </td>\r\n                  </tr>\r\n                </tbody>\r\n              </table>\r\n            </div>\r\n        </div>\r\n    </div>\r\n\r\n    <div style=\"page-break-before: always\"></div>\r\n\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n          <div class=\"content\">\r\n            <div class=\"mt-2\">\r\n                <p class=\"font-weight-bold\">Jouw EAN-codes</p> [elk_gas_eans]\r\n            </div>\r\n            <div class=\"mt-5\">\r\n                <p class=\"font-weight-bold\">Btw-aangifte</p>\r\n                <p class=\"mb-0\"> [reseller_name] handelt onder de leveranciersvergunning van Kikker Energie. In het geval je een btw-aangifte moet doen, dien je daarom de gegevens van Kikker Energie te gebruiken. De benodigde informatie van Kikker Energie en je netbeheerder vind je onderstaand: </p>\r\n            </div>\r\n            <div class=\"row mt-4\">\r\n                <div class=\"col-5\">\r\n                  <p class=\"mb-0\">\r\n                    Kikker Energie B.V.</br>\r\n                    Tolnasingel 12 </br> 2411PV Bodegraven\r\n                  </p>\r\n                  <p class=\"mb-0\">KvK: 71246681</p>\r\n                  <p class=\"mb-0\">Btw nr.: NL858635732B01</p>\r\n                </div>\r\n                <div class=\"col-5\">\r\n                  <p class=\"mb-0\"> [grid_operator_name] </br> [grid_operator_house_nr] </br> [grid_operator_postcode] </p>\r\n                  <p class=\"mb-0\">KvK: [grid_operator_kvk]</p>\r\n                  <p class=\"mb-0\">Btw nr.: [grid_operator_btw]</p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n  </body>\r\n</html>', NULL, NULL, 'nl', 'ke-pdf', NULL, '2023-11-27 09:07:13.152323', NULL);
INSERT IGNORE INTO `templates_reseller` (`Id`, `reseller_id`, `template_name`, `html_content`, `header_id`, `footer_id`, `language_code`, `CreatedBy`, `ModifiedBy`, `CreatedAt`, `ModifiedAt`) VALUES (162, 197, 'FINALBILL_TEMPLATE_MAIN_CANCELATION_FEE_KX', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n  <head>\r\n    <title>Billing | Kikker</title>\r\n    <meta charset=\"utf-8\">\r\n    <link rel=\"icon\" href=\"asset/kikker-icon.ico\" />\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\r\n    <link rel=\"stylesheet\" href=\"https://storage.googleapis.com/kikkerprodbucket/static-files/pdf-css/site.css\">\r\n    <link rel=\"stylesheet\" href=\"https://storage.googleapis.com/kikkerprodbucket/static-files/pdf-css/final_bill.css\">\r\n  </head>\r\n  \r\n  <body>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div class=\"row header mr-0 ml-0\">\r\n            <div style=\"width: 33%;\">\r\n            </div>\r\n            <div class=\"[hide-header-invoice-info] header-invoice-info\">\r\n                <div class=\"d-flex justify-content-end\">\r\n                    <div class=\"space-span d-inline-block\" style=\"padding-top: 0\">\r\n                        <div class=\"mb-0 d-flex\">\r\n                            <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\">Klantnummer:</p>\r\n                            <p class=\"mb-0\">[client_number]</p>\r\n                        </div>\r\n                        <div class=\"mb-0 d-flex\">\r\n                            <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\"\r\n                                >Contractnummer:\r\n                            </p>\r\n                            <p class=\"mb-0\">[contract_number]</p>\r\n                        </div>\r\n                        <div class=\"mb-0 d-flex [hidden_contract_reference]\" style=\"flex-flow: row;\">\r\n                            <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\">Contractreferentie: </p>\r\n                            <p class=\"mb-0\">[contract_reference]</p>\r\n                        </div>\r\n                        <div class=\"mb-0 d-flex\">\r\n                            <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\"\r\n                                >Factuurnummer:\r\n                            </p>\r\n                            <p class=\"mb-0\">[invoice_number]</p>\r\n                        </div>\r\n                        <div class=\"mb-0 d-flex [company_name_visible]\" style=\"flex-flow: row;\">\r\n                            <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\">Bedrijfsnaam: </p>\r\n                            <p class=\"mb-0\">[company_name]</p>\r\n                        </div>\r\n                        <div class=\"mb-0 d-flex\" style=\"flex-flow: row;\">\r\n                            <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\">Energie intermediair: </p>\r\n                            <p class=\"mb-0\">[header_reseller_name]</p>\r\n                        </div>\r\n                        <div class=\"mb-0 d-flex\">\r\n                            <p class=\"text-right vertical-align-top pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\"\r\n                                >Leveringsadres:</p\r\n                            >\r\n                            <p class=\"mb-0\" class=\"d-inline-block\"\r\n                                >[delivery_address_street] [delivery_address_houseNr] [delivery_address_zipcode]<br><span class=\"text-capitalize\">[delivery_address_city]</span></p\r\n                            >\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n          <div class=\"row\">\r\n            <div class=\"col-12\">\r\n                <p class=\"mb-0\">\r\n                    <span class=\"float-right\">[date_generate_PDF]</span>\r\n                  </p>\r\n              <p class=\"mt-5\">Beste [customer_first_name],</p>\r\n              <p class=\"mt-4 [final_bill_visible]\">Dit is je eindafrekening over de verbruiksperiode van [final_bill_start_date] tot [final_bill_end_date] voor je leveringsadres [delivery_address_street] [delivery_address_houseNr] te <span class=\"text-capitalize\">[delivery_address_city]</span>. Je ontvangt deze afrekening omdat je contract met [reseller_name] eindigt. In deze eindafrekening berekenen we de kosten tot de einddatum van je contract. Indien je onlangs een nieuw [reseller_name]-contract hebt afgesloten, ontvang je hier apart bericht van. </p>\r\n              <p class=\"mt-4 [yearly_bill_visible]\">Dit is je jaarafrekening over de verbruiksperiode van [final_bill_start_date] tot [final_bill_end_date] voor je leveringsadres [delivery_address_street] [delivery_address_houseNr] te <span class=\"text-capitalize\">[delivery_address_city]</span>. In deze jaarafrekening vind je een overzicht van je energieverbruik in het afgelopen jaar en wat je hiervoor hebt betaald. </p>\r\n            </div>\r\n          </div>\r\n          [FINALBILL_TEMPLATE_UNPAID_AMOUNT_INVOICE_ITEM]\r\n          [FINALBILL_TEMPLATE_PAID_AMOUNT_INVOICE_ITEM]\r\n          <div>\r\n            <p class=\"mb-1 font-weight-bold [yearly_bill_visible] [new_monthly_amount_visible]\">\r\n              <span>Je nieuwe termijnbedrag </span>\r\n            </p>\r\n            <p class=\"mb-4 [yearly_bill_visible] [new_monthly_amount_visible]\"> Op basis van je verbruik in de afgelopen 12 maanden, hebben we een nieuw termijnbedrag voor je uitgerekend. We passen het termijnbedrag automatisch voor je aan. Ben je het niet eens met je nieuwe termijnbedrag? Dan kun je dit gemakkelijk aanpassen in onze mobiele app. </p>\r\n          </div>\r\n          <div class=\"row monthly-amount-block [yearly_bill_visible] [new_monthly_amount_visible] mt-4\" style=\"background-image: url(\'data:image/png;base64,\');background-size: 100%; background-repeat: no-repeat; background-position: center center;\">\r\n            <div class=\"col-6\">\r\n              <span> Oude termijnbedrag </span>\r\n              <span class=\"float-right\"> € [current_monthly_amount] </span>\r\n            </div>\r\n            <div class=\"col-6 pl-5 font-weight-bold\">\r\n              <span> Nieuwe termijnbedrag </span>\r\n              <span class=\"float-right\"> € [new_monthly_amount] </span>\r\n            </div>\r\n          </div>\r\n          <div class=\"mt-4 avoid-break-page\">\r\n            <p class=\"font-weight-bold mb-1\">Vragen?</p>\r\n            <p class=\"mb-3\">Je kunt altijd contact met ons opnemen via <a href=\"mailto:[reseller_email]\">[reseller_email]</a> of bellen naar [reseller_phone]. </p>\r\n            <p class=\"mb-3\">Met vriendelijke groet, </p>\r\n            <p class=\"mb-0\">[reseller_name]</p>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div class=\"row\">\r\n            <div class=\"col-12\">\r\n              <p>Meer informatie over je verbruik of de precieze berekening van je <span class=\"[final_bill_visible]\">eindafrekening</span> <span class=\"[yearly_bill_visible]\">jaarafrekening</span> vind je op de volgende pagina’s.</p>\r\n              <p class=\"mb-1 font-weight-bold\">Samenvatting van je <span class=\"[final_bill_visible]\">eindafrekening</span>\r\n                <span class=\"[yearly_bill_visible]\">jaarafrekening</span>\r\n              </p>\r\n            </div>\r\n          </div>\r\n          <div class=\"[hide_text_summary]\">[text_summary]</div>\r\n          <div class=\"mt-5 table-first\">\r\n            <table class=\"table\">\r\n              <tbody>\r\n                <tr>\r\n                  <td class=\"pl-2\"> 1. Leveringskosten van [product_type] </td>\r\n                  <td class=\"pl-2 text-right\">[total_delivery_amount]</td>\r\n                </tr>\r\n                <tr class=\"[show_price_cap_billing]\">\r\n                  <td class=\"pl-2\"> 2. Tegemoetkoming uit het prijsplafond</td>\r\n                  <td class=\"pl-2 text-right\">[total_price_cap]</td>\r\n                </tr>\r\n                <tr>\r\n                  <td class=\"pl-2 [hide_price_cap_billing]\">2. Overheidsheffingen op [product_type], dit dragen we af aan de overheid</td>\r\n                  <td class=\"pl-2 [show_price_cap_billing]\">3. Overheidsheffingen op [product_type], dit dragen we af aan de overheid</td>\r\n                  <td class=\"pl-2 text-right\">[total_tax_amount]</td>\r\n                </tr>\r\n                <tr>\r\n                  <td class=\"pl-2 [hide_price_cap_billing]\">3. Netbeheerkosten op [product_type], dit dragen we af aan je netbeheerder</td>\r\n                  <td class=\"pl-2 [show_price_cap_billing]\">4. Netbeheerkosten op [product_type], dit dragen we af aan je netbeheerder</td>\r\n                  <td class=\"pl-2 text-right\">[total_grid_operator_amount]</td>\r\n                </tr>\r\n                <tr>\r\n                  <td class=\"pl-2 [hide_price_cap_billing]\">4. Opzegboete voor tussentijdse opzegging</td>\r\n                  <td class=\"pl-2 [show_price_cap_billing]\">5. Opzegboete voor tussentijdse opzegging</td>\r\n                  <td class=\"pl-2 text-right\">[cancelation_fee]</td>\r\n                </tr>\r\n                <tr>\r\n                  <td class=\"pl-2 font-weight-bold\"></td>\r\n                  <td class=\"pl-2 text-right  font-weight-bold\">[total_real_amount_incl_cancel_fee]</td>\r\n                </tr>\r\n              </tbody>\r\n            </table>\r\n          </div>\r\n          <div class=\"mt-4 table-first\">\r\n            <table class=\"table\">\r\n              <tbody>\r\n                <tr>\r\n                  <td class=\"pl-2 [hide_price_cap_billing]\">5. In rekening gebrachte termijnbedragen </td>\r\n                  <td class=\"pl-2 [show_price_cap_billing]\">6. In rekening gebrachte termijnbedragen </td>\r\n                  <td class=\"pl-2 text-right\">[total_generated_amount_negative]</td>\r\n                </tr>\r\n                <tr class=\"[total_unpaid_amount_class]\">\r\n                  <td class=\"pl-4 font-italic\"> Openstaande termijnbedragen </td>\r\n                  <td class=\"pl-2 text-right\">[total_unpaid_amount]</td>\r\n                </tr>\r\n                <tr class=\"[total_collection_cost_amount_class]\">\r\n                  <td class=\"pl-4 font-italic\"> Openstaande incassokosten </td>\r\n                  <td class=\"pl-2 text-right\">[total_collection_cost_amount]</td>\r\n                </tr>\r\n                <tr>\r\n                  <td class=\"pl-2 font-weight-bold\"></td>\r\n                  <td class=\"pl-2 text-right  font-weight-bold\">[total_real_generated_amount_negative]</td>\r\n                </tr>\r\n              </tbody>\r\n            </table>\r\n            <table>\r\n              <tbody>\r\n                <tr>\r\n                  <td class=\"w-100\"></td>\r\n                  <td class=\"pl-2 text-right font-weight-bold text-nowrap t-nowrap\">\r\n                    <div class=\"border-top-bold position-relative\">\r\n                      <span class=\"pr-5\">[is_receive]</span>\r\n                      <span>€ [difference_amount]</span>\r\n                    </div>\r\n                  </td>\r\n                </tr>\r\n              </tbody>\r\n            </table>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div class=\"[usage_only_gas_elk_visible]\">\r\n            <p class=\"mb-1 font-weight-bold\"> Berekening van je verbruik </p>\r\n            <p> Op basis van je meterstanden bepalen wij hoeveel energie je hebt verbruikt. De meterstanden lezen wij uit via je slimme meter, vragen wij bij je op via de Kikker app of berekenen we zelf. Onderstaand vind je een overzicht van je verbruik per periode. Omdat tussen periodes soms verschillende tarieven gelden, kan het zijn dat je verschillende periodes ziet. </p>\r\n          </div>\r\n          <div class=\"mt-5 [usage_only_gas_elk_visible]\"> [usage_item_by_ean] </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div class=\"[usage_only_gas_elk_visible]\" style=\"page-break-before: always\"></div>\r\n    <div class=\"page [usage_both_gas_elk_visible]\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div>\r\n            <p class=\"mb-1 font-weight-bold\"> Berekening van je verbruik </p>\r\n            <p> Op basis van je meterstanden bepalen wij hoeveel energie je hebt verbruikt. De meterstanden lezen wij uit via je slimme meter, vragen wij bij je op via de Kikker app of berekenen we zelf. Onderstaand vind je een overzicht van je verbruik per periode. Omdat tussen periodes soms verschillende tarieven gelden, kan het zijn dat je verschillende periodes ziet. </p>\r\n          </div>\r\n          <div class=\"mt-5\"> [usage_item_by_ean] </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div class=\"[usage_both_gas_elk_visible]\" style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div>\r\n            <p class=\"mb-4\">Op de volgende pagina’s vind je een nadere specificatie van de kosten die weergegeven zijn op pagina 2.</p>\r\n            [return_tariff_section]\r\n            <p class=\"mb-1 font-weight-bold\">1. Leveringskosten voor [product_type]</p>\r\n            <p class=\"mb-5\"> Onderstaand vind je een specificatie van je leveringskosten voor [product_type]. Door je verbruik te vermenigvuldigen met je tarief bepalen we je kosten per contract. </p>\r\n          </div>\r\n          <div class=\"table_fixed_delivery\"> [fixed_delivery_item_dynamic_page] </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    [price_cap_section_template]\r\n\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div class=\"row\">\r\n            <div class=\"col-12\">\r\n              <p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">2. Overheidsheffingen op [product_type]</p>\r\n              <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">3. Overheidsheffingen op [product_type]</p>\r\n              <p style=\"display: [show_new_ode_tax_description]\">Naast de kosten voor het verbruik van [product_type], moet je ook belastingen betalen aan de overheid. Ook deze zijn afhankelijk van je verbruik. Onderstaande kosten dragen wij direct af aan de overheid. Omdat de heffingen jaarlijks (per 1 januari) veranderen zie je onderstaand mogelijk twee berekeningen: een voor de periode vóór en een voor de periode ná 1 januari.</p>\r\n            </div>\r\n          </div>\r\n          <div class=\"mt-3\"> [tax_item_dynamic_page] </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div class=\"row\">\r\n            <div class=\"col-12\">\r\n              <p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">3. Netbeheerkosten voor [product_type]</p>\r\n              <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">4. Netbeheerkosten voor [product_type]</p>\r\n              <p class=\"mb-3\">Om van [product_type] gebruik te kunnen maken, dien je aangesloten te zijn op het openbare [product_type]netwerk van je netbeheerder. Hiervoor betaal je een vaste vergoeding die afhankelijk is van je aansluiting. Wij dragen deze vervolgens weer af aan je netbeheerder. Ook hier geldt dat de tarieven jaarlijks per 1 januari wijzigen. Om deze reden zie je onderstaand mogelijk weer twee berekeningen: voor de periode vóór en de periode ná 1 januari. </p>\r\n              <p> Je netbeheerder: <strong>[grid_operator_name]</strong>\r\n              </p>\r\n            </div>\r\n          </div>\r\n          <div class=\"mt-3 custom-table table_grid_operator\"> [grid_operator_item_dynamic_page] </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div class=\"row\">\r\n            <div class=\"col-12\">\r\n              <p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">4. Opzegboete voor tussentijdse opzegging</p>\r\n              <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">5. Opzegboete voor tussentijdse opzegging</p>\r\n              <p>Dit contract had een looptijd voor <span style=\"text-transform: lowercase;\">[contract_duration]</span>, maar is na [day_active_in_our_system] dagen opgezegd. Conform de afgesproken voorwaarden, wordt bij opzegging gedurende de vaste looptijd van het contract een opzegboete in rekening gebracht. Deze opzegboete is afhankelijk van de resterende looptijd van het contract en geldt per product ([product_type]). Voor een resterende looptijd van [remaning_days], bedraagt de opzegboete € [cancelation_fee_summary] per product. Hierbij houden we ons aan de richtlijnen van de Autoriteit Consument en Markt. </p>\r\n            </div>\r\n          </div>\r\n          <div class=\"mt-5\">\r\n            <table class=\"table table-custom [cancellation_fee_visible]\">\r\n              <thead>\r\n                <th class=\"pl-2 text-uppercase\">OPZEGBOETE VOOR CONTRACT MET RESTERENDE LOOPTIJD MEER DAN [contract_duration_title]</th>\r\n                <th class=\"pl-2 text-right\">BEDRAG</th>\r\n              </thead>\r\n              <tbody>\r\n                <tr class=\"[cancellation_fee_elk_visible]\">\r\n                  <td class=\"pl-2\"> Opzegboete stroom </td>\r\n                  <td class=\"pl-2 text-right\">€ [cancelation_fee_elk]</td>\r\n                </tr>\r\n                <tr class=\"[cancellation_fee_gas_visible]\">\r\n                  <td class=\"pl-2\"> Opzegboete gas </td>\r\n                  <td class=\"pl-2 text-right\">€ [cancelation_fee_gas]</td>\r\n                </tr>\r\n              </tbody>\r\n            </table>\r\n            <table>\r\n              <tbody>\r\n                <tr>\r\n                  <td style=\"height: 15px;\"></td>\r\n                </tr>\r\n                <tr>\r\n                  <td class=\"w-100\"></td>\r\n                  <td class=\"pl-2 text-right font-weight-bold text-nowrap t-nowrap\">\r\n                    <div class=\"border-top-bold position-relative\">\r\n                      <span class=\"pr-5\">Totaalbedrag opzegboete voor tussentijdse opzegging</span>\r\n                      <span>€ [cancelation_fee_last_page]</span>\r\n                    </div>\r\n                  </td>\r\n                </tr>\r\n              </tbody>\r\n            </table>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div class=\"row\">\r\n            <div class=\"col-12\">\r\n            	<p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">5. Totaal in rekening gebrachte termijnbedragen</p>\r\n              <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">6. Totaal in rekening gebrachte termijnbedragen</p>\r\n              <p>Hier zie je een overzicht van de door ons in rekening gebrachte termijnbedragen in de afgelopen periode (incl. btw). Een negatief termijnbedrag wordt als niet in rekening gebracht beschouwd en daarom als 0 weergegeven.</p>\r\n            </div>\r\n          </div>\r\n          <div class=\"mt-5\">\r\n            <table class=\"table table-custom\">\r\n              <thead>\r\n                <th class=\"pl-2 charge-item-month-column\">MAAND</th>\r\n                <th class=\"pl-2 charge-item-invoice-number\">FACTUURNUMMER</th>\r\n                <th class=\"pl-2 text-right\" colspan=\"2\">BEDRAG</th>\r\n              </thead>\r\n              <tbody> [charged_item_by_month] </tbody>\r\n            </table>\r\n            <table>\r\n              <tbody>\r\n                <tr>\r\n                  <td style=\"height: 15px;\"></td>\r\n                </tr>\r\n                <tr>\r\n                  <td class=\"w-100\"></td>\r\n                  <td class=\"pl-2 text-right font-weight-bold text-nowrap t-nowrap\">\r\n                    <div class=\"border-top-bold position-relative\">\r\n                      <span class=\"pr-5\">Totaal in rekening gebrachte termijnbedragen</span>\r\n                      <span>[total_generated_amount]</span>\r\n                    </div>\r\n                  </td>\r\n                </tr>\r\n              </tbody>\r\n            </table>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <div style=\"page-break-before: always\"></div>\r\n\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n          <div class=\"content\">\r\n            <div class=\"mt-2\">\r\n              <p class=\"font-weight-bold\">Jouw EAN-codes</p> [elk_gas_eans]\r\n            </div>\r\n            <div class=\"mt-5\">\r\n              <p class=\"font-weight-bold\">Btw-aangifte</p>\r\n              <p class=\"mb-0\">[reseller_name] handelt onder de leveranciersvergunning van Kikker Energie. In het geval je een btw-aangifte moet doen, dien je daarom de gegevens van Kikker Energie te gebruiken. De benodigde informatie van Kikker Energie en je netbeheerder vind je onderstaand: </p>\r\n            </div>\r\n            <div class=\"row mt-4\">\r\n              <div class=\"col-5\">\r\n                <p class=\"mb-0\"> Kikker Energie B.V. </br> Tolnasingel 12 </br> 2411PV Bodegraven </p>\r\n                <p class=\"mb-0\">KvK: 71246681</p>\r\n                <p class=\"mb-0\">Btw nr.: NL858635732B01</p>\r\n              </div>\r\n              <div class=\"col-5\">\r\n                <p class=\"mb-0\"> [grid_operator_name] </br> [grid_operator_house_nr] </br> [grid_operator_postcode] </p>\r\n                <p class=\"mb-0\">KvK: [grid_operator_kvk]</p>\r\n                <p class=\"mb-0\">Btw nr.: [grid_operator_btw]</p>\r\n              </div>\r\n            </div>\r\n          </div>\r\n        </div>\r\n    </div>\r\n  </body>\r\n</html>', NULL, NULL, 'nl', 'ke-pdf', NULL, '2023-11-27 09:07:13.152323', NULL);
INSERT IGNORE INTO `templates_reseller` (`Id`, `reseller_id`, `template_name`, `html_content`, `header_id`, `footer_id`, `language_code`, `CreatedBy`, `ModifiedBy`, `CreatedAt`, `ModifiedAt`) VALUES (169, 197, 'FINALBILL_TEMPLATE_MAIN_CANCELATION_FEE_V', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n  <head>\r\n    <title>Billing | Kikker</title>\r\n    <meta charset=\"utf-8\">\r\n    <link rel=\"icon\" href=\"asset/kikker-icon.ico\" />\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\r\n    <link rel=\"stylesheet\" href=\"https://storage.googleapis.com/kikkerprodbucket/static-files/pdf-css/site.css\">\r\n    <link rel=\"stylesheet\" href=\"https://storage.googleapis.com/kikkerprodbucket/static-files/pdf-css/final_bill.css\">\r\n  </head>\r\n  \r\n  <body>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div class=\"row header mr-0 ml-0\">\r\n            <div style=\"width: 33%;\">\r\n            </div>\r\n            <div class=\"[hide-header-invoice-info] header-invoice-info\">\r\n                <div class=\"d-flex justify-content-end\">\r\n                    <div class=\"space-span d-inline-block\" style=\"padding-top: 0\">\r\n                        <div class=\"mb-0 d-flex\">\r\n                            <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\">Klantnummer:</p>\r\n                            <p class=\"mb-0\">[client_number]</p>\r\n                        </div>\r\n                        <div class=\"mb-0 d-flex\">\r\n                            <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\"\r\n                                >Contractnummer:\r\n                            </p>\r\n                            <p class=\"mb-0\">[contract_number]</p>\r\n                        </div>\r\n                        <div class=\"mb-0 d-flex [hidden_contract_reference]\" style=\"flex-flow: row;\">\r\n                            <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\">Contractreferentie: </p>\r\n                            <p class=\"mb-0\">[contract_reference]</p>\r\n                        </div>\r\n                        <div class=\"mb-0 d-flex\">\r\n                            <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\"\r\n                                >Factuurnummer:\r\n                            </p>\r\n                            <p class=\"mb-0\">[invoice_number]</p>\r\n                        </div>\r\n                        <div class=\"mb-0 d-flex [company_name_visible]\" style=\"flex-flow: row;\">\r\n                            <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\">Bedrijfsnaam: </p>\r\n                            <p class=\"mb-0\">[company_name]</p>\r\n                        </div>\r\n                        <div class=\"mb-0 d-flex\" style=\"flex-flow: row;\">\r\n                            <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\">Energie intermediair: </p>\r\n                            <p class=\"mb-0\">[header_reseller_name]</p>\r\n                        </div>\r\n                        <div class=\"mb-0 d-flex\">\r\n                            <p class=\"text-right vertical-align-top pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\"\r\n                                >Leveringsadres:</p\r\n                            >\r\n                            <p class=\"mb-0\" class=\"d-inline-block\"\r\n                                >[delivery_address_street] [delivery_address_houseNr] [delivery_address_zipcode]<br><span class=\"text-capitalize\">[delivery_address_city]</span></p\r\n                            >\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n          <div class=\"row\">\r\n            <div class=\"col-12\">\r\n                <p class=\"mb-0\">\r\n                    <span class=\"float-right\">[date_generate_PDF]</span>\r\n                  </p>\r\n              <p class=\"mt-5\">Beste [customer_first_name],</p>\r\n              <p class=\"mt-4 [final_bill_visible]\">Dit is je eindafrekening over de verbruiksperiode van [final_bill_start_date] tot [final_bill_end_date] voor je leveringsadres [delivery_address_street] [delivery_address_houseNr] te <span class=\"text-capitalize\">[delivery_address_city]</span>. Je ontvangt deze afrekening omdat je contract met [reseller_name] eindigt. In deze eindafrekening berekenen we de kosten tot de einddatum van je contract. Indien je onlangs een nieuw [reseller_name]-contract hebt afgesloten, ontvang je hier apart bericht van. </p>\r\n              <p class=\"mt-4 [yearly_bill_visible]\">Dit is je jaarafrekening over de verbruiksperiode van [final_bill_start_date] tot [final_bill_end_date] voor je leveringsadres [delivery_address_street] [delivery_address_houseNr] te <span class=\"text-capitalize\">[delivery_address_city]</span>. In deze jaarafrekening vind je een overzicht van je energieverbruik in het afgelopen jaar en wat je hiervoor hebt betaald. </p>\r\n            </div>\r\n          </div>\r\n          [FINALBILL_TEMPLATE_UNPAID_AMOUNT_INVOICE_ITEM]\r\n          [FINALBILL_TEMPLATE_PAID_AMOUNT_INVOICE_ITEM]\r\n          <div>\r\n            <p class=\"mb-1 font-weight-bold [yearly_bill_visible] [new_monthly_amount_visible]\"> \r\n                <span>Je nieuwe termijnbedrag </span>\r\n            </p>\r\n            <p class=\"mb-4 [yearly_bill_visible] [new_monthly_amount_visible]\"> Op basis van je verbruik in de afgelopen 12 maanden, hebben we een nieuw termijnbedrag voor je uitgerekend. We passen het termijnbedrag automatisch voor je aan. Ben je het niet eens met je nieuwe termijnbedrag? Dan kun je dit gemakkelijk aanpassen in onze mobiele app. </p>\r\n          </div>\r\n          <div class=\"row monthly-amount-block [yearly_bill_visible] [new_monthly_amount_visible] mt-4\" style=\"background-image: url(\'data:image/png;base64,\');background-size: 100%; background-repeat: no-repeat; background-position: center center;\">\r\n            <div class=\"col-6\">\r\n              <span> Oude termijnbedrag </span>\r\n              <span class=\"float-right\"> € [current_monthly_amount] </span>\r\n            </div>\r\n            <div class=\"col-6 pl-5 font-weight-bold\">\r\n              <span> Nieuwe termijnbedrag </span>\r\n              <span class=\"float-right\"> € [new_monthly_amount] </span>\r\n            </div>\r\n          </div>\r\n          <div class=\"mt-4 avoid-break-page\">\r\n            <p class=\"font-weight-bold mb-1\">Vragen?</p>\r\n            <p class=\"mb-3\" style=\"text-align: left;\">Neem contact op met jouw wederverkoper [reseller_name]. Dit kun je doen via e-mail op [reseller_email] of telefonisch op [reseller_phone].</p>\r\n            <p class=\"mb-3\">Met vriendelijke groet, </p>\r\n            <p class=\"mb-0\">[reseller_name]</p>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div class=\"row\">\r\n            <div class=\"col-12\">\r\n              <p>Meer informatie over je verbruik of de precieze berekening van je <span class=\"[final_bill_visible]\">eindafrekening</span> <span class=\"[yearly_bill_visible]\">jaarafrekening</span> vind je op de volgende pagina’s.</p>\r\n              <p class=\"mb-1 font-weight-bold\">Samenvatting van je <span class=\"[final_bill_visible]\">eindafrekening</span>\r\n                <span class=\"[yearly_bill_visible]\">jaarafrekening</span>\r\n              </p>\r\n            </div>\r\n          </div>\r\n          <div class=\"[hide_text_summary]\">[text_summary]</div>\r\n          <div class=\"mt-5 table-first\">\r\n            <table class=\"table\">\r\n              <tbody>\r\n                <tr>\r\n                  <td class=\"pl-2\"> 1. Leveringskosten van [product_type] </td>\r\n                  <td class=\"pl-2 text-right\">[total_delivery_amount]</td>\r\n                </tr>\r\n                <tr class=\"[show_price_cap_billing]\">\r\n                    <td class=\"pl-2\"> 2. Tegemoetkoming uit het prijsplafond</td>\r\n                    <td class=\"pl-2 text-right\">[total_price_cap]</td>\r\n                </tr>\r\n                <tr>\r\n                    <td class=\"pl-2 [hide_price_cap_billing]\"> 2. Overheidsheffingen op [product_type], dit dragen we af aan de overheid </td>\r\n                    <td class=\"pl-2 [show_price_cap_billing]\"> 3. Overheidsheffingen op [product_type], dit dragen we af aan de overheid </td>\r\n                    <td class=\"pl-2 text-right\">[total_tax_amount]</td>\r\n                </tr>\r\n                <tr>\r\n                    <td class=\"pl-2 [hide_price_cap_billing]\"> 3. Netbeheerkosten op [product_type], dit dragen we af aan je netbeheerder </td>\r\n                    <td class=\"pl-2 [show_price_cap_billing]\"> 4. Netbeheerkosten op [product_type], dit dragen we af aan je netbeheerder </td>\r\n                    <td class=\"pl-2 text-right\">[total_grid_operator_amount]</td>\r\n                </tr>\r\n                <tr>\r\n                    <td class=\"pl-2 [hide_price_cap_billing]\"> 4. Opzegboete voor tussentijdse opzegging </td>\r\n                    <td class=\"pl-2 [show_price_cap_billing]\"> 5. Opzegboete voor tussentijdse opzegging </td>\r\n                    <td class=\"pl-2 text-right\">[cancelation_fee]</td>\r\n                </tr>\r\n                <tr>\r\n                  <td class=\"pl-2 font-weight-bold\"></td>\r\n                  <td class=\"pl-2 text-right  font-weight-bold\">[total_real_amount_incl_cancel_fee]</td>\r\n                </tr>\r\n              </tbody>\r\n            </table>\r\n          </div>\r\n          <div class=\"mt-4 table-first\">\r\n            <table class=\"table\">\r\n              <tbody>\r\n                <tr>\r\n                    <td class=\"pl-2 [hide_price_cap_billing]\"> 5. In rekening gebrachte termijnbedragen </td>\r\n                    <td class=\"pl-2 [show_price_cap_billing]\"> 6. In rekening gebrachte termijnbedragen </td>\r\n                    <td class=\"pl-2 text-right\">[total_generated_amount_negative]</td>\r\n                </tr>\r\n                <tr class=\"[total_unpaid_amount_class]\">\r\n                  <td class=\"pl-4 font-italic\"> Openstaande termijnbedragen </td>\r\n                  <td class=\"pl-2 text-right\">[total_unpaid_amount]</td>\r\n                </tr>\r\n                <tr class=\"[total_collection_cost_amount_class]\">\r\n                  <td class=\"pl-4 font-italic\"> Openstaande incassokosten </td>\r\n                  <td class=\"pl-2 text-right\">[total_collection_cost_amount]</td>\r\n                </tr>\r\n                <tr>\r\n                  <td class=\"pl-2 font-weight-bold\"></td>\r\n                  <td class=\"pl-2 text-right  font-weight-bold\">[total_real_generated_amount_negative]</td>\r\n                </tr>\r\n              </tbody>\r\n            </table>\r\n            <table>\r\n              <tbody>\r\n                <tr>\r\n                  <td class=\"w-100\"></td>\r\n                  <td class=\"pl-2 text-right font-weight-bold text-nowrap t-nowrap\">\r\n                    <div class=\"border-top-bold position-relative\">\r\n                      <span class=\"pr-5\">[is_receive]</span>\r\n                      <span>€ [difference_amount]</span>\r\n                    </div>\r\n                  </td>\r\n                </tr>\r\n              </tbody>\r\n            </table>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div class=\"[usage_only_gas_elk_visible]\">\r\n            <p class=\"mb-1 font-weight-bold\"> Berekening van je verbruik </p>\r\n            <p> Op basis van je meterstanden bepalen wij hoeveel energie je hebt verbruikt. De meterstanden lezen wij uit via je slimme meter, vragen wij bij je op of berekenen we zelf. Onderstaand vind je een overzicht van je verbruik per periode. Omdat tussen periodes soms verschillende tarieven gelden, kan het zijn dat je verschillende periodes ziet. </p>\r\n          </div>\r\n          <div class=\"mt-5 [usage_only_gas_elk_visible]\"> [usage_item_by_ean] </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div class=\"[usage_only_gas_elk_visible]\" style=\"page-break-before: always\"></div>\r\n    <div class=\"page [usage_both_gas_elk_visible]\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div>\r\n                    <p class=\"mb-1 font-weight-bold\">\r\n                        Berekening van je verbruik\r\n                    </p>\r\n                    <p class=\"mb-5\">\r\n                        Op basis van je meterstanden bepalen wij hoeveel energie je hebt verbruikt. De meterstanden lezen wij uit via je\r\n                        slimme meter, vragen wij bij je op of berekenen we zelf. Onderstaand vind je een overzicht van je\r\n                        verbruik per periode. Omdat tussen periodes soms verschillende tarieven gelden, kan het zijn dat je verschillende\r\n                        periodes ziet.\r\n                    </p>\r\n                </div>\r\n\r\n                <div class=\"table-usage\">\r\n                    [usage_item_by_ean]\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    <div class=\"[usage_both_gas_elk_visible]\" style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div>\r\n            <p class=\"mb-4\">Op de volgende pagina’s vind je een nadere specificatie van de kosten die weergegeven zijn op pagina 2.</p>\r\n            [return_tariff_section]\r\n            <p class=\"mb-1 font-weight-bold\">1. Leveringskosten voor [product_type]</p>\r\n            <p class=\"mb-5\"> Onderstaand vind je een specificatie van je leveringskosten voor [product_type]. Door je verbruik te vermenigvuldigen met je tarief bepalen we je kosten per contract. </p>\r\n          </div>\r\n          <div class=\"table_fixed_delivery\"> [fixed_delivery_item_dynamic_page] </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    [price_cap_section_template]\r\n\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div class=\"row\">\r\n            <div class=\"col-12\">\r\n                <p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">2. Overheidsheffingen op [product_type]</p>\r\n                <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">3. Overheidsheffingen op [product_type]</p>\r\n              <p style=\"display: [show_new_ode_tax_description]\">Naast de kosten voor het verbruik van [product_type], moet je ook belastingen betalen aan de overheid. Ook deze zijn afhankelijk van je verbruik. Onderstaande kosten dragen wij direct af aan de overheid. Omdat de heffingen jaarlijks (per 1 januari) veranderen zie je onderstaand mogelijk twee berekeningen: een voor de periode vóór en een voor de periode ná 1 januari.</p>\r\n            </div>\r\n          </div>\r\n          <div class=\"mt-3\"> [tax_item_dynamic_page] </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div class=\"row\">\r\n            <div class=\"col-12\">\r\n            <p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">3. Netbeheerkosten voor [product_type]</p>\r\n            <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">4. Netbeheerkosten voor [product_type]</p>\r\n              <p class=\"mb-3\">Om van [product_type] gebruik te kunnen maken, dien je aangesloten te zijn op het openbare [product_type]netwerk van je netbeheerder. Hiervoor betaal je een vaste vergoeding die afhankelijk is van je aansluiting. Wij dragen deze vervolgens weer af aan je netbeheerder. Ook hier geldt dat de tarieven jaarlijks per 1 januari wijzigen. Om deze reden zie je onderstaand mogelijk weer twee berekeningen: voor de periode vóór en de periode ná 1 januari. </p>\r\n              <p> Je netbeheerder: <strong>[grid_operator_name]</strong>\r\n              </p>\r\n            </div>\r\n          </div>\r\n          <div class=\"mt-3 custom-table table_grid_operator\"> [grid_operator_item_dynamic_page] </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div class=\"row\">\r\n            <div class=\"col-12\">\r\n                <p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">4. Opzegboete voor tussentijdse opzegging</p>\r\n                <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">5. Opzegboete voor tussentijdse opzegging</p>\r\n              <p>Dit contract had een looptijd voor <span style=\"text-transform: lowercase;\">[contract_duration]</span>, maar is na [day_active_in_our_system] dagen opgezegd. Conform de afgesproken voorwaarden, wordt bij opzegging gedurende de vaste looptijd van het contract een opzegboete in rekening gebracht. Deze opzegboete is afhankelijk van de resterende looptijd van het contract en geldt per product ([product_type]). Voor een resterende looptijd van [remaning_days], bedraagt de opzegboete € [cancelation_fee_summary] per product. Hierbij houden we ons aan de richtlijnen van de Autoriteit Consument en Markt. </p>\r\n            </div>\r\n          </div>\r\n          <div class=\"mt-5\">\r\n            <table class=\"table table-custom [cancellation_fee_visible]\">\r\n              <thead>\r\n                <th class=\"pl-2 text-uppercase\">OPZEGBOETE VOOR CONTRACT MET RESTERENDE LOOPTIJD MEER DAN [contract_duration_title]</th>\r\n                <th class=\"pl-2 text-right\">BEDRAG</th>\r\n              </thead>\r\n              <tbody>\r\n                <tr class=\"[cancellation_fee_elk_visible]\">\r\n                  <td class=\"pl-2\"> Opzegboete stroom </td>\r\n                  <td class=\"pl-2 text-right\">€ [cancelation_fee_elk]</td>\r\n                </tr>\r\n                <tr class=\"[cancellation_fee_gas_visible]\">\r\n                  <td class=\"pl-2\"> Opzegboete gas </td>\r\n                  <td class=\"pl-2 text-right\">€ [cancelation_fee_gas]</td>\r\n                </tr>\r\n              </tbody>\r\n            </table>\r\n            <table>\r\n              <tbody>\r\n                <tr>\r\n                  <td style=\"height: 15px;\"></td>\r\n                </tr>\r\n                <tr>\r\n                  <td class=\"w-100\"></td>\r\n                  <td class=\"pl-2 text-right font-weight-bold text-nowrap t-nowrap\">\r\n                    <div class=\"border-top-bold position-relative\">\r\n                      <span class=\"pr-5\">Totaalbedrag opzegboete voor tussentijdse opzegging</span>\r\n                      <span>€ [cancelation_fee_last_page]</span>\r\n                    </div>\r\n                  </td>\r\n                </tr>\r\n              </tbody>\r\n            </table>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div class=\"row\">\r\n            <div class=\"col-12\">\r\n              <p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">5. Totaal in rekening gebrachte termijnbedragen</p>\r\n                <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">6. Totaal in rekening gebrachte termijnbedragen</p>\r\n              <p>Hier zie je een overzicht van de door ons in rekening gebrachte termijnbedragen in de afgelopen periode (incl. btw). Een negatief termijnbedrag wordt als niet in rekening gebracht beschouwd en daarom als 0 weergegeven.</p>\r\n            </div>\r\n          </div>\r\n          <div class=\"mt-5\">\r\n            <table class=\"table table-custom\">\r\n              <thead>\r\n                <th class=\"pl-2 charge-item-month-column\">MAAND</th>\r\n                <th class=\"pl-2 charge-item-invoice-number\">FACTUURNUMMER</th>\r\n                <th class=\"pl-2 text-right\" colspan=\"2\">BEDRAG</th>\r\n              </thead>\r\n              <tbody> [charged_item_by_month] </tbody>\r\n            </table>\r\n            <table>\r\n              <tbody>\r\n                <tr>\r\n                  <td style=\"height: 15px;\"></td>\r\n                </tr>\r\n                <tr>\r\n                  <td class=\"w-100\"></td>\r\n                  <td class=\"pl-2 text-right font-weight-bold text-nowrap t-nowrap\">\r\n                    <div class=\"border-top-bold position-relative\">\r\n                      <span class=\"pr-5\">Totaal in rekening gebrachte termijnbedragen</span>\r\n                      <span>[total_generated_amount]</span>\r\n                    </div>\r\n                  </td>\r\n                </tr>\r\n              </tbody>\r\n            </table>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <div style=\"page-break-before: always\"></div>\r\n\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n          <div class=\"content\">\r\n            <div class=\"mt-2\">\r\n              <p class=\"font-weight-bold\">Jouw EAN-codes</p> [elk_gas_eans]\r\n            </div>\r\n            <div class=\"mt-5\">\r\n              <p class=\"font-weight-bold\">Btw-aangifte</p>\r\n              <p class=\"mb-0\"> [reseller_name] handelt onder de leveranciersvergunning van Kikker Energie. In het geval je een btw-aangifte moet doen, dien je daarom de gegevens van Kikker Energie te gebruiken. De benodigde informatie van Kikker Energie en je netbeheerder vind je onderstaand: </p>\r\n            </div>\r\n            <div class=\"row mt-4\">\r\n              <div class=\"col-5\">\r\n                <p class=\"mb-0\"> Kikker Energie B.V. </br> Tolnasingel 12 </br> 2411PV Bodegraven </p>\r\n                <p class=\"mb-0\">KvK: 71246681</p>\r\n                <p class=\"mb-0\">Btw nr.: NL858635732B01</p>\r\n              </div>\r\n              <div class=\"col-5\">\r\n                <p class=\"mb-0\"> [grid_operator_name] </br> [grid_operator_house_nr] </br> [grid_operator_postcode] </p>\r\n                <p class=\"mb-0\">KvK: [grid_operator_kvk]</p>\r\n                <p class=\"mb-0\">Btw nr.: [grid_operator_btw]</p>\r\n              </div>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n  </body>\r\n</html>', NULL, NULL, 'nl', 'ke-pdf', NULL, '2023-11-27 09:07:13.152323', NULL);
INSERT IGNORE INTO `templates_reseller` (`Id`, `reseller_id`, `template_name`, `html_content`, `header_id`, `footer_id`, `language_code`, `CreatedBy`, `ModifiedBy`, `CreatedAt`, `ModifiedAt`) VALUES (176, 197, 'FINALBILL_TEMPLATE_MAIN_KFM', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n  <head>\r\n    <title>Billing | Kikker</title>\r\n    <link rel=\"icon\" href=\"asset/kikker-icon.ico\" />\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\r\n    <link rel=\"stylesheet\" href=\"https://storage.googleapis.com/kikkerprodbucket/static-files/pdf-css/site.css\">\r\n    <link rel=\"stylesheet\" href=\"https://storage.googleapis.com/kikkerprodbucket/static-files/pdf-css/final_bill.css\">\r\n  </head>\r\n  <body>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div class=\"row header mr-0 ml-0\">\r\n            <div style=\"width: 33%;\">\r\n            </div>\r\n            <div class=\"[hide-header-invoice-info] header-invoice-info\">\r\n                <div class=\"d-flex justify-content-end\">\r\n                    <div class=\"space-span d-inline-block\" style=\"padding-top: 0\">\r\n                        <div class=\"mb-0 d-flex\">\r\n                            <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\">Klantnummer:</p>\r\n                            <p class=\"mb-0\">[client_number]</p>\r\n                        </div>\r\n                        <div class=\"mb-0 d-flex\">\r\n                            <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\"\r\n                                >Contractnummer:\r\n                            </p>\r\n                            <p class=\"mb-0\">[contract_number]</p>\r\n                        </div>\r\n                        <div class=\"mb-0 d-flex [hidden_contract_reference]\" style=\"flex-flow: row;\">\r\n                            <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\">Contractreferentie: </p>\r\n                            <p class=\"mb-0\">[contract_reference]</p>\r\n                        </div>\r\n                        <div class=\"mb-0 d-flex\">\r\n                            <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\"\r\n                                >Factuurnummer:\r\n                            </p>\r\n                            <p class=\"mb-0\">[invoice_number]</p>\r\n                        </div>\r\n                        <div class=\"mb-0 d-flex [company_name_visible]\" style=\"flex-flow: row;\">\r\n                            <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\">Bedrijfsnaam: </p>\r\n                            <p class=\"mb-0\">[company_name]</p>\r\n                        </div>\r\n                        <div class=\"mb-0 d-flex\" style=\"flex-flow: row;\">\r\n                            <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\">Energie intermediair: </p>\r\n                            <p class=\"mb-0\">[header_reseller_name]</p>\r\n                        </div>\r\n                        <div class=\"mb-0 d-flex\">\r\n                            <p class=\"text-right vertical-align-top pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\"\r\n                                >Leveringsadres:</p\r\n                            >\r\n                            <p class=\"mb-0\" class=\"d-inline-block\"\r\n                                >[delivery_address_street] [delivery_address_houseNr] [delivery_address_zipcode]<br><span class=\"text-capitalize\">[delivery_address_city]</span></p\r\n                            >\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n          <div class=\"row\">\r\n            <div class=\"col-12\">\r\n                <p class=\"mb-5\">\r\n                <span class=\"float-right\">[date_generate_PDF]</span>\r\n              </p>\r\n              <p class=\"mb-4\">Beste [customer_first_name],</p>\r\n              <p class=\"mb-4 [final_bill_visible]\">Dit is je eindafrekening over de verbruiksperiode van [final_bill_start_date] tot [final_bill_end_date] voor je leveringsadres [delivery_address_street] [delivery_address_houseNr] te <span class=\"text-capitalize\">[delivery_address_city]</span>. Je ontvangt deze afrekening omdat je contract met [reseller_name] eindigt. In deze eindafrekening berekenen we de kosten tot de einddatum van je contract. Indien je onlangs een nieuw [reseller_name]-contract hebt afgesloten, ontvang je hier apart bericht van. </p>\r\n              <p class=\"mb-4 [yearly_bill_visible]\">Dit is je jaarafrekening over de verbruiksperiode van [final_bill_start_date] tot [final_bill_end_date] voor je leveringsadres [delivery_address_street] [delivery_address_houseNr] te <span class=\"text-capitalize\">[delivery_address_city]</span>. In deze jaarafrekening vind je een overzicht van je energieverbruik in het afgelopen jaar en wat je hiervoor hebt betaald. </p>\r\n            </div>\r\n          </div>\r\n          [FINALBILL_TEMPLATE_UNPAID_AMOUNT_INVOICE_ITEM]\r\n          [FINALBILL_TEMPLATE_PAID_AMOUNT_INVOICE_ITEM]\r\n          <div>\r\n            <p class=\"mb-1 font-weight-bold [yearly_bill_visible] [new_monthly_amount_visible]\"> Je nieuwe termijnbedrag </span>\r\n            </p>\r\n            <p class=\"mb-4 [yearly_bill_visible] [new_monthly_amount_visible]\"> Op basis van je verbruik in de afgelopen 12 maanden, hebben we een nieuw termijnbedrag voor je uitgerekend. We passen het termijnbedrag automatisch voor je aan. Ben je het niet eens met je nieuwe termijnbedrag? Dan kun je dit gemakkelijk aanpassen in onze mobiele app. </p>\r\n          </div>\r\n          <div class=\"row monthly-amount-block [yearly_bill_visible] [new_monthly_amount_visible] mt-4\" style=\"background-image: url(\'data:image/png;base64,\');background-size: 100%; background-repeat: no-repeat; background-position: center center;\">\r\n            <div class=\"col-6\">\r\n              <span> Oude termijnbedrag </span>\r\n              <span class=\"float-right\"> € [current_monthly_amount] </span>\r\n            </div>\r\n            <div class=\"col-6 pl-5 font-weight-bold\">\r\n              <span> Nieuwe termijnbedrag </span>\r\n              <span class=\"float-right\"> € [new_monthly_amount] </span>\r\n            </div>\r\n          </div>\r\n          <div class=\"mt-4 avoid-break-page\">\r\n            <p class=\"font-weight-bold mb-1\">Vragen?</p>\r\n            <p class=\"mb-3\" style=\"text-align: left;\">Je kunt altijd contact met ons opnemen via [reseller_email] of bellen naar [reseller_phone]</p>\r\n            <p class=\"mb-3\">Met vriendelijke groet, </p>\r\n            <p class=\"mb-0\">[reseller_name]</p>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div>\r\n          <p>Meer informatie over je verbruik of de precieze berekening van je <span class=\"[final_bill_visible]\">eindafrekening</span> <span class=\"[yearly_bill_visible]\">jaarafrekening</span> vind je op de volgende pagina’s.</p>\r\n          <div class=\"mb-1 font-weight-bold\">Samenvatting van je <span class=\"[final_bill_visible]\">eindafrekening</span>\r\n            <span class=\"[yearly_bill_visible]\">jaarafrekening</span>\r\n          </div>\r\n          <div class=\"[hide_text_summary]\">[text_summary]</div>\r\n          <div class=\"mt-5\">\r\n            <table class=\"table table-first\">\r\n              <tbody>\r\n                <tr>\r\n                  <td class=\"pl-2\"> 1. Leveringskosten van [product_type] </td>\r\n                  <td class=\"pl-2 text-right\">[total_delivery_amount]</td>\r\n                </tr>\r\n                <tr class=\"[show_price_cap_billing]\">\r\n                  <td class=\"pl-2\"> 2. Tegemoetkoming uit het prijsplafond</td>\r\n                  <td class=\"pl-2 text-right\">[total_price_cap]</td>\r\n                </tr>\r\n                <tr>\r\n                  <td class=\"pl-2 [hide_price_cap_billing]\"> 2. Overheidsheffingen op [product_type], dit dragen we af aan de overheid </td>\r\n                  <td class=\"pl-2 [show_price_cap_billing]\"> 3. Overheidsheffingen op [product_type], dit dragen we af aan de overheid </td>\r\n                  <td class=\"pl-2 text-right\">[total_tax_amount]</td>\r\n                </tr>\r\n                <tr>\r\n                  <td class=\"pl-2 [hide_price_cap_billing]\"> 3. Netbeheerkosten op [product_type], dit dragen we af aan je netbeheerder </td>\r\n                  <td class=\"pl-2 [show_price_cap_billing]\"> 4. Netbeheerkosten op [product_type], dit dragen we af aan je netbeheerder </td>\r\n                  <td class=\"pl-2 text-right\">[total_grid_operator_amount]</td>\r\n                </tr>\r\n                <tr>\r\n                  <td class=\"pl-2 font-weight-bold\"></td>\r\n                  <td class=\"pl-2 text-right  font-weight-bold\">[total_real_amount_incl_cancel_fee]</td>\r\n                </tr>\r\n              </tbody>\r\n            </table>\r\n          </div>\r\n          <div class=\"mt-5\">\r\n            <table class=\"table table-first\">\r\n              <tbody>\r\n                <tr>\r\n                  <td class=\"pl-2 [hide_price_cap_billing]\"> 4. In rekening gebrachte termijnbedragen </td>\r\n                  <td class=\"pl-2 [show_price_cap_billing]\"> 5. In rekening gebrachte termijnbedragen </td>\r\n                  <td class=\"pl-2 text-right\">[total_generated_amount_negative]</td>\r\n                </tr>\r\n                <tr class=\"[total_unpaid_amount_class]\">\r\n                  <td class=\"pl-4 font-italic\"> Openstaande termijnbedragen </td>\r\n                  <td class=\"pl-2 text-right\">[total_unpaid_amount]</td>\r\n                </tr>\r\n                <tr class=\"[total_collection_cost_amount_class]\">\r\n                  <td class=\"pl-4 font-italic\"> Openstaande incassokosten </td>\r\n                  <td class=\"pl-2 text-right\">[total_collection_cost_amount]</td>\r\n                </tr>\r\n                <tr>\r\n                  <td class=\"pl-2 font-weight-bold\"></td>\r\n                  <td class=\"pl-2 text-right  font-weight-bold\">[total_real_generated_amount_negative]</td>\r\n                </tr>\r\n              </tbody>\r\n            </table>\r\n            <table>\r\n              <tbody>\r\n                <tr>\r\n                  <td class=\"w-100\"></td>\r\n                  <td class=\"pl-2 text-right font-weight-bold text-nowrap t-nowrap\">\r\n                    <div class=\"border-top-bold position-relative\">\r\n                      <span class=\"pr-5\">[is_receive]</span>\r\n                      <span>€ [difference_amount]</span>\r\n                    </div>\r\n                  </td>\r\n                </tr>\r\n              </tbody>\r\n            </table>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div class=\"[usage_only_gas_elk_visible]\">\r\n            <p class=\"mb-1 font-weight-bold\"> Berekening van je verbruik </p>\r\n            <p class=\"mb-5\"> Op basis van je meterstanden bepalen wij hoeveel energie je hebt verbruikt. De meterstanden lezen wij uit via je slimme meter, vragen wij bij je op of berekenen we zelf. Onderstaand vind je een overzicht van je verbruik per periode. Omdat tussen periodes soms verschillende tarieven gelden, kan het zijn dat je verschillende periodes ziet. </p>\r\n          </div>\r\n          <div class=\"[usage_only_gas_elk_visible]\"> [usage_item_by_ean] </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div class=\"[usage_only_gas_elk_visible]\" style=\"page-break-before: always\"></div>\r\n    <div class=\"page [usage_both_gas_elk_visible]\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div>\r\n            <p class=\"mb-1 font-weight-bold\"> Berekening van je verbruik </p>\r\n            <p class=\"mb-5\"> Op basis van je meterstanden bepalen wij hoeveel energie je hebt verbruikt. De meterstanden lezen wij uit via je slimme meter, vragen wij bij je op of berekenen we zelf. Onderstaand vind je een overzicht van je verbruik per periode. Omdat tussen periodes soms verschillende tarieven gelden, kan het zijn dat je verschillende periodes ziet. </p>\r\n          </div>\r\n          <div> [usage_item_by_ean] </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div class=\"[usage_both_gas_elk_visible]\" style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div>\r\n            <p class=\"mb-4\">Op de volgende pagina’s vind je een nadere specificatie van de kosten die weergegeven zijn op pagina 2.</p>\r\n            [return_tariff_section]\r\n            <p class=\"mb-1 font-weight-bold\">1. Leveringskosten voor [product_type]</p>\r\n            <p class=\"mb-5\"> Onderstaand vind je een specificatie van je leveringskosten voor [product_type]. Door je verbruik te vermenigvuldigen met je tarief bepalen we je kosten per contract. </p>\r\n          </div>\r\n          <div class=\"table_fixed_delivery\"> [fixed_delivery_item_dynamic_page] </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    [price_cap_section_template]\r\n\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div class=\"row\">\r\n            <div class=\"col-12\">\r\n              <p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">2. Overheidsheffingen op [product_type]</p>\r\n              <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">3. Overheidsheffingen op [product_type]</p>\r\n              <p style=\"display: [show_new_ode_tax_description]\">Naast de kosten voor het verbruik van [product_type], moet je ook belastingen betalen aan de overheid. Ook deze zijn afhankelijk van je verbruik. Onderstaande kosten dragen wij direct af aan de overheid. Omdat de heffingen jaarlijks (per 1 januari) veranderen zie je onderstaand mogelijk twee berekeningen: een voor de periode vóór en een voor de periode ná 1 januari.</p>\r\n            </div>\r\n          </div>\r\n          <div class=\"mt-3\"> [tax_item_dynamic_page] </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div class=\"row\">\r\n            <div class=\"col-12\">\r\n              <p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">3. Netbeheerkosten voor [product_type]</p>\r\n              <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">4. Netbeheerkosten voor [product_type]</p>\r\n              <p class=\"mb-3\">Om van [product_type] gebruik te kunnen maken, dien je aangesloten te zijn op het openbare [product_type]netwerk van je netbeheerder. Hiervoor betaal je een vaste vergoeding die afhankelijk is van je aansluiting. Wij dragen deze vervolgens weer af aan je netbeheerder. Ook hier geldt dat de tarieven jaarlijks per 1 januari wijzigen. Om deze reden zie je onderstaand mogelijk weer twee berekeningen: voor de periode vóór en de periode ná 1 januari. </p>\r\n              <p> Je netbeheerder: <strong>[grid_operator_name]</strong>\r\n              </p>\r\n            </div>\r\n          </div>\r\n          <div class=\"mt-3 custom-table table_grid_operator\"> [grid_operator_item_dynamic_page] </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n          <div class=\"content\">\r\n            <div class=\"row\">\r\n              <div class=\"col-12\">\r\n              	<p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">4. Totaal in rekening gebrachte termijnbedragen</p>\r\n                <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">5. Totaal in rekening gebrachte termijnbedragen</p>\r\n                <p class=\"mb-1\">Hier zie je een overzicht van de door ons in rekening gebrachte termijnbedragen in de afgelopen periode (incl. btw). Een negatief termijnbedrag wordt als niet in rekening gebracht beschouwd en daarom als 0 weergegeven.</p>\r\n              </div>\r\n            </div>\r\n            <div class=\"mt-5\">\r\n              <table class=\"table table-custom\">\r\n                <thead>\r\n                  <th class=\"pl-2 charge-item-month-column\">MAAND</th>\r\n                  <th class=\"pl-2 charge-item-invoice-number\">FACTUURNUMMER</th>\r\n                  <th class=\"pl-2 text-right\" colspan=\"2\">BEDRAG</th>\r\n                </thead>\r\n                <tbody> [charged_item_by_month] </tbody>\r\n              </table>\r\n              <table>\r\n                <tbody>\r\n                  <tr>\r\n                    <td style=\"height: 15px;\"></td>\r\n                  </tr>\r\n                  <tr>\r\n                    <td class=\"w-100\"></td>\r\n                    <td class=\"pl-2 text-right font-weight-bold text-nowrap t-nowrap\">\r\n                      <div class=\"border-top-bold position-relative\">\r\n                        <span class=\"pr-5\">Totaal in rekening gebrachte termijnbedragen</span>\r\n                        <span>[total_generated_amount]</span>\r\n                      </div>\r\n                    </td>\r\n                  </tr>\r\n                </tbody>\r\n              </table>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n      <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div>\r\n            <p class=\"font-weight-bold\">Jouw EAN-codes</p> [elk_gas_eans]\r\n          </div>\r\n          <div class=\"mt-5\">\r\n            <p class=\"font-weight-bold\">Btw-aangifte</p>\r\n            <p class=\"mb-0\">\r\n              [reseller_name] handelt onder de leveranciersvergunning van Kikker Energie. In het geval je een btw-aangifte moet doen, dien je daarom de gegevens van Kikker Energie te gebruiken. De benodigde informatie van Kikker Energie en je netbeheerder vind je onderstaand:\r\n            </p>\r\n          </div>\r\n          <div class=\"row mt-4\">\r\n            <div class=\"col-5\">\r\n              <p class=\"mb-0\">\r\n                Kikker Energie B.V.</br>\r\n                Tolnasingel 12 </br> 2411PV Bodegraven\r\n            </p>\r\n              <p class=\"mb-0\">KvK: 71246681</p>\r\n              <p class=\"mb-0\">Btw nr.: NL858635732B01</p>\r\n            </div>\r\n            <div class=\"col-5\">\r\n              <p class=\"mb-0\"> [grid_operator_name] </br> [grid_operator_house_nr] </br> [grid_operator_postcode] </p>\r\n              <p class=\"mb-0\">KvK: [grid_operator_kvk]</p>\r\n              <p class=\"mb-0\">Btw nr.: [grid_operator_btw]</p>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </body>\r\n</html>', NULL, NULL, 'nl', 'ke-pdf', NULL, '2023-11-27 09:07:13.152323', NULL);
INSERT IGNORE INTO `templates_reseller` (`Id`, `reseller_id`, `template_name`, `html_content`, `header_id`, `footer_id`, `language_code`, `CreatedBy`, `ModifiedBy`, `CreatedAt`, `ModifiedAt`) VALUES (183, 197, 'FINALBILL_TEMPLATE_MAIN_KX', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n  <head>\r\n    <title>Billing | Kikker</title>\r\n    <meta charset=\"utf-8\">\r\n    <link rel=\"icon\" href=\"asset/kikker-icon.ico\" />\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\r\n    <link rel=\"stylesheet\" href=\"https://storage.googleapis.com/kikkerprodbucket/static-files/pdf-css/site.css\">\r\n    <link rel=\"stylesheet\" href=\"https://storage.googleapis.com/kikkerprodbucket/static-files/pdf-css/final_bill.css\">\r\n  </head>\r\n  <body>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div class=\"row header mr-0 ml-0\">\r\n              <div style=\"width: 33%;\">\r\n              </div>\r\n              <div class=\"[hide-header-invoice-info] header-invoice-info\">\r\n                  <div class=\"d-flex justify-content-end\">\r\n                      <div class=\"space-span d-inline-block\" style=\"padding-top: 0\">\r\n                          <div class=\"mb-0 d-flex\">\r\n                              <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\">Klantnummer:</p>\r\n                              <p class=\"mb-0\">[client_number]</p>\r\n                          </div>\r\n                          <div class=\"mb-0 d-flex\">\r\n                              <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\"\r\n                                  >Contractnummer:\r\n                              </p>\r\n                              <p class=\"mb-0\">[contract_number]</p>\r\n                          </div>\r\n                          <div class=\"mb-0 d-flex [hidden_contract_reference]\" style=\"flex-flow: row;\">\r\n                              <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\">Contractreferentie: </p>\r\n                              <p class=\"mb-0\">[contract_reference]</p>\r\n                          </div>\r\n                          <div class=\"mb-0 d-flex\">\r\n                              <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\"\r\n                                  >Factuurnummer:\r\n                              </p>\r\n                              <p class=\"mb-0\">[invoice_number]</p>\r\n                          </div>\r\n                          <div class=\"mb-0 d-flex [company_name_visible]\" style=\"flex-flow: row;\">\r\n                              <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\">Bedrijfsnaam: </p>\r\n                              <p class=\"mb-0\">[company_name]</p>\r\n                          </div>\r\n                          <div class=\"mb-0 d-flex\" style=\"flex-flow: row;\">\r\n                              <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\">Energie intermediair: </p>\r\n                              <p class=\"mb-0\">[header_reseller_name]</p>\r\n                          </div>\r\n                          <div class=\"mb-0 d-flex\">\r\n                              <p class=\"text-right vertical-align-top pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\"\r\n                                  >Leveringsadres:</p\r\n                              >\r\n                              <p class=\"mb-0\" class=\"d-inline-block\"\r\n                                  >[delivery_address_street] [delivery_address_houseNr] [delivery_address_zipcode]<br><span class=\"text-capitalize\">[delivery_address_city]</span></p\r\n                              >\r\n                          </div>\r\n                      </div>\r\n                  </div>\r\n              </div>\r\n          </div>\r\n          <div class=\"row\">\r\n            <div class=\"col-12\">\r\n                <p class=\"mb-5\">\r\n                    <span class=\"float-right\">[date_generate_PDF]</span>\r\n                  </p>\r\n              <p class=\"mb-4\">Beste [customer_first_name],</p>\r\n              <p class=\"mb-4 [final_bill_visible]\">Dit is je eindafrekening over de verbruiksperiode van [final_bill_start_date] tot [final_bill_end_date] voor je leveringsadres [delivery_address_street] [delivery_address_houseNr] te <span class=\"text-capitalize\">[delivery_address_city]</span>. Je ontvangt deze afrekening omdat je contract met [reseller_name] eindigt. In deze eindafrekening berekenen we de kosten tot de einddatum van je contract. Indien je onlangs een nieuw [reseller_name]-contract hebt afgesloten, ontvang je hier apart bericht van. </p>\r\n              <p class=\"mb-4 [yearly_bill_visible]\">Dit is je jaarafrekening over de verbruiksperiode van [final_bill_start_date] tot [final_bill_end_date] voor je leveringsadres [delivery_address_street] [delivery_address_houseNr] te <span class=\"text-capitalize\">[delivery_address_city]</span>. In deze jaarafrekening vind je een overzicht van je energieverbruik in het afgelopen jaar en wat je hiervoor hebt betaald. </p>\r\n            </div>\r\n          </div>\r\n          [FINALBILL_TEMPLATE_UNPAID_AMOUNT_INVOICE_ITEM]\r\n          [FINALBILL_TEMPLATE_PAID_AMOUNT_INVOICE_ITEM]\r\n          <div>\r\n            <p class=\"mb-1 font-weight-bold [yearly_bill_visible] [new_monthly_amount_visible]\"> \r\n              <span>Je nieuwe termijnbedrag </span>\r\n            </p>\r\n            <p class=\"mb-4 [yearly_bill_visible] [new_monthly_amount_visible]\"> Op basis van je verbruik in de afgelopen 12 maanden, hebben we een nieuw termijnbedrag voor je uitgerekend. We passen het termijnbedrag automatisch voor je aan. Ben je het niet eens met je nieuwe termijnbedrag? Dan kun je dit gemakkelijk aanpassen in onze mobiele app. </p>\r\n          </div>\r\n          <div class=\"row monthly-amount-block [yearly_bill_visible] [new_monthly_amount_visible] mt-4\" style=\"background-image: url(\'data:image/png;base64,\');background-size: 100%; background-repeat: no-repeat; background-position: center center;\">\r\n            <div class=\"col-6\">\r\n              <span> Oude termijnbedrag </span>\r\n              <span class=\"float-right\"> € [current_monthly_amount] </span>\r\n            </div>\r\n            <div class=\"col-6 pl-5 font-weight-bold\">\r\n              <span> Nieuwe termijnbedrag </span>\r\n              <span class=\"float-right\"> € [new_monthly_amount] </span>\r\n            </div>\r\n          </div>\r\n          <div class=\"mt-4 avoid-break-page\">\r\n            <p class=\"font-weight-bold mb-1\">Vragen?</p>\r\n            <p class=\"mb-3\">Je kunt altijd contact met ons opnemen via <a href=\"mailto:[reseller_email]\">[reseller_email]</a> of bellen naar [reseller_phone].</p>\r\n            <p class=\"mb-3\">Met vriendelijke groet, </p>\r\n            <p class=\"mb-0\">[reseller_name]</p>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div>\r\n          <p>Meer informatie over je verbruik of de precieze berekening van je <span class=\"[final_bill_visible]\">eindafrekening</span> <span class=\"[yearly_bill_visible]\">jaarafrekening</span> vind je op de volgende pagina’s.</p>\r\n          <div class=\"mb-1 font-weight-bold\">Samenvatting van je <span class=\"[final_bill_visible]\">eindafrekening</span>\r\n            <span class=\"[yearly_bill_visible]\">jaarafrekening</span>\r\n          </div>\r\n          <div class=\"[hide_text_summary]\">[text_summary]</div>\r\n          <div class=\"mt-5\">\r\n            <table class=\"table table-first\">\r\n              <tbody>\r\n                <tr>\r\n                  <td class=\"pl-2\"> 1. Leveringskosten van [product_type] </td>\r\n                  <td class=\"pl-2 text-right\">[total_delivery_amount]</td>\r\n                </tr>\r\n                <tr class=\"[show_price_cap_billing]\">\r\n                    <td class=\"pl-2\"> 2. Tegemoetkoming uit het prijsplafond</td>\r\n                    <td class=\"pl-2 text-right\">[total_price_cap]</td>\r\n                  </tr>\r\n                <tr>\r\n                    <td class=\"pl-2 [hide_price_cap_billing]\"> 2. Overheidsheffingen op [product_type], dit dragen we af aan de overheid </td>\r\n                    <td class=\"pl-2 [show_price_cap_billing]\"> 3. Overheidsheffingen op [product_type], dit dragen we af aan de overheid </td>\r\n                  <td class=\"pl-2 text-right\">[total_tax_amount]</td>\r\n                </tr>\r\n                <tr>\r\n                    <td class=\"pl-2 [hide_price_cap_billing]\"> 3. Netbeheerkosten op [product_type], dit dragen we af aan je netbeheerder </td>\r\n                    <td class=\"pl-2 [show_price_cap_billing]\"> 4. Netbeheerkosten op [product_type], dit dragen we af aan je netbeheerder </td>\r\n                  <td class=\"pl-2 text-right\">[total_grid_operator_amount]</td>\r\n                </tr>\r\n                <tr>\r\n                  <td class=\"pl-2 font-weight-bold\"></td>\r\n                  <td class=\"pl-2 text-right  font-weight-bold\">[total_real_amount_incl_cancel_fee]</td>\r\n                </tr>\r\n              </tbody>\r\n            </table>\r\n          </div>\r\n          <div class=\"mt-5\">\r\n            <table class=\"table table-first\">\r\n              <tbody>\r\n                <tr>\r\n                    <td class=\"pl-2 [hide_price_cap_billing]\"> 4. In rekening gebrachte termijnbedragen </td>\r\n                    <td class=\"pl-2 [show_price_cap_billing]\"> 5. In rekening gebrachte termijnbedragen </td>\r\n                    <td class=\"pl-2 text-right\">[total_generated_amount_negative]</td>\r\n                </tr>\r\n                <tr class=\"[total_unpaid_amount_class]\">\r\n                  <td class=\"pl-4 font-italic\"> Openstaande termijnbedragen </td>\r\n                  <td class=\"pl-2 text-right\">[total_unpaid_amount]</td>\r\n                </tr>\r\n                <tr class=\"[total_collection_cost_amount_class]\">\r\n                  <td class=\"pl-4 font-italic\"> Openstaande incassokosten </td>\r\n                  <td class=\"pl-2 text-right\">[total_collection_cost_amount]</td>\r\n                </tr>\r\n                <tr>\r\n                  <td class=\"pl-2 font-weight-bold\"></td>\r\n                  <td class=\"pl-2 text-right  font-weight-bold\">[total_real_generated_amount_negative]</td>\r\n                </tr>\r\n              </tbody>\r\n            </table>\r\n            <table>\r\n              <tbody>\r\n                <tr>\r\n                  <td class=\"w-100\"></td>\r\n                  <td class=\"pl-2 text-right font-weight-bold text-nowrap t-nowrap\">\r\n                    <div class=\"border-top-bold position-relative\">\r\n                      <span class=\"pr-5\">[is_receive]</span>\r\n                      <span>€ [difference_amount]</span>\r\n                    </div>\r\n                  </td>\r\n                </tr>\r\n              </tbody>\r\n            </table>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div class=\"[usage_only_gas_elk_visible]\">\r\n            <p class=\"mb-1 font-weight-bold\"> Berekening van je verbruik </p>\r\n            <p class=\"mb-5\"> Op basis van je meterstanden bepalen wij hoeveel energie je hebt verbruikt. De meterstanden lezen wij uit via je slimme meter, vragen wij bij je op via de Kikker app of berekenen we zelf. Onderstaand vind je een overzicht van je verbruik per periode. Omdat tussen periodes soms verschillende tarieven gelden, kan het zijn dat je verschillende periodes ziet. </p>\r\n          </div>\r\n          <div class=\"[usage_only_gas_elk_visible]\"> [usage_item_by_ean] </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div class=\"[usage_only_gas_elk_visible]\" style=\"page-break-before: always\"></div>\r\n    <div class=\"page [usage_both_gas_elk_visible]\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div>\r\n            <p class=\"mb-1 font-weight-bold\"> Berekening van je verbruik </p>\r\n            <p class=\"mb-5\"> Op basis van je meterstanden bepalen wij hoeveel energie je hebt verbruikt. De meterstanden lezen wij uit via je slimme meter, vragen wij bij je op via de Kikker app of berekenen we zelf. Onderstaand vind je een overzicht van je verbruik per periode. Omdat tussen periodes soms verschillende tarieven gelden, kan het zijn dat je verschillende periodes ziet. </p>\r\n          </div>\r\n          <div> [usage_item_by_ean] </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div class=\"[usage_both_gas_elk_visible]\" style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div>\r\n            <p class=\"mb-4\">Op de volgende pagina’s vind je een nadere specificatie van de kosten die weergegeven zijn op pagina 2.</p>\r\n            [return_tariff_section]\r\n            <p class=\"mb-1 font-weight-bold\">1. Leveringskosten voor [product_type]</p>\r\n            <p class=\"mb-5\"> Onderstaand vind je een specificatie van je leveringskosten voor [product_type]. Door je verbruik te vermenigvuldigen met je tarief bepalen we je kosten per contract. </p>\r\n          </div>\r\n          <div class=\"table_fixed_delivery\"> [fixed_delivery_item_dynamic_page] </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    [price_cap_section_template]\r\n\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div class=\"row\">\r\n            <div class=\"col-12\">\r\n                <p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">2. Overheidsheffingen op [product_type]</p>\r\n                <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">3. Overheidsheffingen op [product_type]</p>\r\n              <p style=\"display: [show_new_ode_tax_description]\">Naast de kosten voor het verbruik van [product_type], moet je ook belastingen betalen aan de overheid. Ook deze zijn afhankelijk van je verbruik. Onderstaande kosten dragen wij direct af aan de overheid. Omdat de heffingen jaarlijks (per 1 januari) veranderen zie je onderstaand mogelijk twee berekeningen: een voor de periode vóór en een voor de periode ná 1 januari.</p>\r\n            </div>\r\n          </div>\r\n          <div class=\"mt-3\"> [tax_item_dynamic_page] </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div class=\"row\">\r\n            <div class=\"col-12\">\r\n                <p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">3. Netbeheerkosten voor [product_type]</p>\r\n                <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">4. Netbeheerkosten voor [product_type]</p>\r\n              <p class=\"mb-3\">Om van [product_type] gebruik te kunnen maken, dien je aangesloten te zijn op het openbare [product_type]netwerk van je netbeheerder. Hiervoor betaal je een vaste vergoeding die afhankelijk is van je aansluiting. Wij dragen deze vervolgens weer af aan je netbeheerder. Ook hier geldt dat de tarieven jaarlijks per 1 januari wijzigen. Om deze reden zie je onderstaand mogelijk weer twee berekeningen: voor de periode vóór en de periode ná 1 januari. </p>\r\n              <p> Je netbeheerder: <strong>[grid_operator_name]</strong>\r\n              </p>\r\n            </div>\r\n          </div>\r\n          <div class=\"mt-3 custom-table table_grid_operator\"> [grid_operator_item_dynamic_page] </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n          <div class=\"content\">\r\n            <div class=\"row\">\r\n              <div class=\"col-12\">\r\n              	<p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">4. Totaal in rekening gebrachte termijnbedragen</p>\r\n                <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">5. Totaal in rekening gebrachte termijnbedragen</p>\r\n                <p class=\"mb-1\">Hier zie je een overzicht van de door ons in rekening gebrachte termijnbedragen in de afgelopen periode (incl. btw). Een negatief termijnbedrag wordt als niet in rekening gebracht beschouwd en daarom als 0 weergegeven.</p>\r\n              </div>\r\n            </div>\r\n            <div class=\"mt-5\">\r\n              <table class=\"table table-custom\">\r\n                <thead>\r\n                  <th class=\"pl-2 charge-item-month-column\">MAAND</th>\r\n                  <th class=\"pl-2 charge-item-invoice-number\">FACTUURNUMMER</th>\r\n                  <th class=\"pl-2 text-right\" colspan=\"2\">BEDRAG</th>\r\n                </thead>\r\n                <tbody> [charged_item_by_month] </tbody>\r\n              </table>\r\n              <table>\r\n                <tbody>\r\n                  <tr>\r\n                    <td style=\"height: 15px;\"></td>\r\n                  </tr>\r\n                  <tr>\r\n                    <td class=\"w-100\"></td>\r\n                    <td class=\"pl-2 text-right font-weight-bold text-nowrap t-nowrap\">\r\n                      <div class=\"border-top-bold position-relative\">\r\n                        <span class=\"pr-5\">Totaal in rekening gebrachte termijnbedragen</span>\r\n                        <span>[total_generated_amount]</span>\r\n                      </div>\r\n                    </td>\r\n                  </tr>\r\n                </tbody>\r\n              </table>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n      <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div>\r\n            <p class=\"font-weight-bold\">Jouw EAN-codes</p> [elk_gas_eans]\r\n          </div>\r\n          <div class=\"mt-5\">\r\n            <p class=\"font-weight-bold\">Btw-aangifte</p>\r\n            <p class=\"mb-0\"> [reseller_name] handelt onder de leveranciersvergunning van Kikker Energie. In het geval je een btw-aangifte moet doen, dien je daarom de gegevens van Kikker Energie te gebruiken. De benodigde informatie van Kikker Energie en je netbeheerder vind je onderstaand:</p>\r\n          </div>\r\n          <div class=\"row mt-4\">\r\n            <div class=\"col-5\">\r\n              <p class=\"mb-0\"> Kikker Energie B.V. </br> Tolnasingel 12 </br> 2411PV Bodegraven </p>\r\n              <p class=\"mb-0\">KvK: 71246681</p>\r\n              <p class=\"mb-0\">Btw nr.: NL858635732B01</p>\r\n            </div>\r\n            <div class=\"col-5\">\r\n              <p class=\"mb-0\"> [grid_operator_name] </br> [grid_operator_house_nr] </br> [grid_operator_postcode] </p>\r\n              <p class=\"mb-0\">KvK: [grid_operator_kvk]</p>\r\n              <p class=\"mb-0\">Btw nr.: [grid_operator_btw]</p>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </body>\r\n</html>', NULL, NULL, 'nl', 'ke-pdf', NULL, '2023-11-27 09:07:13.152323', NULL);
INSERT IGNORE INTO `templates_reseller` (`Id`, `reseller_id`, `template_name`, `html_content`, `header_id`, `footer_id`, `language_code`, `CreatedBy`, `ModifiedBy`, `CreatedAt`, `ModifiedAt`) VALUES (190, 197, 'FINALBILL_TEMPLATE_MAIN_V', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n  <head>\r\n    <title>Billing | Kikker</title>\r\n    <meta charset=\"utf-8\">\r\n    <link rel=\"icon\" href=\"asset/kikker-icon.ico\" />\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\r\n    <link rel=\"stylesheet\" href=\"https://storage.googleapis.com/kikkerprodbucket/static-files/pdf-css/site.css\">\r\n    <link rel=\"stylesheet\" href=\"https://storage.googleapis.com/kikkerprodbucket/static-files/pdf-css/final_bill.css\">\r\n  </head>\r\n  <body>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div class=\"row header mr-0 ml-0\">\r\n            <div style=\"width: 33%;\">\r\n            </div>\r\n            <div class=\"[hide-header-invoice-info] header-invoice-info\">\r\n                <div class=\"d-flex justify-content-end\">\r\n                    <div class=\"space-span d-inline-block\" style=\"padding-top: 0\">\r\n                        <div class=\"mb-0 d-flex\">\r\n                            <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\">Klantnummer:</p>\r\n                            <p class=\"mb-0\">[client_number]</p>\r\n                        </div>\r\n                        <div class=\"mb-0 d-flex\">\r\n                            <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\"\r\n                                >Contractnummer:\r\n                            </p>\r\n                            <p class=\"mb-0\">[contract_number]</p>\r\n                        </div>\r\n                        <div class=\"mb-0 d-flex [hidden_contract_reference]\" style=\"flex-flow: row;\">\r\n                            <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\">Contractreferentie: </p>\r\n                            <p class=\"mb-0\">[contract_reference]</p>\r\n                        </div>\r\n                        <div class=\"mb-0 d-flex\">\r\n                            <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\"\r\n                                >Factuurnummer:\r\n                            </p>\r\n                            <p class=\"mb-0\">[invoice_number]</p>\r\n                        </div>\r\n                        <div class=\"mb-0 d-flex [company_name_visible]\" style=\"flex-flow: row;\">\r\n                            <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\">Bedrijfsnaam: </p>\r\n                            <p class=\"mb-0\">[company_name]</p>\r\n                        </div>\r\n                        <div class=\"mb-0 d-flex\" style=\"flex-flow: row;\">\r\n                            <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\">Energie intermediair: </p>\r\n                            <p class=\"mb-0\">[header_reseller_name]</p>\r\n                        </div>\r\n                        <div class=\"mb-0 d-flex\">\r\n                            <p class=\"text-right vertical-align-top pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\"\r\n                                >Leveringsadres:</p\r\n                            >\r\n                            <p class=\"mb-0\" class=\"d-inline-block\"\r\n                                >[delivery_address_street] [delivery_address_houseNr] [delivery_address_zipcode]<br><span class=\"text-capitalize\">[delivery_address_city]</span></p\r\n                            >\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n          <div class=\"row\">\r\n            <div class=\"col-12\">\r\n                <p class=\"mb-4\">\r\n                <span class=\"float-right\">[date_generate_PDF]</span>\r\n              </p>\r\n              <p class=\"mb-4\">Beste [customer_first_name],</p>\r\n              <p class=\"mb-4 [final_bill_visible]\">Dit is je eindafrekening over de verbruiksperiode van [final_bill_start_date] tot [final_bill_end_date] voor je leveringsadres [delivery_address_street] [delivery_address_houseNr] te <span class=\"text-capitalize\">[delivery_address_city]</span>. Je ontvangt deze afrekening omdat je contract met [reseller_name] eindigt. In deze eindafrekening berekenen we de kosten tot de einddatum van je contract. Indien je onlangs een nieuw [reseller_name]-contract hebt afgesloten, ontvang je hier apart bericht van. </p>\r\n              <p class=\"mb-4 [yearly_bill_visible]\">Dit is je jaarafrekening over de verbruiksperiode van [final_bill_start_date] tot [final_bill_end_date] voor je leveringsadres [delivery_address_street] [delivery_address_houseNr] te <span class=\"text-capitalize\">[delivery_address_city]</span>. In deze jaarafrekening vind je een overzicht van je energieverbruik in het afgelopen jaar en wat je hiervoor hebt betaald. </p>\r\n            </div>\r\n          </div>\r\n          [FINALBILL_TEMPLATE_UNPAID_AMOUNT_INVOICE_ITEM]\r\n          [FINALBILL_TEMPLATE_PAID_AMOUNT_INVOICE_ITEM]\r\n          <div style=\"page-break-before: always\" class=\"[yearly_bill_visible] [new_monthly_amount_visible]\"></div>\r\n          <div class=\"mt-3\">\r\n            <p class=\"mb-1 font-weight-bold [yearly_bill_visible] [new_monthly_amount_visible]\"> Je nieuwe termijnbedrag </span>\r\n            </p>\r\n            <p class=\"mb-4 [yearly_bill_visible] [new_monthly_amount_visible]\"> Op basis van je verbruik in de afgelopen 12 maanden, hebben we een nieuw termijnbedrag voor je uitgerekend. We passen het termijnbedrag automatisch voor je aan. Ben je het niet eens met je nieuwe termijnbedrag? Dan kun je dit gemakkelijk aanpassen in onze mobiele app. </p>\r\n          </div>\r\n          <div class=\"row monthly-amount-block [yearly_bill_visible] [new_monthly_amount_visible] mt-4\" style=\"background-image: url(\'data:image/png;base64,\');background-size: 100%; background-repeat: no-repeat; background-position: center center;\">\r\n            <div class=\"col-6\">\r\n              <span> Oude termijnbedrag </span>\r\n              <span class=\"float-right\"> € [current_monthly_amount] </span>\r\n            </div>\r\n            <div class=\"col-6 pl-5 font-weight-bold\">\r\n              <span> Nieuwe termijnbedrag </span>\r\n              <span class=\"float-right\"> € [new_monthly_amount] </span>\r\n            </div>\r\n          </div>\r\n          <div class=\"mt-3 avoid-break-page\">\r\n            <p class=\"font-weight-bold mb-1\">Vragen?</p>\r\n            <p class=\"mb-3\" style=\"text-align: left;\">Neem contact op met jouw wederverkoper [reseller_name]. Dit kun je doen via e-mail op [reseller_email] of telefonisch op [reseller_phone].</p>\r\n            <p class=\"mb-3\">Met vriendelijke groet, </p>\r\n            <p class=\"mb-0\">[reseller_name]</p>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div>\r\n          <p>Meer informatie over je verbruik of de precieze berekening van je <span class=\"[final_bill_visible]\">eindafrekening</span> <span class=\"[yearly_bill_visible]\">jaarafrekening</span> vind je op de volgende pagina’s.</p>\r\n          <div class=\"mb-1 font-weight-bold\">Samenvatting van je <span class=\"[final_bill_visible]\">eindafrekening</span>\r\n            <span class=\"[yearly_bill_visible]\">jaarafrekening</span>\r\n          </div>\r\n          <div class=\"[hide_text_summary]\">[text_summary]</div>\r\n          <div class=\"mt-5\">\r\n            <table class=\"table table-first\">\r\n              <tbody>\r\n                <tr>\r\n                  <td class=\"pl-2\"> 1. Leveringskosten van [product_type] </td>\r\n                  <td class=\"pl-2 text-right\">[total_delivery_amount]</td>\r\n                </tr>\r\n                <tr class=\"[show_price_cap_billing]\">\r\n                  <td class=\"pl-2\"> 2. Tegemoetkoming uit het prijsplafond</td>\r\n                  <td class=\"pl-2 text-right\">[total_price_cap]</td>\r\n                </tr>\r\n                <tr>\r\n                  <td class=\"pl-2 [hide_price_cap_billing]\"> 2. Overheidsheffingen op [product_type], dit dragen we af aan de overheid </td>\r\n                  <td class=\"pl-2 [show_price_cap_billing]\"> 3. Overheidsheffingen op [product_type], dit dragen we af aan de overheid </td>\r\n                  <td class=\"pl-2 text-right\">[total_tax_amount]</td>\r\n                </tr>\r\n                <tr>\r\n                  <td class=\"pl-2 [hide_price_cap_billing]\"> 3. Netbeheerkosten op [product_type], dit dragen we af aan je netbeheerder </td>\r\n                  <td class=\"pl-2 [show_price_cap_billing]\"> 4. Netbeheerkosten op [product_type], dit dragen we af aan je netbeheerder </td>\r\n                  <td class=\"pl-2 text-right\">[total_grid_operator_amount]</td>\r\n                </tr>\r\n                <tr>\r\n                  <td class=\"pl-2 font-weight-bold\"></td>\r\n                  <td class=\"pl-2 text-right  font-weight-bold\">[total_real_amount_incl_cancel_fee]</td>\r\n                </tr>\r\n              </tbody>\r\n            </table>\r\n          </div>\r\n          <div class=\"mt-5\">\r\n            <table class=\"table table-first\">\r\n              <tbody>\r\n                <tr>\r\n                  <td class=\"pl-2 [hide_price_cap_billing]\"> 4. In rekening gebrachte termijnbedragen </td>\r\n                  <td class=\"pl-2 [show_price_cap_billing]\"> 5. In rekening gebrachte termijnbedragen </td>\r\n                  <td class=\"pl-2 text-right\">[total_generated_amount_negative]</td>\r\n                </tr>\r\n                <tr class=\"[total_unpaid_amount_class]\">\r\n                  <td class=\"pl-4 font-italic\"> Openstaande termijnbedragen </td>\r\n                  <td class=\"pl-2 text-right\">[total_unpaid_amount]</td>\r\n                </tr>\r\n                <tr class=\"[total_collection_cost_amount_class]\">\r\n                  <td class=\"pl-4 font-italic\"> Openstaande incassokosten </td>\r\n                  <td class=\"pl-2 text-right\">[total_collection_cost_amount]</td>\r\n                </tr>\r\n                <tr>\r\n                  <td class=\"pl-2 font-weight-bold\"></td>\r\n                  <td class=\"pl-2 text-right  font-weight-bold\">[total_real_generated_amount_negative]</td>\r\n                </tr>\r\n              </tbody>\r\n            </table>\r\n            <table>\r\n              <tbody>\r\n                <tr>\r\n                  <td class=\"w-100\"></td>\r\n                  <td class=\"pl-2 text-right font-weight-bold text-nowrap t-nowrap\">\r\n                    <div class=\"border-top-bold position-relative\">\r\n                      <span class=\"pr-5\">[is_receive]</span>\r\n                      <span>€ [difference_amount]</span>\r\n                    </div>\r\n                  </td>\r\n                </tr>\r\n              </tbody>\r\n            </table>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div class=\"[usage_only_gas_elk_visible]\">\r\n            <p class=\"mb-1 font-weight-bold\"> Berekening van je verbruik </p>\r\n            <p class=\"mb-5\"> Op basis van je meterstanden bepalen wij hoeveel energie je hebt verbruikt. De meterstanden lezen wij uit via je slimme meter, vragen wij bij je op of berekenen we zelf. Onderstaand vind je een overzicht van je verbruik per periode. Omdat tussen periodes soms verschillende tarieven gelden, kan het zijn dat je verschillende periodes ziet. </p>\r\n          </div>\r\n          <div class=\"[usage_only_gas_elk_visible]\"> [usage_item_by_ean] </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div class=\"[usage_only_gas_elk_visible]\" style=\"page-break-before: always\"></div>\r\n    <div class=\"page [usage_both_gas_elk_visible]\">\r\n        <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n            <div>\r\n                <p class=\"mb-1 font-weight-bold\">\r\n                    Berekening van je verbruik\r\n                </p>\r\n                <p class=\"mb-5\">\r\n                    Op basis van je meterstanden bepalen wij hoeveel energie je hebt verbruikt. De meterstanden lezen wij uit via je\r\n                    slimme meter, vragen wij bij je op of berekenen we zelf. Onderstaand vind je een overzicht van je\r\n                    verbruik per periode. Omdat tussen periodes soms verschillende tarieven gelden, kan het zijn dat je verschillende\r\n                    periodes ziet.\r\n                </p>\r\n            </div>\r\n\r\n            <div class=\"table-usage\">\r\n                [usage_item_by_ean]\r\n            </div>\r\n        </div>\r\n        </div>\r\n    </div>\r\n    <div class=\"[usage_both_gas_elk_visible]\" style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div>\r\n            <p class=\"mb-4\">Op de volgende pagina’s vind je een nadere specificatie van de kosten die weergegeven zijn op pagina 2.</p>\r\n            [return_tariff_section]\r\n            <p class=\"mb-1 font-weight-bold\">1. Leveringskosten voor [product_type]</p>\r\n            <p class=\"mb-5\"> Onderstaand vind je een specificatie van je leveringskosten voor [product_type]. Door je verbruik te vermenigvuldigen met je tarief bepalen we je kosten per contract. </p>\r\n          </div>\r\n          <div class=\"table_fixed_delivery\"> [fixed_delivery_item_dynamic_page] </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    [price_cap_section_template]\r\n\r\n\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div class=\"row\">\r\n            <div class=\"col-12\">\r\n              <p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">2. Overheidsheffingen op [product_type]</p>\r\n              <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">3. Overheidsheffingen op [product_type]</p>\r\n              <p>Naast de kosten voor het verbruik van [product_type], moet je ook belastingen betalen aan de overheid. Ook deze zijn afhankelijk van je verbruik. Onderstaande kosten dragen wij direct af aan de overheid. Omdat de heffingen jaarlijks (per 1 januari) veranderen zie je onderstaand mogelijk twee berekeningen: een voor de periode vóór en een voor de periode ná 1 januari.</p>\r\n            </div>\r\n          </div>\r\n          <div class=\"mt-3\"> [tax_item_dynamic_page] </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div class=\"row\">\r\n            <div class=\"col-12\">\r\n              <p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">3. Netbeheerkosten voor [product_type]</p>\r\n              <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">4. Netbeheerkosten voor [product_type]</p>\r\n              <p class=\"mb-3\">Om van [product_type] gebruik te kunnen maken, dien je aangesloten te zijn op het openbare [product_type]netwerk van je netbeheerder. Hiervoor betaal je een vaste vergoeding die afhankelijk is van je aansluiting. Wij dragen deze vervolgens weer af aan je netbeheerder. Ook hier geldt dat de tarieven jaarlijks per 1 januari wijzigen. Om deze reden zie je onderstaand mogelijk weer twee berekeningen: voor de periode vóór en de periode ná 1 januari. </p>\r\n              <p> Je netbeheerder: <strong>[grid_operator_name]</strong>\r\n              </p>\r\n            </div>\r\n          </div>\r\n          <div class=\"mt-3 custom-table table_grid_operator\"> [grid_operator_item_dynamic_page] </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n          <div class=\"content\">\r\n            <div class=\"row\">\r\n              <div class=\"col-12\">\r\n              	<p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">4. Totaal in rekening gebrachte termijnbedragen</p>\r\n                <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">5. Totaal in rekening gebrachte termijnbedragen</p>\r\n                <p class=\"mb-1\">Hier zie je een overzicht van de door ons in rekening gebrachte termijnbedragen in de afgelopen periode (incl. btw). Een negatief termijnbedrag wordt als niet in rekening gebracht beschouwd en daarom als 0 weergegeven.</p>\r\n              </div>\r\n            </div>\r\n            <div class=\"mt-5\">\r\n              <table class=\"table table-custom\">\r\n                <thead>\r\n                  <th class=\"pl-2 charge-item-month-column\">MAAND</th>\r\n                  <th class=\"pl-2 charge-item-invoice-number\">FACTUURNUMMER</th>\r\n                  <th class=\"pl-2 text-right\" colspan=\"2\">BEDRAG</th>\r\n                </thead>\r\n                <tbody> [charged_item_by_month] </tbody>\r\n              </table>\r\n              <table>\r\n                <tbody>\r\n                  <tr>\r\n                    <td style=\"height: 15px;\"></td>\r\n                  </tr>\r\n                  <tr>\r\n                    <td class=\"w-100\"></td>\r\n                    <td class=\"pl-2 text-right font-weight-bold text-nowrap t-nowrap\">\r\n                      <div class=\"border-top-bold position-relative\">\r\n                        <span class=\"pr-5\">Totaal in rekening gebrachte termijnbedragen</span>\r\n                        <span>[total_generated_amount]</span>\r\n                      </div>\r\n                    </td>\r\n                  </tr>\r\n                </tbody>\r\n              </table>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n      <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div>\r\n            <p class=\"font-weight-bold\">Jouw EAN-codes</p> [elk_gas_eans]\r\n          </div>\r\n          <div class=\"mt-5\">\r\n            <p class=\"font-weight-bold\">Btw-aangifte</p>\r\n            <p class=\"mb-0\"> [reseller_name] handelt onder de leveranciersvergunning van Kikker Energie. In het geval je een btw-aangifte moet doen, dien je daarom de gegevens van Kikker Energie te gebruiken. De benodigde informatie van Kikker Energie en je netbeheerder vind je onderstaand: </p>\r\n          </div>\r\n          <div class=\"row mt-4\">\r\n            <div class=\"col-5\">\r\n              <p class=\"mb-0\"> Kikker Energie B.V. </br> Tolnasingel 12 </br> 2411PV Bodegraven </p>\r\n              <p class=\"mb-0\">KvK: 71246681</p>\r\n              <p class=\"mb-0\">Btw nr.: NL858635732B01</p>\r\n            </div>\r\n            <div class=\"col-5\">\r\n              <p class=\"mb-0\"> [grid_operator_name] </br> [grid_operator_house_nr] </br> [grid_operator_postcode] </p>\r\n              <p class=\"mb-0\">KvK: [grid_operator_kvk]</p>\r\n              <p class=\"mb-0\">Btw nr.: [grid_operator_btw]</p>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </body>\r\n</html>', NULL, NULL, 'nl', 'ke-pdf', NULL, '2023-11-27 09:07:13.152323', NULL);
INSERT IGNORE INTO `templates_reseller` (`Id`, `reseller_id`, `template_name`, `html_content`, `header_id`, `footer_id`, `language_code`, `CreatedBy`, `ModifiedBy`, `CreatedAt`, `ModifiedAt`) VALUES (197, 197, 'FINALBILL_TEMPLATE_PAID_AMOUNT_INVOICE_ITEM', '<div class=\"mb-3\">\r\n    <p class=\"mb-3\"> Alle onderdelen met betrekking tot energie, behalve een eventuele opzegboete, zijn belast met btw. Meer informatie over je verbruik of de precieze berekening van je <span class=\"[final_bill_visible]\">eindafrekening</span>\r\n        <span class=\"[yearly_bill_visible]\">jaarafrekening</span> vind je op de volgende pagina’s.\r\n    </p>\r\n    <table class=\"table\">\r\n        <tbody>\r\n        <tr>\r\n            <td class=\"pl-2\"> Totale kosten in de verbruiksperiode </td>\r\n            <td class=\"pl-2 text-right\">[total_real_amount]</td>\r\n        </tr>\r\n        <tr class=\"[show_price_cap_billing]\">\r\n            <td class=\"pl-2 [show_price_cap_billing]\"> Tegemoetkoming uit het prijsplafond </td>\r\n            <td class=\"pl-2 text-right [show_price_cap_billing]\">[total_price_cap]</td>\r\n        </tr>\r\n        <tr class=\"[cancelation_fee_visible]\">\r\n            <td class=\"pl-2\"> Opzegboete </td>\r\n            <td class=\"pl-2 text-right\">[cancelation_fee]</td>\r\n        </tr>\r\n        <tr>\r\n            <td class=\"pl-2\"> In rekening gebrachte termijnbedragen </td>\r\n            <td class=\"pl-2 text-right\">[total_generated_amount_negative]</td>\r\n        </tr>\r\n        <tr class=\"[total_unpaid_amount_class]\">\r\n            <td class=\"pl-2\"> Totaal openstaande termijnbedragen </td>\r\n            <td class=\"pl-2 text-right\">[total_unpaid_amount]</td>\r\n        </tr>\r\n        <tr class=\"[total_collection_cost_amount_class]\">\r\n            <td class=\"pl-2\"> Totaal openstaande incassokosten </td>\r\n            <td class=\"pl-2 text-right\">[total_collection_cost_amount]</td>\r\n        </tr>\r\n        <tr>\r\n            <table>\r\n            <tbody>\r\n                <tr>\r\n                <td style=\"height: 15px;\"></td>\r\n                </tr>\r\n                <tr>\r\n                <td class=\"w-100\"></td>\r\n                <td class=\"pl-2 text-right font-weight-bold text-nowrap t-nowrap mt-3\">\r\n                    <div class=\"border-top-bold position-relative\">\r\n                    <span class=\"pr-5\">[is_receive]</span>\r\n                    <span>€ [difference_amount]</span>\r\n                    </div>\r\n                </td>\r\n                </tr>\r\n            </tbody>\r\n            </table>\r\n        </tr>\r\n        </tbody>\r\n    </table>\r\n    <p class=\"mb-1 mt-3 font-weight-bold\"> De termijnbedragen op je <span class=\"[final_bill_visible]\">eindafrekening</span>\r\n        <span class=\"[yearly_bill_visible]\">jaarafrekening</span>\r\n    </p>\r\n    <p class=\"mb-4\"> Op deze <span class=\"[final_bill_visible]\">eindafrekening</span>\r\n        <span class=\"[yearly_bill_visible]\">jaarafrekening</span> verrekenen we alle termijnbedragen die we tot nu toe hebben gefactureerd. Indien je één of meerdere termijnfacturen nog niet hebt betaald, moet je dit alsnog doen.\r\n    </p>\r\n</div>', NULL, NULL, 'nl', 'ke-pdf', NULL, '2023-11-27 09:07:13.152323', NULL);
INSERT IGNORE INTO `templates_reseller` (`Id`, `reseller_id`, `template_name`, `html_content`, `header_id`, `footer_id`, `language_code`, `CreatedBy`, `ModifiedBy`, `CreatedAt`, `ModifiedAt`) VALUES (204, 197, 'FINALBILL_TEMPLATE_TAX_ITEM_ENERGY', '<tr>\r\n    <td class=\"pl-2\">\r\n        Energiebelasting [tax_item_by_ean_energy_name]\r\n    </td>\r\n    <td class=\"pl-2\">[tax_item_by_ean_energy_usage] [tax_item_by_ean_energy_unit]</td>\r\n    <td class=\"pl-2\">€ [tax_item_by_ean_energy_tariff]</td>\r\n    <td class=\"pl-2 text-right\">€ [tax_item_by_ean_energy_amount]</td>\r\n</tr>', NULL, NULL, 'nl', 'ke-pdf', NULL, '2023-11-27 09:07:13.152323', NULL);
INSERT IGNORE INTO `templates_reseller` (`Id`, `reseller_id`, `template_name`, `html_content`, `header_id`, `footer_id`, `language_code`, `CreatedBy`, `ModifiedBy`, `CreatedAt`, `ModifiedAt`) VALUES (211, 197, 'FINALBILL_TEMPLATE_TAX_ITEM_STORAGE', '<tr>\r\n    <td class=\"pl-2\">\r\n        Opslag duurzame energie [tax_item_by_ean_storage_name]\r\n    </td>\r\n    <td class=\"pl-2\">[tax_item_by_ean_storage_usage] [tax_item_by_ean_storage_unit]</td>\r\n    <td class=\"pl-2\">€ [tax_item_by_ean_storage_tariff]</td>\r\n    <td class=\"pl-2 text-right\">€ [tax_item_by_ean_storage_amount]</td>\r\n</tr>', NULL, NULL, 'nl', 'ke-pdf', NULL, '2023-11-27 09:07:13.152323', NULL);
INSERT IGNORE INTO `templates_reseller` (`Id`, `reseller_id`, `template_name`, `html_content`, `header_id`, `footer_id`, `language_code`, `CreatedBy`, `ModifiedBy`, `CreatedAt`, `ModifiedAt`) VALUES (218, 197, 'FINALBILL_TEMPLATE_TAXES', '[tax_item_by_ean_energy]\r\n[tax_item_by_ean_storage]               \r\n<tr class=\"[tax_item_by_ean_reduction_visible] green-background\"> \r\n    <td class=\"pl-2\">\r\n        Vermindering energiebelasting\r\n    </td>\r\n    <td class=\"pl-2\">[tax_item_by_ean_reduction_usage] jaar</td>\r\n    <td class=\"pl-2\">- € [tax_item_by_ean_reduction_tariff]</td>\r\n    <td class=\"pl-2 text-right\">- € [tax_item_by_ean_reduction_amount]</td>\r\n</tr>\r\n<tr style=\"background-color: transparent !important;\" class=\"background-none [tax_item_by_ean_total_visible] avoid-break-page\">\r\n    <td style=\"background-color: transparent !important;\" class=\"pl-2\"></td>\r\n    <td style=\"background-color: transparent !important;\" class=\"pl-2\"></td>\r\n    <td style=\"background-color: transparent !important;\" class=\"pl-2\"></td>\r\n    <td style=\"background-color: transparent !important;\" class=\"pl-2 font-weight-bold text-right\">[tax_item_total]</td>\r\n</tr>\r\n\r\n\r\n', NULL, NULL, 'nl', 'ke-pdf', NULL, '2023-11-27 09:07:13.152323', NULL);
INSERT IGNORE INTO `templates_reseller` (`Id`, `reseller_id`, `template_name`, `html_content`, `header_id`, `footer_id`, `language_code`, `CreatedBy`, `ModifiedBy`, `CreatedAt`, `ModifiedAt`) VALUES (225, 197, 'FINALBILL_TEMPLATE_TAXES_DYNAMIC_PAGE', '<table class=\"table table-custom mb-0 table_tax\">\r\n    <thead class=\"[tax_item_header_visible] header-line\">\r\n        <th class=\"pl-2\">ENERGIEBELASTING OP LEVERING VAN [product_type]</th>\r\n        <th class=\"pl-2 text-center\"></th>\r\n        <th class=\"pl-2 text-right\"><span class=\"float-left\">TARIEF</th>\r\n        <th class=\"pl-2 text-right\">BEDRAG</th>\r\n    </thead>\r\n     <thead class=\"[tax_item_header_visible]\">\r\n        <th class=\"pl-2\">([start_date] / [end_date])<span class=\"[multil_ean_number_visible]\"> EAN\r\n                [multil_ean_number]</span> | [tax_btw]% BTW</th>\r\n        <th class=\"pl-2 text-center\"><span class=\"float-left\">AANTAL</span><span>x</span></th>\r\n        <th class=\"pl-2 text-right\"><span class=\"float-left\">EXCL. BTW</span><span class=\"d-inline-block pr-2\">=</span>\r\n        </th>\r\n        <th class=\"pl-2 text-right\">EXCL. BTW</th>\r\n    </thead>\r\n    <tbody>\r\n        [tax_item]\r\n\r\n        <tr class=\"[tax_item_total_visible] tr-total-vat\">\r\n            <td colspan=\"4\">\r\n                <div class=\"text-right\" style=\"margin-right: -4px;\">\r\n                    <div class=\"text-nowrap\" >\r\n                        Subtotaal\r\n                        <span class=\"d-inline-block\" style=\"width: 140px;\">\r\n                            [tax_sub_total]\r\n                        </span>\r\n                    </div>\r\n                   \r\n                    <div class=\"text-tax-color text-nowrap [hide_tax_vat_1]\" >\r\n                        btw [tax_btw_1]% over [tax_net_month_1]\r\n                        <span class=\"d-inline-block\" style=\"width: 140px;\">\r\n                            [tax_btw_amount_1]\r\n                        </span>\r\n                    </div>\r\n         \r\n                    <div class=\"text-tax-color text-nowrap [hide_tax_vat_2]\" >\r\n                        btw [tax_btw_2]% over [tax_net_month_2]\r\n                        <span class=\"d-inline-block\" style=\"width: 140px;\">\r\n                            [tax_btw_amount_2]\r\n                        </span>\r\n                    </div>\r\n          \r\n                    <div class=\"d-inline-block border-top-bold-td text-nowrap font-weight-bold\">\r\n                        Totaalbedrag voor overheidsheffingen op [total_product_type]\r\n                        <span class=\"d-inline-block\" style=\"width: 140px;\">\r\n                            [tax_item_total]\r\n                        </span>\r\n                    </div>\r\n                </div>\r\n            </td>\r\n        </tr>\r\n    </tbody>\r\n</table>', NULL, NULL, 'nl', 'ke-pdf', NULL, '2023-11-27 09:07:13.152323', NULL);
INSERT IGNORE INTO `templates_reseller` (`Id`, `reseller_id`, `template_name`, `html_content`, `header_id`, `footer_id`, `language_code`, `CreatedBy`, `ModifiedBy`, `CreatedAt`, `ModifiedAt`) VALUES (232, 197, 'FINALBILL_TEMPLATE_UNPAID_AMOUNT_INVOICE_ITEM', '<div>\r\n    <p class=\"mb-3\">\r\n        Alle onderdelen met betrekking tot energie, behalve een eventuele opzegboete, zijn belast met btw.  In deze eindafrekening verrekenen we het totaalbedrag uit de <span class=\"[final_bill_visible]\">eindafrekening</span>\r\n        <span class=\"[yearly_bill_visible]\">jaarafrekening</span> met de nog openstaande termijnfacturen. Dit zie je terug in onderstaand factuuroverzicht.\r\n    </p>\r\n    <p class=\"mb-3\" style=\"text-align: left !important;\">\r\n        [text_summary]\r\n    </p>\r\n    \r\n    <table class=\"table green-background\">\r\n        <thead>\r\n            <th class=\"pl-2 text-left\">FACTUUR</th>\r\n            <th class=\"pl-2 text-left\">FACTUURNUMMER</th>\r\n            <th class=\"pl-2 text-right\">BEDRAG</th>\r\n        </thead>\r\n        <tbody>\r\n        <tr class=\"green-background\">\r\n            <td class=\"pl-2\"> [title_difference_amount_unpaid_invoice_item] </td>\r\n            <td class=\"pl-2\">[reference_number_unpaid_invoice_item] </td>\r\n            <td class=\"pl-2 text-right\">[difference_amount_unpaid_invoice_item]</td>\r\n        </tr>\r\n        <tr  class=\"white-background\" style=\"height: 70px\">\r\n            <td style=\"background: transparent !important;\" class=\"pl-2\"> </td>\r\n            <td style=\"background: transparent !important;\" class=\"pl-2\"> </td>\r\n            <td style=\"background: transparent !important;\" class=\"pl-2 text-right font-weight-bold\">[difference_amount_unpaid_invoice_item]</td>\r\n        </tr>\r\n        [FINALBILL_TEMPLATE_PAID_AMOUNT_INVOICE_ITEM_CHILD]\r\n        <tr style=\"background: transparent;height: 50px\">\r\n            <td style=\"background: transparent !important;\" class=\"pl-2\"></td>\r\n            <td style=\"background: transparent !important;\" class=\"pl-2\"></td>\r\n            <td style=\"background: transparent !important;\" class=\"pl-2 text-right font-weight-bold\">[total_amount_unpaid_invoice_item]</td>\r\n        </tr>\r\n        <tr>\r\n            <table>\r\n            <tbody>\r\n                <tr>\r\n                <td style=\"height: 15px;\"></td>\r\n                </tr>\r\n                <tr>\r\n                <td class=\"w-100\"></td>\r\n                <td class=\"pl-2 text-right font-weight-bold text-nowrap t-nowrap mt-3\">\r\n                    <div class=\"border-top-bold position-relative\">\r\n                    <span class=\"pr-5\">[is_receive_payment]</span>\r\n                    <span>[payment_amount_unpaid_invoice_item]</span>\r\n                    </div>\r\n                </td>\r\n                </tr>\r\n            </tbody>\r\n            </table>\r\n        </tr>\r\n        </tbody>\r\n    </table>\r\n</div>', NULL, NULL, 'nl', 'ke-pdf', NULL, '2023-11-27 09:07:13.152323', NULL);
INSERT IGNORE INTO `templates_reseller` (`Id`, `reseller_id`, `template_name`, `html_content`, `header_id`, `footer_id`, `language_code`, `CreatedBy`, `ModifiedBy`, `CreatedAt`, `ModifiedAt`) VALUES (239, 197, 'FINALBILL_TEMPLATE_UNPAID_AMOUNT_INVOICE_ITEM_CHILD', '<tr class=\"green-background [visible_break_page]\">\r\n    <td class=\"pl-2\"> Openstaande termijnfactuur [month_unpaid_invoice_item] </td>\r\n    <td class=\"pl-2\">[reference_number_unpaid_invoice_item]</td>\r\n    <td class=\"pl-2 text-right \">[amount_unpaid_invoice_item]</td>\r\n</tr>\r\n<tr class=\"[hide_collection_cost_unpaid_amount] green-background\">\r\n    <td class=\"pl-2 font-italic\"> Incassokosten </td>\r\n    <td class=\"pl-2\">[reference_number_unpaid_invoice_item]</td>\r\n    <td class=\"pl-2 text-right\">[collection_cost_unpaid_invoice_item]</td>\r\n</tr>', NULL, NULL, 'nl', 'ke-pdf', NULL, '2023-11-27 09:07:13.152323', NULL);
INSERT IGNORE INTO `templates_reseller` (`Id`, `reseller_id`, `template_name`, `html_content`, `header_id`, `footer_id`, `language_code`, `CreatedBy`, `ModifiedBy`, `CreatedAt`, `ModifiedAt`) VALUES (246, 197, 'FINALBILL_TEMPLATE_USAGE_ITEM', '<table class=\"table table-custom table-usage\" cellspacing=\"0\" cellpadding=\"0\">\r\n    <thead>\r\n        <th>VERBRUIK ([start_date] / [end_date])<span class=\"[multil_ean_number_visible]\"><br>EAN [multil_ean_number]</span></th>\r\n        <th class=\"pl-2 text-center\"><span class=\"float-left\">EINDSTAND</span><span>-</span></th>\r\n        <th class=\"pl-2 text-center\"><span class=\"float-left\">BEGINSTAND</span><span>x</span></th>\r\n        <th class=\"pl-2 text-center\"><span class=\"float-left\">FACTOR</span><span>=</span></th>\r\n        <th class=\"pl-2 text-right\" style=\"width: 200px\">VERBRUIK</th>\r\n    </thead>\r\n    <tbody>\r\n        <tr class=\"[usage_item_dal_visible]\">\r\n            <td>\r\n                Stroom daltarief\r\n            </td>\r\n            <td>[usage_item_elk_end_dal]</td>\r\n            <td>[usage_item_elk_start_dal]</td>\r\n            <td>[usage_item_elk_factor_dal]</td>\r\n            <td class=\"text-right text-nowrap\">[usage_item_elk_total_dal] kWh</td>\r\n        </tr>\r\n        <tr class=\"[usage_item_normal_visible]\">\r\n            <td>\r\n                Stroom normaaltarief\r\n            </td>\r\n            <td>[usage_item_elk_end_normal]</td>\r\n            <td>[usage_item_elk_start_normal]</td>\r\n            <td>[usage_item_elk_factor_normal]</td>\r\n            <td class=\"text-right text-nowrap\">[usage_item_elk_total_normal] kWh</td>\r\n        </tr>\r\n        <tr class=\"[usage_item_return_dal_visible]\">\r\n            <td>\r\n                Stroom teruglevering daltarief\r\n            </td>\r\n            <td>[usage_item_return_end_dal]</td>\r\n            <td>[usage_item_return_start_dal]</td>\r\n            <td>[usage_item_return_factor_dal]</td>\r\n            <td class=\"text-right text-nowrap\">[usage_item_return_total_dal] kWh</td>\r\n        </tr>\r\n        <tr class=\"[usage_item_return_normal_visible]\">\r\n            <td>\r\n                Stroom teruglevering normaaltarief\r\n            </td>\r\n            <td>[usage_item_return_end_normal]</td>\r\n            <td>[usage_item_return_start_normal]</td>\r\n            <td>[usage_item_return_factor_normal]</td>\r\n            <td class=\"text-right text-nowrap\">[usage_item_return_total_normal] kWh</td>\r\n        </tr>\r\n        <tr class=\"[usage_item_gas_visible]\">\r\n            <td>\r\n                Gas\r\n            </td>\r\n            <td>[usage_item_gas_end]</td>\r\n            <td>[usage_item_gas_start]</td>\r\n            <td>[usage_item_gas_factor]</td>\r\n            <td class=\"text-right text-nowrap\">[usage_item_gas_total] m<sup>3</sup></td>\r\n        </tr> \r\n        <tr class=\"[period_usage_total_visible]\" style=\"background-color: transparent !important\">\r\n            <td style=\"background-color: transparent !important\"></td>\r\n            <td style=\"background-color: transparent !important\"></td>\r\n            <td style=\"background-color: transparent !important\"></td>\r\n            <td style=\"background-color: transparent !important\"></td>\r\n            <td class=\"text-right text-nowrap\" style=\"font-weight: bold; background-color: transparent !important\">[period_usage_total] [unit]</td>\r\n        </tr>\r\n        <tr class=\"[all_period_usage_total_visible]\"  style=\"background-color: transparent !important\">\r\n            <td style=\"background-color: transparent !important\"></td>\r\n            <td style=\"background-color: transparent !important\"></td>\r\n            <td style=\"background-color: transparent !important\"></td>\r\n            <td style=\"font-weight: bold;border-top: 1.5px solid #000000;background-color: transparent !important\">\r\n                <div style=\"white-space: nowrap; border-top: 1.5px solid #000000;\" >\r\n                    Totaalverbruik\r\n                    </div></td>\r\n            <td style=\"font-weight: bold;border-top: 1.5px solid #000000;background-color: transparent !important\">\r\n                <div class=\"text-right\" style=\"margin-left: -8px; white-space: nowrap; border-top: 1.5px solid #000000; \" >\r\n                    [all_period_usage_total] [unit]\r\n                    </div>\r\n            </td>\r\n            <!-- <td class=\"border-top-bold-td\" colspan=\"2\">\r\n                <div style=\"font-weight: bold;border-top: 1.5px solid #000000; display:flex; justify-content:space-between;\">\r\n                    <table>\r\n                        <tbody>\r\n                            <tr>\r\n                                <td>\r\n                                    <span style=\"white-space: nowrap\" >\r\n                    Totaalverbruik\r\n                    </span>\r\n                                </td>\r\n                                <td >\r\n                                </td>\r\n                                <td>\r\n                                    <span style=\"white-space: nowrap\" >\r\n                    [all_period_usage_total] [unit]\r\n                    </span>\r\n                                </td>\r\n                            </tr>\r\n                        </tbody>\r\n                    </table>\r\n                </div>\r\n                </td> -->\r\n            \r\n        </tr>\r\n    </tbody>\r\n</table>', NULL, NULL, 'nl', 'ke-pdf', NULL, '2023-11-27 09:07:13.152323', NULL);
INSERT IGNORE INTO `templates_reseller` (`Id`, `reseller_id`, `template_name`, `html_content`, `header_id`, `footer_id`, `language_code`, `CreatedBy`, `ModifiedBy`, `CreatedAt`, `ModifiedAt`) VALUES (253, 197, 'FINALBILL_TEMPLATE_USAGE_ITEM_HOURLY', '<table class=\"table table-custom table-usage green-background\" cellspacing=\"0\" cellpadding=\"0\">\r\n    <thead>\r\n        <th>VERBRUIK ([start_date] / [end_date])<span class=\"[multil_ean_number_visible]\"><br>EAN [multil_ean_number]</span></th>\r\n        <th class=\"pl-2 text-center\"><span class=\"float-left\">EINDSTAND</span><span>-</span></th>\r\n        <th class=\"pl-2 text-center\"><span class=\"float-left\">BEGINSTAND</span><span>x</span></th>\r\n        <th class=\"pl-2 text-center\"><span class=\"float-left\">FACTOR</span><span>=</span></th>\r\n        <th class=\"pl-2 text-right\" style=\"width: 200px\">VERBRUIK</th>\r\n    </thead>\r\n    <tbody>\r\n        <tr class=\"[usage_item_dal_visible] green-background\">\r\n            <td>\r\n                Stroom daltarief\r\n            </td>\r\n            <td>[usage_item_elk_end_dal]</td>\r\n            <td>[usage_item_elk_start_dal]</td>\r\n            <td>[usage_item_elk_factor_dal]</td>\r\n            <td class=\"text-right text-nowrap\">[usage_item_elk_total_dal] kWh</td>\r\n        </tr>\r\n        <tr class=\"[usage_item_normal_visible] green-background\">\r\n            <td>\r\n                Stroom normaaltarief\r\n            </td>\r\n            <td>[usage_item_elk_end_normal]</td>\r\n            <td>[usage_item_elk_start_normal]</td>\r\n            <td>[usage_item_elk_factor_normal]</td>\r\n            <td class=\"text-right text-nowrap\">[usage_item_elk_total_normal] kWh</td>\r\n        </tr>\r\n        <tr class=\"[usage_item_return_dal_visible] green-background\">\r\n            <td>\r\n                Stroom teruglevering daltarief\r\n            </td>\r\n            <td>[usage_item_return_end_dal]</td>\r\n            <td>[usage_item_return_start_dal]</td>\r\n            <td>[usage_item_return_factor_dal]</td>\r\n            <td class=\"text-right text-nowrap\">[usage_item_return_total_dal] kWh</td>\r\n        </tr>\r\n        <tr class=\"[usage_item_return_normal_visible] green-background\">\r\n            <td>\r\n                Stroom teruglevering normaaltarief\r\n            </td>\r\n            <td>[usage_item_return_end_normal]</td>\r\n            <td>[usage_item_return_start_normal]</td>\r\n            <td>[usage_item_return_factor_normal]</td>\r\n            <td class=\"text-right text-nowrap\">[usage_item_return_total_normal] kWh</td>\r\n        </tr>\r\n        <tr class=\"[usage_item_gas_visible] green-background\">\r\n            <td>\r\n                Gas\r\n            </td>\r\n            <td>[usage_item_gas_end]</td>\r\n            <td>[usage_item_gas_start]</td>\r\n            <td>[usage_item_gas_factor]</td>\r\n            <td class=\"text-right text-nowrap\">[usage_item_gas_total] m<sup>3</sup></td>\r\n        </tr> \r\n        <tr class=\"[period_usage_total_visible]\" style=\"background-color: transparent !important\">\r\n            <td style=\"background-color: transparent !important\"></td>\r\n            <td style=\"background-color: transparent !important\"></td>\r\n            <td style=\"background-color: transparent !important\"></td>\r\n            <td style=\"background-color: transparent !important\"></td>\r\n            <td class=\"text-right text-nowrap\" style=\"font-weight: bold;background-color: transparent !important\">[period_usage_total] [unit]</td>\r\n        </tr>\r\n        <tr class=\"[all_period_usage_total_visible]\"  style=\"background-color: transparent !important\">\r\n            <td style=\"background-color: transparent !important\"></td>\r\n            <td style=\"background-color: transparent !important\"></td>\r\n            <td style=\"background-color: transparent !important\"></td>\r\n            <td style=\"font-weight: bold;border-top: 1.5px solid #000000;background-color: transparent !important\">\r\n                <div style=\"white-space: nowrap; border-top: 1.5px solid #000000;\" >\r\n                    Totaalverbruik\r\n                    </div></td>\r\n            <td style=\"font-weight: bold;border-top: 1.5px solid #000000;background-color: transparent !important\">\r\n                <div class=\"text-right\" style=\"margin-left: -8px; white-space: nowrap; border-top: 1.5px solid #000000; \" >\r\n                    [all_period_usage_total] [unit]\r\n                    </div>\r\n            </td>\r\n            <!-- <td class=\"border-top-bold-td\" colspan=\"2\">\r\n                <div style=\"font-weight: bold;border-top: 1.5px solid #000000; display:flex; justify-content:space-between;\">\r\n                    <table>\r\n                        <tbody>\r\n                            <tr>\r\n                                <td>\r\n                                    <span style=\"white-space: nowrap\" >\r\n                    Totaalverbruik\r\n                    </span>\r\n                                </td>\r\n                                <td >\r\n                                </td>\r\n                                <td>\r\n                                    <span style=\"white-space: nowrap\" >\r\n                    [all_period_usage_total] [unit]\r\n                    </span>\r\n                                </td>\r\n                            </tr>\r\n                        </tbody>\r\n                    </table>\r\n                </div>\r\n                </td> -->\r\n            \r\n        </tr>\r\n    </tbody>\r\n</table>', NULL, NULL, 'nl', 'ke-pdf', NULL, '2023-11-27 09:07:13.152323', NULL);
INSERT IGNORE INTO `templates_reseller` (`Id`, `reseller_id`, `template_name`, `html_content`, `header_id`, `footer_id`, `language_code`, `CreatedBy`, `ModifiedBy`, `CreatedAt`, `ModifiedAt`) VALUES (260, 197, 'USAGE_BASED_INVOICE_MONTHLY_FOOTER_WHITE_TEMPLATE', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n\r\n<head>\r\n    <title>Billing | Kikker</title>\r\n    <meta charset=\"utf-8\">\r\n    <link rel=\"icon\" href=\"asset/kikker-icon.ico\" />\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\r\n    <link rel=\"stylesheet\" href=\"https://storage.googleapis.com/kikkerprodbucket/static-files/pdf-css/site.css\">\r\n</head>\r\n<style>\r\n    .footer {\r\n        position: relative;\r\n        max-width: 100% !important;\r\n        height: 70px;\r\n        margin-bottom: 20px;\r\n    }\r\n\r\n    .footer * {\r\n        font-size: 12px;\r\n        white-space: nowrap;\r\n    }\r\n\r\n    .footer-paging {\r\n        position: absolute;\r\n        bottom: 35px;\r\n        right: -100px;\r\n        transform: rotate(270deg);\r\n        width: 80px;\r\n        color: #7b7889;\r\n    }\r\n\r\n    .reseller-logo {\r\n        max-width: 60px;\r\n        max-height: 60px;\r\n        margin: 10px;\r\n\r\n    }\r\n\r\n    .reseller-logo img {\r\n        max-width: 60px;\r\n        max-height: 60px;\r\n        margin: 10px;\r\n    }\r\n\r\n    .footer-info {\r\n        display: flex;\r\n        flex-direction: row;\r\n        align-items: end;\r\n        line-height: 1.3;\r\n        width: 600px;\r\n        position: relative;\r\n        min-height: 60px;\r\n    }\r\n\r\n    .footer-info-child {\r\n        display: flex;\r\n        flex-direction: row;\r\n        align-items: end;\r\n        line-height: 1.3;\r\n        width: 100%;\r\n        position: relative;\r\n        min-height: 60px;\r\n    }\r\n</style>\r\n\r\n<body>\r\n    <div class=\"[hide_footer] footer\">\r\n        <div class=\"footer-info\">\r\n            <div class=\"[hide_footer_reseler] footer-info-child\">\r\n                <div>\r\n                    <b>[footer_reseller_name]</b><br>\r\n                    <p class=\"mb-0\">[footer_reseller_contact_street] [footer_reseller_contact_house_number] [footer_reseller_contact_house_number_extension]\r\n                      <br>[footer_reseller_contact_zipcode] [footer_reseller_contact_city]</p>\r\n                </div>\r\n                <div style=\" margin-left: 60px;\">\r\n                    <b>KvK </b><span style=\"padding-left: 7px;\">[footer_reseller_kvk]</span><br>\r\n                    <b>BTW </b><span style=\"padding-left: 4px\">[footer_reseller_btw]</span>\r\n                </div>\r\n                <div style=\"margin-left: 50px\">\r\n                    <b>Tel </b><span style=\"padding-left: 20px;\"> [footer_reseller_contact_phone]</span><br>\r\n                    <b>E-mail </b><span style=\"padding-left: 4px;\"> [footer_reseller_contact_email]\r\n                                </span>\r\n                </div>\r\n            </div>\r\n           \r\n            <div class=\"footer-paging\">\r\n                [page_number] van [total_page]\r\n            </div>\r\n        </div>\r\n       \r\n    </div>\r\n</body>\r\n\r\n</html>', NULL, NULL, 'nl', '', NULL, '2024-04-03 03:50:15.960706', NULL);
INSERT IGNORE INTO `templates_reseller` (`Id`, `reseller_id`, `template_name`, `html_content`, `header_id`, `footer_id`, `language_code`, `CreatedBy`, `ModifiedBy`, `CreatedAt`, `ModifiedAt`) VALUES (262, 197, 'FINALBILL_TEMPLATE_FIXED_DELIVERY_DYNAMIC_PAGE_VOLTI', '<table class=\"table table-custom mb-0 table_fixed_delivery\">\r\n  <thead class=\"[fixed_delivery_item_header_visible]\">\r\n    <th class=\"pl-2 th-elk text-nowrap\" style=\"overflow: visible !important;background-color: transparent !important\"> [reseller_name_upper] [is_green_energy] [product_type] [contract_duration] <span class=\"[multil_ean_number_visible]\">\r\n        <br>EAN [multil_ean_number] </span>\r\n      <br> ([start_date] / [end_date]) | [fixed_delivery_btw]% BTW\r\n    </th>\r\n    <th class=\"pl-2 text-right\" style=\"vertical-align: bottom;overflow: visible !important;background-color: transparent !important\">\r\n      <br>\r\n      <span class=\"float-left\">AANTAL</span>\r\n      <span class=\"d-inline-block pr-4\">x</span>\r\n    </th>\r\n    <th class=\"pl-2 text-right\" style=\"vertical-align: bottom;\">\r\n      <span class=\"float-left\">TARIEF</span>\r\n      <br>\r\n      <span class=\"float-left\">EXCL. BTW</span>\r\n      <span class=\"d-inline-block pr-4\">=</span>\r\n    </th>\r\n    <th class=\"pl-2 text-right\" style=\"vertical-align: bottom;\">BEDRAG <br> EXCL. BTW </th>\r\n  </thead>\r\n  <tbody> [fixed_delivery_item] <tr class=\"[fixed_delivery_item_total_visible] tr-total-vat\">\r\n      <td colspan=\"5\">\r\n        <div class=\"text-right\" style=\"margin-right: -4px;\">\r\n          <div class=\"text-nowrap\"> Subtotaal <span class=\"d-inline-block\" style=\"width: 140px;\"> [delivery_sub_total] </span>\r\n          </div>\r\n          <div class=\"text-tax-color text-nowrap [hide_delivery_vat_1]\"> btw [delivery_btw_1]% over [delivery_net_month_1] <span class=\"d-inline-block\" style=\"width: 140px;\"> [delivery_btw_amount_1] </span>\r\n          </div>\r\n          <div class=\"text-tax-color text-nowrap [hide_delivery_vat_2]\"> btw [delivery_btw_2]% over [delivery_net_month_2] <span class=\"d-inline-block\" style=\"width: 140px;\"> [delivery_btw_amount_2] </span>\r\n          </div>\r\n          <div class=\"d-inline-block border-top-bold-td text-nowrap font-weight-bold\"> Totaalbedrag voor leveringskosten voor [total_product_type] <span class=\"d-inline-block\" style=\"width: 140px;\"> [fixed_delivery_total] </span>\r\n          </div>\r\n        </div>\r\n      </td>\r\n    </tr>\r\n  </tbody>\r\n</table>', NULL, NULL, 'nl', 'ke-pdf', NULL, '2024-05-15 09:25:03.000000', NULL);
INSERT IGNORE INTO `templates_reseller` (`Id`, `reseller_id`, `template_name`, `html_content`, `header_id`, `footer_id`, `language_code`, `CreatedBy`, `ModifiedBy`, `CreatedAt`, `ModifiedAt`) VALUES (263, 197, 'FINALBILL_TEMPLATE_FIXED_DELIVERY_TYPE_VOLTI', '<tr class=\"[fixed_delivery_item_detail]\">\r\n    <td class=\"pl-2\">\r\n        [fixed_delivery_item_name]\r\n    </td>\r\n    <td class=\"pl-2\">[fixed_delivery_usage] [product_type_unit]</td>\r\n    <td class=\"pl-2\">[fixed_delivery_tariff]</td>\r\n    <td class=\"pl-2 text-right\">[fixed_delivery_amount]</td>\r\n</tr>\r\n\r\n<tr style=\"background-color: transparent !important\" class=\"background-none [fixed_delivery_item_total]\">\r\n    <td style=\"background-color: transparent !important\" class=\"pl-2\"></td>\r\n    <td style=\"background-color: transparent !important\" class=\"pl-2\"></td>\r\n    <td style=\"background-color: transparent !important\" class=\"pl-2\"></td>\r\n    <td style=\"background-color: transparent !important\" class=\"pl-2 font-weight-bold text-right\">[fixed_delivery_total]</td>\r\n</tr>', NULL, NULL, 'nl', 'ke-pdf', NULL, '2024-05-15 09:25:04.000000', NULL);
INSERT IGNORE INTO `templates_reseller` (`Id`, `reseller_id`, `template_name`, `html_content`, `header_id`, `footer_id`, `language_code`, `CreatedBy`, `ModifiedBy`, `CreatedAt`, `ModifiedAt`) VALUES (264, 197, 'FINALBILL_TEMPLATE_MAIN_VOLTI', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n  <head>\r\n    <title>Billing | Kikker</title>\r\n    <meta charset=\"utf-8\">\r\n    <link rel=\"icon\" href=\"asset/kikker-icon.ico\" />\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\r\n    <link rel=\"stylesheet\" href=\"https://storage.googleapis.com/kikkerprodbucket/static-files/pdf-css/site.css\">\r\n    <link rel=\"stylesheet\" href=\"https://storage.googleapis.com/kikkerprodbucket/static-files/pdf-css/final_bill.css\">\r\n  </head>\r\n  <body>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div class=\"row header mr-0 ml-0\">\r\n            <div style=\"width: 33%;\">\r\n            </div>\r\n            <div class=\"[hide-header-invoice-info] header-invoice-info\">\r\n                <div class=\"d-flex justify-content-end\">\r\n                    <div class=\"space-span d-inline-block\" style=\"padding-top: 0\">\r\n                        <div class=\"mb-0 d-flex\">\r\n                            <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\">Klantnummer:</p>\r\n                            <p class=\"mb-0\">[client_number]</p>\r\n                        </div>\r\n                        <div class=\"mb-0 d-flex\">\r\n                            <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\"\r\n                                >Contractnummer:\r\n                            </p>\r\n                            <p class=\"mb-0\">[contract_number]</p>\r\n                        </div>\r\n                        <div class=\"mb-0 d-flex [hidden_contract_reference]\" style=\"flex-flow: row;\">\r\n                            <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\">Contractreferentie: </p>\r\n                            <p class=\"mb-0\">[contract_reference]</p>\r\n                        </div>\r\n                        <div class=\"mb-0 d-flex\">\r\n                            <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\"\r\n                                >Factuurnummer:\r\n                            </p>\r\n                            <p class=\"mb-0\">[invoice_number]</p>\r\n                        </div>\r\n                        <div class=\"mb-0 d-flex [company_name_visible]\" style=\"flex-flow: row;\">\r\n                            <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\">Bedrijfsnaam: </p>\r\n                            <p class=\"mb-0\">[company_name]</p>\r\n                        </div>\r\n                        <div class=\"mb-0 d-flex\" style=\"flex-flow: row;\">\r\n                            <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\">Energie intermediair: </p>\r\n                            <p class=\"mb-0\">[header_reseller_name]</p>\r\n                        </div>\r\n                        <div class=\"mb-0 d-flex\">\r\n                            <p class=\"text-right vertical-align-top pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\"\r\n                                >Leveringsadres:</p\r\n                            >\r\n                            <p class=\"mb-0\" class=\"d-inline-block\"\r\n                                >[delivery_address_street] [delivery_address_houseNr] [delivery_address_zipcode]<br><span class=\"text-capitalize\">[delivery_address_city]</span></p\r\n                            >\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n          <div class=\"row\">\r\n            <div class=\"col-12\">\r\n                <p class=\"mb-4\">\r\n                <span class=\"float-right\">[date_generate_PDF]</span>\r\n              </p>\r\n              <p class=\"mb-4\">Beste [customer_first_name],</p>\r\n              <p class=\"mb-4 [final_bill_visible]\">Dit is je eindafrekening over de verbruiksperiode van [final_bill_start_date] tot [final_bill_end_date] voor je leveringsadres [delivery_address_street] [delivery_address_houseNr] te <span class=\"text-capitalize\">[delivery_address_city]</span>. Je ontvangt deze afrekening omdat je contract met [reseller_name] eindigt. In deze eindafrekening berekenen we de kosten tot de einddatum van je contract. Indien je onlangs een nieuw [reseller_name]-contract hebt afgesloten, ontvang je hier apart bericht van. </p>\r\n              <p class=\"mb-4 [yearly_bill_visible]\">Dit is je jaarafrekening over de verbruiksperiode van [final_bill_start_date] tot [final_bill_end_date] voor je leveringsadres [delivery_address_street] [delivery_address_houseNr] te <span class=\"text-capitalize\">[delivery_address_city]</span>. In deze jaarafrekening vind je een overzicht van je energieverbruik in het afgelopen jaar en wat je hiervoor hebt betaald. </p>\r\n            </div>\r\n          </div>\r\n          [FINALBILL_TEMPLATE_UNPAID_AMOUNT_INVOICE_ITEM]\r\n          [FINALBILL_TEMPLATE_PAID_AMOUNT_INVOICE_ITEM]\r\n          <div style=\"page-break-before: always\" class=\"[yearly_bill_visible] [new_monthly_amount_visible]\"></div>\r\n          <div class=\"mt-3\">\r\n            <p class=\"mb-1 font-weight-bold [yearly_bill_visible] [new_monthly_amount_visible]\"> Je nieuwe termijnbedrag </span>\r\n            </p>\r\n            <p class=\"mb-4 [yearly_bill_visible] [new_monthly_amount_visible]\"> Op basis van je verbruik in de afgelopen 12 maanden, hebben we een nieuw termijnbedrag voor je uitgerekend. We passen het termijnbedrag automatisch voor je aan. Ben je het niet eens met je nieuwe termijnbedrag? Dan kun je dit gemakkelijk aanpassen in onze mobiele app. </p>\r\n          </div>\r\n          <div class=\"row monthly-amount-block [yearly_bill_visible] [new_monthly_amount_visible] mt-4\" style=\"background-image: url(\'data:image/png;base64,\');background-size: 100%; background-repeat: no-repeat; background-position: center center;\">\r\n            <div class=\"col-6\">\r\n              <span> Oude termijnbedrag </span>\r\n              <span class=\"float-right\"> € [current_monthly_amount] </span>\r\n            </div>\r\n            <div class=\"col-6 pl-5 font-weight-bold\">\r\n              <span> Nieuwe termijnbedrag </span>\r\n              <span class=\"float-right\"> € [new_monthly_amount] </span>\r\n            </div>\r\n          </div>\r\n          <div class=\"mt-3 avoid-break-page\">\r\n            <p class=\"font-weight-bold mb-1\">Vragen?</p>\r\n            <p class=\"mb-3\" style=\"text-align: left;\">Neem contact op met jouw wederverkoper [reseller_name]. Dit kun je doen via e-mail op [reseller_email] of telefonisch op [reseller_phone].</p>\r\n            <p class=\"mb-3\">Met vriendelijke groet, </p>\r\n            <p class=\"mb-0\">[reseller_name]</p>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div>\r\n          <p>Meer informatie over je verbruik of de precieze berekening van je <span class=\"[final_bill_visible]\">eindafrekening</span> <span class=\"[yearly_bill_visible]\">jaarafrekening</span> vind je op de volgende pagina’s.</p>\r\n          <div class=\"mb-1 font-weight-bold\">Samenvatting van je <span class=\"[final_bill_visible]\">eindafrekening</span>\r\n            <span class=\"[yearly_bill_visible]\">jaarafrekening</span>\r\n          </div>\r\n          <div class=\"[hide_text_summary]\">[text_summary]</div>\r\n          <div class=\"mt-5\">\r\n            <table class=\"table table-first\">\r\n              <tbody>\r\n                <tr>\r\n                  <td class=\"pl-2\"> 1. Leveringskosten van [product_type] </td>\r\n                  <td class=\"pl-2 text-right\">[total_delivery_amount]</td>\r\n                </tr>\r\n                <tr class=\"[show_price_cap_billing]\">\r\n                  <td class=\"pl-2\"> 2. Tegemoetkoming uit het prijsplafond</td>\r\n                  <td class=\"pl-2 text-right\">[total_price_cap]</td>\r\n                </tr>\r\n                <tr>\r\n                  <td class=\"pl-2 [hide_price_cap_billing]\"> 2. Overheidsheffingen op [product_type], dit dragen we af aan de overheid </td>\r\n                  <td class=\"pl-2 [show_price_cap_billing]\"> 3. Overheidsheffingen op [product_type], dit dragen we af aan de overheid </td>\r\n                  <td class=\"pl-2 text-right\">[total_tax_amount]</td>\r\n                </tr>\r\n                <tr>\r\n                  <td class=\"pl-2 [hide_price_cap_billing]\"> 3. Netbeheerkosten op [product_type], dit dragen we af aan je netbeheerder </td>\r\n                  <td class=\"pl-2 [show_price_cap_billing]\"> 4. Netbeheerkosten op [product_type], dit dragen we af aan je netbeheerder </td>\r\n                  <td class=\"pl-2 text-right\">[total_grid_operator_amount]</td>\r\n                </tr>\r\n                <tr>\r\n                  <td class=\"pl-2 font-weight-bold\"></td>\r\n                  <td class=\"pl-2 text-right  font-weight-bold\">[total_real_amount_incl_cancel_fee]</td>\r\n                </tr>\r\n              </tbody>\r\n            </table>\r\n          </div>\r\n          <div class=\"mt-5\">\r\n            <table class=\"table table-first\">\r\n              <tbody>\r\n                <tr>\r\n                  <td class=\"pl-2 [hide_price_cap_billing]\"> 4. In rekening gebrachte termijnbedragen </td>\r\n                  <td class=\"pl-2 [show_price_cap_billing]\"> 5. In rekening gebrachte termijnbedragen </td>\r\n                  <td class=\"pl-2 text-right\">[total_generated_amount_negative]</td>\r\n                </tr>\r\n                <tr class=\"[total_unpaid_amount_class]\">\r\n                  <td class=\"pl-4 font-italic\"> Openstaande termijnbedragen </td>\r\n                  <td class=\"pl-2 text-right\">[total_unpaid_amount]</td>\r\n                </tr>\r\n                <tr class=\"[total_collection_cost_amount_class]\">\r\n                  <td class=\"pl-4 font-italic\"> Openstaande incassokosten </td>\r\n                  <td class=\"pl-2 text-right\">[total_collection_cost_amount]</td>\r\n                </tr>\r\n                <tr>\r\n                  <td class=\"pl-2 font-weight-bold\"></td>\r\n                  <td class=\"pl-2 text-right  font-weight-bold\">[total_real_generated_amount_negative]</td>\r\n                </tr>\r\n              </tbody>\r\n            </table>\r\n            <table>\r\n              <tbody>\r\n                <tr>\r\n                  <td class=\"w-100\"></td>\r\n                  <td class=\"pl-2 text-right font-weight-bold text-nowrap t-nowrap\">\r\n                    <div class=\"border-top-bold position-relative\">\r\n                      <span class=\"pr-5\">[is_receive]</span>\r\n                      <span>€ [difference_amount]</span>\r\n                    </div>\r\n                  </td>\r\n                </tr>\r\n              </tbody>\r\n            </table>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div class=\"[usage_only_gas_elk_visible]\">\r\n            <p class=\"mb-1 font-weight-bold\"> Berekening van je verbruik </p>\r\n            <p class=\"mb-5\"> Op basis van je meterstanden bepalen wij hoeveel energie je hebt verbruikt. De meterstanden lezen wij uit via je slimme meter, vragen wij bij je op of berekenen we zelf. Onderstaand vind je een overzicht van je verbruik per periode. Omdat tussen periodes soms verschillende tarieven gelden, kan het zijn dat je verschillende periodes ziet. </p>\r\n          </div>\r\n          <div class=\"[usage_only_gas_elk_visible]\"> [usage_item_by_ean] </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div class=\"[usage_only_gas_elk_visible]\" style=\"page-break-before: always\"></div>\r\n    <div class=\"page [usage_both_gas_elk_visible]\">\r\n        <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n            <div>\r\n                <p class=\"mb-1 font-weight-bold\">\r\n                    Berekening van je verbruik\r\n                </p>\r\n                <p class=\"mb-5\">\r\n                    Op basis van je meterstanden bepalen wij hoeveel energie je hebt verbruikt. De meterstanden lezen wij uit via je\r\n                    slimme meter, vragen wij bij je op of berekenen we zelf. Onderstaand vind je een overzicht van je\r\n                    verbruik per periode. Omdat tussen periodes soms verschillende tarieven gelden, kan het zijn dat je verschillende\r\n                    periodes ziet.\r\n                </p>\r\n            </div>\r\n\r\n            <div class=\"table-usage\">\r\n                [usage_item_by_ean]\r\n            </div>\r\n        </div>\r\n        </div>\r\n    </div>\r\n    <div class=\"[usage_both_gas_elk_visible]\" style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div>\r\n            <p class=\"mb-4\">Op de volgende pagina’s vind je een nadere specificatie van de kosten die weergegeven zijn op pagina 2.</p>\r\n            [return_tariff_section]\r\n            <p class=\"mb-1 font-weight-bold\">1. Leveringskosten voor [product_type]</p>\r\n            <p class=\"mb-5\"> Onderstaand vind je een specificatie van je leveringskosten voor [product_type]. Door je verbruik te vermenigvuldigen met je tarief bepalen we je kosten per contract. </p>\r\n          </div>\r\n          <div class=\"table_fixed_delivery\"> [fixed_delivery_item_dynamic_page] </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    [price_cap_section_template]\r\n\r\n\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div class=\"row\">\r\n            <div class=\"col-12\">\r\n              <p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">2. Overheidsheffingen op [product_type]</p>\r\n              <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">3. Overheidsheffingen op [product_type]</p>\r\n              <p>Naast de kosten voor het verbruik van [product_type], moet je ook belastingen betalen aan de overheid. Ook deze zijn afhankelijk van je verbruik. Onderstaande kosten dragen wij direct af aan de overheid. Omdat de heffingen jaarlijks (per 1 januari) veranderen zie je onderstaand mogelijk twee berekeningen: een voor de periode vóór en een voor de periode ná 1 januari.</p>\r\n            </div>\r\n          </div>\r\n          <div class=\"mt-3\"> [tax_item_dynamic_page] </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div class=\"row\">\r\n            <div class=\"col-12\">\r\n              <p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">3. Netbeheerkosten voor [product_type]</p>\r\n              <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">4. Netbeheerkosten voor [product_type]</p>\r\n              <p class=\"mb-3\">Om van [product_type] gebruik te kunnen maken, dien je aangesloten te zijn op het openbare [product_type]netwerk van je netbeheerder. Hiervoor betaal je een vaste vergoeding die afhankelijk is van je aansluiting. Wij dragen deze vervolgens weer af aan je netbeheerder. Ook hier geldt dat de tarieven jaarlijks per 1 januari wijzigen. Om deze reden zie je onderstaand mogelijk weer twee berekeningen: voor de periode vóór en de periode ná 1 januari. </p>\r\n              <p> Je netbeheerder: <strong>[grid_operator_name]</strong>\r\n              </p>\r\n            </div>\r\n          </div>\r\n          <div class=\"mt-3 custom-table table_grid_operator\"> [grid_operator_item_dynamic_page] </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n          <div class=\"content\">\r\n            <div class=\"row\">\r\n              <div class=\"col-12\">\r\n              	<p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">4. Totaal in rekening gebrachte termijnbedragen</p>\r\n                <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">5. Totaal in rekening gebrachte termijnbedragen</p>\r\n                <p class=\"mb-1\">Hier zie je een overzicht van de door ons in rekening gebrachte termijnbedragen in de afgelopen periode (incl. btw). Een negatief termijnbedrag wordt als niet in rekening gebracht beschouwd en daarom als 0 weergegeven.</p>\r\n              </div>\r\n            </div>\r\n            <div class=\"mt-5\">\r\n              <table class=\"table table-custom\">\r\n                <thead>\r\n                  <th class=\"pl-2 charge-item-month-column\">MAAND</th>\r\n                  <th class=\"pl-2 charge-item-invoice-number\">FACTUURNUMMER</th>\r\n                  <th class=\"pl-2 text-right\" colspan=\"2\">BEDRAG</th>\r\n                </thead>\r\n                <tbody> [charged_item_by_month] </tbody>\r\n              </table>\r\n              <table>\r\n                <tbody>\r\n                  <tr>\r\n                    <td style=\"height: 15px;\"></td>\r\n                  </tr>\r\n                  <tr>\r\n                    <td class=\"w-100\"></td>\r\n                    <td class=\"pl-2 text-right font-weight-bold text-nowrap t-nowrap\">\r\n                      <div class=\"border-top-bold position-relative\">\r\n                        <span class=\"pr-5\">Totaal in rekening gebrachte termijnbedragen</span>\r\n                        <span>[total_generated_amount]</span>\r\n                      </div>\r\n                    </td>\r\n                  </tr>\r\n                </tbody>\r\n              </table>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n      <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div>\r\n            <p class=\"font-weight-bold\">Jouw EAN-codes</p> [elk_gas_eans]\r\n          </div>\r\n          <div class=\"mt-5\">\r\n            <p class=\"font-weight-bold\">Btw-aangifte</p>\r\n            <p class=\"mb-0\"> [reseller_name] handelt onder de leveranciersvergunning van Kikker Energie. In het geval je een btw-aangifte moet doen, dien je daarom de gegevens van Kikker Energie te gebruiken. De benodigde informatie van Kikker Energie en je netbeheerder vind je onderstaand: </p>\r\n          </div>\r\n          <div class=\"row mt-4\">\r\n            <div class=\"col-5\">\r\n              <p class=\"mb-0\"> Kikker Energie B.V. </br> Tolnasingel 12 </br> 2411PV Bodegraven </p>\r\n              <p class=\"mb-0\">KvK: 71246681</p>\r\n              <p class=\"mb-0\">Btw nr.: NL858635732B01</p>\r\n            </div>\r\n            <div class=\"col-5\">\r\n              <p class=\"mb-0\"> [grid_operator_name] </br> [grid_operator_house_nr] </br> [grid_operator_postcode] </p>\r\n              <p class=\"mb-0\">KvK: [grid_operator_kvk]</p>\r\n              <p class=\"mb-0\">Btw nr.: [grid_operator_btw]</p>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </body>\r\n</html>', NULL, NULL, 'nl', 'ke-pdf', NULL, '2023-11-27 09:07:13.152323', NULL);
INSERT IGNORE INTO `templates_reseller` (`Id`, `reseller_id`, `template_name`, `html_content`, `header_id`, `footer_id`, `language_code`, `CreatedBy`, `ModifiedBy`, `CreatedAt`, `ModifiedAt`) VALUES (265, 197, 'FINALBILL_TEMPLATE_MAIN_CANCELATION_FEE_VOLTI', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n  <head>\r\n    <title>Billing | Kikker</title>\r\n    <meta charset=\"utf-8\">\r\n    <link rel=\"icon\" href=\"asset/kikker-icon.ico\" />\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\r\n    <link rel=\"stylesheet\" href=\"https://storage.googleapis.com/kikkerprodbucket/static-files/pdf-css/site.css\">\r\n    <link rel=\"stylesheet\" href=\"https://storage.googleapis.com/kikkerprodbucket/static-files/pdf-css/final_bill.css\">\r\n  </head>\r\n  \r\n  <body>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div class=\"row header mr-0 ml-0\">\r\n            <div style=\"width: 33%;\">\r\n            </div>\r\n            <div class=\"[hide-header-invoice-info] header-invoice-info\">\r\n                <div class=\"d-flex justify-content-end\">\r\n                    <div class=\"space-span d-inline-block\" style=\"padding-top: 0\">\r\n                        <div class=\"mb-0 d-flex\">\r\n                            <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\">Klantnummer:</p>\r\n                            <p class=\"mb-0\">[client_number]</p>\r\n                        </div>\r\n                        <div class=\"mb-0 d-flex\">\r\n                            <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\"\r\n                                >Contractnummer:\r\n                            </p>\r\n                            <p class=\"mb-0\">[contract_number]</p>\r\n                        </div>\r\n                        <div class=\"mb-0 d-flex [hidden_contract_reference]\" style=\"flex-flow: row;\">\r\n                            <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\">Contractreferentie: </p>\r\n                            <p class=\"mb-0\">[contract_reference]</p>\r\n                        </div>\r\n                        <div class=\"mb-0 d-flex\">\r\n                            <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\"\r\n                                >Factuurnummer:\r\n                            </p>\r\n                            <p class=\"mb-0\">[invoice_number]</p>\r\n                        </div>\r\n                        <div class=\"mb-0 d-flex [company_name_visible]\" style=\"flex-flow: row;\">\r\n                            <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\">Bedrijfsnaam: </p>\r\n                            <p class=\"mb-0\">[company_name]</p>\r\n                        </div>\r\n                        <div class=\"mb-0 d-flex\" style=\"flex-flow: row;\">\r\n                            <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\">Energie intermediair: </p>\r\n                            <p class=\"mb-0\">[header_reseller_name]</p>\r\n                        </div>\r\n                        <div class=\"mb-0 d-flex\">\r\n                            <p class=\"text-right vertical-align-top pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\"\r\n                                >Leveringsadres:</p\r\n                            >\r\n                            <p class=\"mb-0\" class=\"d-inline-block\"\r\n                                >[delivery_address_street] [delivery_address_houseNr] [delivery_address_zipcode]<br><span class=\"text-capitalize\">[delivery_address_city]</span></p\r\n                            >\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n          <div class=\"row\">\r\n            <div class=\"col-12\">\r\n                <p class=\"mb-0\">\r\n                    <span class=\"float-right\">[date_generate_PDF]</span>\r\n                  </p>\r\n              <p class=\"mt-5\">Beste [customer_first_name],</p>\r\n              <p class=\"mt-4 [final_bill_visible]\">Dit is je eindafrekening over de verbruiksperiode van [final_bill_start_date] tot [final_bill_end_date] voor je leveringsadres [delivery_address_street] [delivery_address_houseNr] te <span class=\"text-capitalize\">[delivery_address_city]</span>. Je ontvangt deze afrekening omdat je contract met [reseller_name] eindigt. In deze eindafrekening berekenen we de kosten tot de einddatum van je contract. Indien je onlangs een nieuw [reseller_name]-contract hebt afgesloten, ontvang je hier apart bericht van. </p>\r\n              <p class=\"mt-4 [yearly_bill_visible]\">Dit is je jaarafrekening over de verbruiksperiode van [final_bill_start_date] tot [final_bill_end_date] voor je leveringsadres [delivery_address_street] [delivery_address_houseNr] te <span class=\"text-capitalize\">[delivery_address_city]</span>. In deze jaarafrekening vind je een overzicht van je energieverbruik in het afgelopen jaar en wat je hiervoor hebt betaald. </p>\r\n            </div>\r\n          </div>\r\n          [FINALBILL_TEMPLATE_UNPAID_AMOUNT_INVOICE_ITEM]\r\n          [FINALBILL_TEMPLATE_PAID_AMOUNT_INVOICE_ITEM]\r\n          <div>\r\n            <p class=\"mb-1 font-weight-bold [yearly_bill_visible] [new_monthly_amount_visible]\"> \r\n                <span>Je nieuwe termijnbedrag </span>\r\n            </p>\r\n            <p class=\"mb-4 [yearly_bill_visible] [new_monthly_amount_visible]\"> Op basis van je verbruik in de afgelopen 12 maanden, hebben we een nieuw termijnbedrag voor je uitgerekend. We passen het termijnbedrag automatisch voor je aan. Ben je het niet eens met je nieuwe termijnbedrag? Dan kun je dit gemakkelijk aanpassen in onze mobiele app. </p>\r\n          </div>\r\n          <div class=\"row monthly-amount-block [yearly_bill_visible] [new_monthly_amount_visible] mt-4\" style=\"background-image: url(\'data:image/png;base64,\');background-size: 100%; background-repeat: no-repeat; background-position: center center;\">\r\n            <div class=\"col-6\">\r\n              <span> Oude termijnbedrag </span>\r\n              <span class=\"float-right\"> € [current_monthly_amount] </span>\r\n            </div>\r\n            <div class=\"col-6 pl-5 font-weight-bold\">\r\n              <span> Nieuwe termijnbedrag </span>\r\n              <span class=\"float-right\"> € [new_monthly_amount] </span>\r\n            </div>\r\n          </div>\r\n          <div class=\"mt-4 avoid-break-page\">\r\n            <p class=\"font-weight-bold mb-1\">Vragen?</p>\r\n            <p class=\"mb-3\" style=\"text-align: left;\">Neem contact op met jouw wederverkoper [reseller_name]. Dit kun je doen via e-mail op [reseller_email] of telefonisch op [reseller_phone].</p>\r\n            <p class=\"mb-3\">Met vriendelijke groet, </p>\r\n            <p class=\"mb-0\">[reseller_name]</p>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div class=\"row\">\r\n            <div class=\"col-12\">\r\n              <p>Meer informatie over je verbruik of de precieze berekening van je <span class=\"[final_bill_visible]\">eindafrekening</span> <span class=\"[yearly_bill_visible]\">jaarafrekening</span> vind je op de volgende pagina’s.</p>\r\n              <p class=\"mb-1 font-weight-bold\">Samenvatting van je <span class=\"[final_bill_visible]\">eindafrekening</span>\r\n                <span class=\"[yearly_bill_visible]\">jaarafrekening</span>\r\n              </p>\r\n            </div>\r\n          </div>\r\n          <div class=\"[hide_text_summary]\">[text_summary]</div>\r\n          <div class=\"mt-5 table-first\">\r\n            <table class=\"table\">\r\n              <tbody>\r\n                <tr>\r\n                  <td class=\"pl-2\"> 1. Leveringskosten van [product_type] </td>\r\n                  <td class=\"pl-2 text-right\">[total_delivery_amount]</td>\r\n                </tr>\r\n                <tr class=\"[show_price_cap_billing]\">\r\n                    <td class=\"pl-2\"> 2. Tegemoetkoming uit het prijsplafond</td>\r\n                    <td class=\"pl-2 text-right\">[total_price_cap]</td>\r\n                </tr>\r\n                <tr>\r\n                    <td class=\"pl-2 [hide_price_cap_billing]\"> 2. Overheidsheffingen op [product_type], dit dragen we af aan de overheid </td>\r\n                    <td class=\"pl-2 [show_price_cap_billing]\"> 3. Overheidsheffingen op [product_type], dit dragen we af aan de overheid </td>\r\n                    <td class=\"pl-2 text-right\">[total_tax_amount]</td>\r\n                </tr>\r\n                <tr>\r\n                    <td class=\"pl-2 [hide_price_cap_billing]\"> 3. Netbeheerkosten op [product_type], dit dragen we af aan je netbeheerder </td>\r\n                    <td class=\"pl-2 [show_price_cap_billing]\"> 4. Netbeheerkosten op [product_type], dit dragen we af aan je netbeheerder </td>\r\n                    <td class=\"pl-2 text-right\">[total_grid_operator_amount]</td>\r\n                </tr>\r\n                <tr>\r\n                    <td class=\"pl-2 [hide_price_cap_billing]\"> 4. Opzegboete voor tussentijdse opzegging </td>\r\n                    <td class=\"pl-2 [show_price_cap_billing]\"> 5. Opzegboete voor tussentijdse opzegging </td>\r\n                    <td class=\"pl-2 text-right\">[cancelation_fee]</td>\r\n                </tr>\r\n                <tr>\r\n                  <td class=\"pl-2 font-weight-bold\"></td>\r\n                  <td class=\"pl-2 text-right  font-weight-bold\">[total_real_amount_incl_cancel_fee]</td>\r\n                </tr>\r\n              </tbody>\r\n            </table>\r\n          </div>\r\n          <div class=\"mt-4 table-first\">\r\n            <table class=\"table\">\r\n              <tbody>\r\n                <tr>\r\n                    <td class=\"pl-2 [hide_price_cap_billing]\"> 5. In rekening gebrachte termijnbedragen </td>\r\n                    <td class=\"pl-2 [show_price_cap_billing]\"> 6. In rekening gebrachte termijnbedragen </td>\r\n                    <td class=\"pl-2 text-right\">[total_generated_amount_negative]</td>\r\n                </tr>\r\n                <tr class=\"[total_unpaid_amount_class]\">\r\n                  <td class=\"pl-4 font-italic\"> Openstaande termijnbedragen </td>\r\n                  <td class=\"pl-2 text-right\">[total_unpaid_amount]</td>\r\n                </tr>\r\n                <tr class=\"[total_collection_cost_amount_class]\">\r\n                  <td class=\"pl-4 font-italic\"> Openstaande incassokosten </td>\r\n                  <td class=\"pl-2 text-right\">[total_collection_cost_amount]</td>\r\n                </tr>\r\n                <tr>\r\n                  <td class=\"pl-2 font-weight-bold\"></td>\r\n                  <td class=\"pl-2 text-right  font-weight-bold\">[total_real_generated_amount_negative]</td>\r\n                </tr>\r\n              </tbody>\r\n            </table>\r\n            <table>\r\n              <tbody>\r\n                <tr>\r\n                  <td class=\"w-100\"></td>\r\n                  <td class=\"pl-2 text-right font-weight-bold text-nowrap t-nowrap\">\r\n                    <div class=\"border-top-bold position-relative\">\r\n                      <span class=\"pr-5\">[is_receive]</span>\r\n                      <span>€ [difference_amount]</span>\r\n                    </div>\r\n                  </td>\r\n                </tr>\r\n              </tbody>\r\n            </table>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div class=\"[usage_only_gas_elk_visible]\">\r\n            <p class=\"mb-1 font-weight-bold\"> Berekening van je verbruik </p>\r\n            <p> Op basis van je meterstanden bepalen wij hoeveel energie je hebt verbruikt. De meterstanden lezen wij uit via je slimme meter, vragen wij bij je op of berekenen we zelf. Onderstaand vind je een overzicht van je verbruik per periode. Omdat tussen periodes soms verschillende tarieven gelden, kan het zijn dat je verschillende periodes ziet. </p>\r\n          </div>\r\n          <div class=\"mt-5 [usage_only_gas_elk_visible]\"> [usage_item_by_ean] </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div class=\"[usage_only_gas_elk_visible]\" style=\"page-break-before: always\"></div>\r\n    <div class=\"page [usage_both_gas_elk_visible]\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div>\r\n                    <p class=\"mb-1 font-weight-bold\">\r\n                        Berekening van je verbruik\r\n                    </p>\r\n                    <p class=\"mb-5\">\r\n                        Op basis van je meterstanden bepalen wij hoeveel energie je hebt verbruikt. De meterstanden lezen wij uit via je\r\n                        slimme meter, vragen wij bij je op of berekenen we zelf. Onderstaand vind je een overzicht van je\r\n                        verbruik per periode. Omdat tussen periodes soms verschillende tarieven gelden, kan het zijn dat je verschillende\r\n                        periodes ziet.\r\n                    </p>\r\n                </div>\r\n\r\n                <div class=\"table-usage\">\r\n                    [usage_item_by_ean]\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    <div class=\"[usage_both_gas_elk_visible]\" style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div>\r\n            <p class=\"mb-4\">Op de volgende pagina’s vind je een nadere specificatie van de kosten die weergegeven zijn op pagina 2.</p>\r\n            [return_tariff_section]\r\n            <p class=\"mb-1 font-weight-bold\">1. Leveringskosten voor [product_type]</p>\r\n            <p class=\"mb-5\"> Onderstaand vind je een specificatie van je leveringskosten voor [product_type]. Door je verbruik te vermenigvuldigen met je tarief bepalen we je kosten per contract. </p>\r\n          </div>\r\n          <div class=\"table_fixed_delivery\"> [fixed_delivery_item_dynamic_page] </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    [price_cap_section_template]\r\n\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div class=\"row\">\r\n            <div class=\"col-12\">\r\n                <p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">2. Overheidsheffingen op [product_type]</p>\r\n                <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">3. Overheidsheffingen op [product_type]</p>\r\n              <p style=\"display: [show_new_ode_tax_description]\">Naast de kosten voor het verbruik van [product_type], moet je ook belastingen betalen aan de overheid. Ook deze zijn afhankelijk van je verbruik. Onderstaande kosten dragen wij direct af aan de overheid. Omdat de heffingen jaarlijks (per 1 januari) veranderen zie je onderstaand mogelijk twee berekeningen: een voor de periode vóór en een voor de periode ná 1 januari.</p>\r\n            </div>\r\n          </div>\r\n          <div class=\"mt-3\"> [tax_item_dynamic_page] </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div class=\"row\">\r\n            <div class=\"col-12\">\r\n            <p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">3. Netbeheerkosten voor [product_type]</p>\r\n            <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">4. Netbeheerkosten voor [product_type]</p>\r\n              <p class=\"mb-3\">Om van [product_type] gebruik te kunnen maken, dien je aangesloten te zijn op het openbare [product_type]netwerk van je netbeheerder. Hiervoor betaal je een vaste vergoeding die afhankelijk is van je aansluiting. Wij dragen deze vervolgens weer af aan je netbeheerder. Ook hier geldt dat de tarieven jaarlijks per 1 januari wijzigen. Om deze reden zie je onderstaand mogelijk weer twee berekeningen: voor de periode vóór en de periode ná 1 januari. </p>\r\n              <p> Je netbeheerder: <strong>[grid_operator_name]</strong>\r\n              </p>\r\n            </div>\r\n          </div>\r\n          <div class=\"mt-3 custom-table table_grid_operator\"> [grid_operator_item_dynamic_page] </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div class=\"row\">\r\n            <div class=\"col-12\">\r\n                <p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">4. Opzegboete voor tussentijdse opzegging</p>\r\n                <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">5. Opzegboete voor tussentijdse opzegging</p>\r\n              <p>Dit contract had een looptijd voor <span style=\"text-transform: lowercase;\">[contract_duration]</span>, maar is na [day_active_in_our_system] dagen opgezegd. Conform de afgesproken voorwaarden, wordt bij opzegging gedurende de vaste looptijd van het contract een opzegboete in rekening gebracht. Deze opzegboete is afhankelijk van de resterende looptijd van het contract en geldt per product ([product_type]). Voor een resterende looptijd van [remaning_days], bedraagt de opzegboete € [cancelation_fee_summary] per product. Hierbij houden we ons aan de richtlijnen van de Autoriteit Consument en Markt. </p>\r\n            </div>\r\n          </div>\r\n          <div class=\"mt-5\">\r\n            <table class=\"table table-custom [cancellation_fee_visible]\">\r\n              <thead>\r\n                <th class=\"pl-2 text-uppercase\">OPZEGBOETE VOOR CONTRACT MET RESTERENDE LOOPTIJD MEER DAN [contract_duration_title]</th>\r\n                <th class=\"pl-2 text-right\">BEDRAG</th>\r\n              </thead>\r\n              <tbody>\r\n                <tr class=\"[cancellation_fee_elk_visible]\">\r\n                  <td class=\"pl-2\"> Opzegboete stroom </td>\r\n                  <td class=\"pl-2 text-right\">€ [cancelation_fee_elk]</td>\r\n                </tr>\r\n                <tr class=\"[cancellation_fee_gas_visible]\">\r\n                  <td class=\"pl-2\"> Opzegboete gas </td>\r\n                  <td class=\"pl-2 text-right\">€ [cancelation_fee_gas]</td>\r\n                </tr>\r\n              </tbody>\r\n            </table>\r\n            <table>\r\n              <tbody>\r\n                <tr>\r\n                  <td style=\"height: 15px;\"></td>\r\n                </tr>\r\n                <tr>\r\n                  <td class=\"w-100\"></td>\r\n                  <td class=\"pl-2 text-right font-weight-bold text-nowrap t-nowrap\">\r\n                    <div class=\"border-top-bold position-relative\">\r\n                      <span class=\"pr-5\">Totaalbedrag opzegboete voor tussentijdse opzegging</span>\r\n                      <span>€ [cancelation_fee_last_page]</span>\r\n                    </div>\r\n                  </td>\r\n                </tr>\r\n              </tbody>\r\n            </table>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n      <div class=\"container text-normal\">\r\n        <div class=\"content\">\r\n          <div class=\"row\">\r\n            <div class=\"col-12\">\r\n            	<p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">5. Totaal in rekening gebrachte termijnbedragen</p>\r\n                <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">6. Totaal in rekening gebrachte termijnbedragen</p>\r\n              <p>Hier zie je een overzicht van de door ons in rekening gebrachte termijnbedragen in de afgelopen periode (incl. btw). Een negatief termijnbedrag wordt als niet in rekening gebracht beschouwd en daarom als 0 weergegeven.</p>\r\n            </div>\r\n          </div>\r\n          <div class=\"mt-5\">\r\n            <table class=\"table table-custom\">\r\n              <thead>\r\n                <th class=\"pl-2 charge-item-month-column\">MAAND</th>\r\n                <th class=\"pl-2 charge-item-invoice-number\">FACTUURNUMMER</th>\r\n                <th class=\"pl-2 text-right\" colspan=\"2\">BEDRAG</th>\r\n              </thead>\r\n              <tbody> [charged_item_by_month] </tbody>\r\n            </table>\r\n            <table>\r\n              <tbody>\r\n                <tr>\r\n                  <td style=\"height: 15px;\"></td>\r\n                </tr>\r\n                <tr>\r\n                  <td class=\"w-100\"></td>\r\n                  <td class=\"pl-2 text-right font-weight-bold text-nowrap t-nowrap\">\r\n                    <div class=\"border-top-bold position-relative\">\r\n                      <span class=\"pr-5\">Totaal in rekening gebrachte termijnbedragen</span>\r\n                      <span>[total_generated_amount]</span>\r\n                    </div>\r\n                  </td>\r\n                </tr>\r\n              </tbody>\r\n            </table>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <div style=\"page-break-before: always\"></div>\r\n\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n          <div class=\"content\">\r\n            <div class=\"mt-2\">\r\n              <p class=\"font-weight-bold\">Jouw EAN-codes</p> [elk_gas_eans]\r\n            </div>\r\n            <div class=\"mt-5\">\r\n              <p class=\"font-weight-bold\">Btw-aangifte</p>\r\n              <p class=\"mb-0\"> [reseller_name] handelt onder de leveranciersvergunning van Kikker Energie. In het geval je een btw-aangifte moet doen, dien je daarom de gegevens van Kikker Energie te gebruiken. De benodigde informatie van Kikker Energie en je netbeheerder vind je onderstaand: </p>\r\n            </div>\r\n            <div class=\"row mt-4\">\r\n              <div class=\"col-5\">\r\n                <p class=\"mb-0\"> Kikker Energie B.V. </br> Tolnasingel 12 </br> 2411PV Bodegraven </p>\r\n                <p class=\"mb-0\">KvK: 71246681</p>\r\n                <p class=\"mb-0\">Btw nr.: NL858635732B01</p>\r\n              </div>\r\n              <div class=\"col-5\">\r\n                <p class=\"mb-0\"> [grid_operator_name] </br> [grid_operator_house_nr] </br> [grid_operator_postcode] </p>\r\n                <p class=\"mb-0\">KvK: [grid_operator_kvk]</p>\r\n                <p class=\"mb-0\">Btw nr.: [grid_operator_btw]</p>\r\n              </div>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n  </body>\r\n</html>', NULL, NULL, 'nl', 'ke-pdf', NULL, '2023-11-27 09:07:13.152323', NULL);
INSERT IGNORE INTO `templates_reseller` (`Id`, `reseller_id`, `template_name`, `html_content`, `header_id`, `footer_id`, `language_code`, `CreatedBy`, `ModifiedBy`, `CreatedAt`, `ModifiedAt`) VALUES (266, 197, 'FINALBILL_TEMPLATE_ONE_YEAR', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n\r\n<head>\r\n    <title>Billing | Kikker</title>\r\n    <meta charset=\"utf-8\">\r\n    <link rel=\"icon\" href=\"asset/kikker-icon.ico\" />\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\r\n    <link rel=\"stylesheet\" href=\"https://storage.googleapis.com/kikkerprodbucket/static-files/pdf-css/site.css\">\r\n    <link rel=\"stylesheet\" href=\"https://storage.googleapis.com/kikkerprodbucket/static-files/pdf-css/final_bill.css\">\r\n</head>\r\n<body>\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div class=\"row header mr-0 ml-0\">\r\n                    <div style=\"width: 33%;\">\r\n                    </div>\r\n                    <div class=\"[hide-header-invoice-info] header-invoice-info\">\r\n                        <div class=\"d-flex justify-content-end\">\r\n                            <div class=\"space-span d-inline-block\" style=\"padding-top: 0\">\r\n                                <div class=\"mb-0 d-flex\">\r\n                                    <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\">Klantnummer:</p>\r\n                                    <p class=\"mb-0\">[client_number]</p>\r\n                                </div>\r\n                                <div class=\"mb-0 d-flex\">\r\n                                    <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\"\r\n                                        >Contractnummer:\r\n                                    </p>\r\n                                    <p class=\"mb-0\">[contract_number]</p>\r\n                                </div>\r\n                                <div class=\"mb-0 d-flex [hidden_contract_reference]\" style=\"flex-flow: row;\">\r\n                                    <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\">Contractreferentie: </p>\r\n                                    <p class=\"mb-0\">[contract_reference]</p>\r\n                                </div>\r\n                                <div class=\"mb-0 d-flex\">\r\n                                    <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\"\r\n                                        >Factuurnummer:\r\n                                    </p>\r\n                                    <p class=\"mb-0\">[invoice_number]</p>\r\n                                </div>\r\n                                <div class=\"mb-0 d-flex [company_name_visible]\" style=\"flex-flow: row;\">\r\n                                    <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\">Bedrijfsnaam: </p>\r\n                                    <p class=\"mb-0\">[company_name]</p>\r\n                                </div>\r\n                                <div class=\"mb-0 d-flex\" style=\"flex-flow: row;\">\r\n                                    <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\">Energie intermediair: </p>\r\n                                    <p class=\"mb-0\">[header_reseller_name]</p>\r\n                                </div>\r\n                                <div class=\"mb-0 d-flex\">\r\n                                    <p class=\"text-right vertical-align-top pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\"\r\n                                        >Leveringsadres:</p\r\n                                    >\r\n                                    <p class=\"mb-0\" class=\"d-inline-block\"\r\n                                        >[delivery_address_street] [delivery_address_houseNr] [delivery_address_zipcode]<br><span class=\"text-capitalize\">[delivery_address_city]</span></p\r\n                                    >\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n                <div class=\"row\">\r\n                    <div class=\"col-12\">\r\n                        <p class=\"mb-5\">\r\n                            <span class=\"float-right\">[date_generate_PDF]</span>\r\n                        </p>\r\n                        <p class=\"mb-4\">Beste [customer_first_name],</p>\r\n                        <p class=\"mb-4 [final_bill_visible]\">Dit is je eindafrekening over de verbruiksperiode van\r\n                            [final_bill_start_date] tot [final_bill_end_date] voor je leveringsadres\r\n                            [delivery_address_street] [delivery_address_houseNr] te <span\r\n                                class=\"text-capitalize\">[delivery_address_city]</span>. Je ontvangt deze afrekening\r\n                            omdat je contract met [reseller_name] eindigt. In deze eindafrekening berekenen we de kosten\r\n                            tot de einddatum van je contract. Indien je onlangs een nieuw [reseller_name]-contract hebt\r\n                            afgesloten, ontvang je hier apart bericht van. </p>\r\n                        <p class=\"mb-4 [yearly_bill_visible]\">Dit is je jaarafrekening over de verbruiksperiode van\r\n                            [final_bill_start_date] tot [final_bill_end_date] voor je leveringsadres\r\n                            [delivery_address_street] [delivery_address_houseNr] te <span\r\n                                class=\"text-capitalize\">[delivery_address_city]</span>. In deze jaarafrekening vind je\r\n                            een overzicht van je energieverbruik in het afgelopen jaar en wat je hiervoor hebt betaald.\r\n                        </p>\r\n                    </div>\r\n                </div>\r\n                [FINALBILL_TEMPLATE_UNPAID_AMOUNT_INVOICE_ITEM]\r\n                [FINALBILL_TEMPLATE_PAID_AMOUNT_INVOICE_ITEM]\r\n                <div>\r\n                    <p class=\"mb-1 font-weight-bold [yearly_bill_visible] [new_monthly_amount_visible]\"> Je nieuwe\r\n                        termijnbedrag </span>\r\n                    </p>\r\n                    <p class=\"mb-4 [yearly_bill_visible] [new_monthly_amount_visible]\"> Op basis van je verbruik in de\r\n                        afgelopen 12 maanden, hebben we een nieuw termijnbedrag voor je uitgerekend. We passen het\r\n                        termijnbedrag automatisch voor je aan. Ben je het niet eens met je nieuwe termijnbedrag? Dan kun\r\n                        je dit gemakkelijk aanpassen in onze mobiele app. </p>\r\n                </div>\r\n                <div class=\"row monthly-amount-block [yearly_bill_visible] [new_monthly_amount_visible] mt-4\"\r\n                    style=\"background-image: url(\'data:image/png;base64,\');background-size: 100%; background-repeat: no-repeat; background-position: center center;\">\r\n                    <div class=\"col-6\">\r\n                        <span> Oude termijnbedrag </span>\r\n                        <span class=\"float-right\"> € [current_monthly_amount] </span>\r\n                    </div>\r\n                    <div class=\"col-6 pl-5 font-weight-bold\">\r\n                        <span> Nieuwe termijnbedrag </span>\r\n                        <span class=\"float-right\"> € [new_monthly_amount] </span>\r\n                    </div>\r\n                </div>\r\n                <div class=\"mt-4\">\r\n                    <p class=\"font-weight-bold mb-1\">Vragen?</p>\r\n                    <p class=\"mb-3\">Je kunt altijd contact met ons opnemen via [reseller_email] of bellen naar\r\n                        [reseller_phone]</p>\r\n                    <p class=\"mb-3\">Met vriendelijke groet, </p>\r\n                    <p class=\"mb-0\">[reseller_name]</p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n            <div>\r\n                <p>Meer informatie over je verbruik of de precieze berekening van je <span class=\"[final_bill_visible]\">eindafrekening</span> <span class=\"[yearly_bill_visible]\">jaarafrekening</span> vind je op de volgende pagina’s.</p>\r\n                <div class=\"mb-1 font-weight-bold\">Samenvatting van je <span\r\n                        class=\"[final_bill_visible]\">eindafrekening</span>\r\n                    <span class=\"[yearly_bill_visible]\">jaarafrekening</span>\r\n                </div>\r\n                <div class=\"[hide_text_summary]\">[text_summary]</div>\r\n                <div class=\"mt-5\">\r\n                    <table class=\"table table-first\">\r\n                        <tbody>\r\n                            <tr>\r\n                                <td class=\"pl-2\"> 1. Leveringskosten van [product_type] </td>\r\n                                <td class=\"pl-2 text-right\">[total_delivery_amount]</td>\r\n                            </tr>\r\n                            <tr class=\"[show_price_cap_billing]\">\r\n                                <td class=\"pl-2\"> 2. Tegemoetkoming uit het prijsplafond</td>\r\n                                <td class=\"pl-2 text-right\">[total_price_cap]</td>\r\n                              </tr>\r\n                            <tr>\r\n                                <td class=\"pl-2 [hide_price_cap_billing]\"> 2. Overheidsheffingen op [product_type], dit dragen we af aan de overheid </td>\r\n                                <td class=\"pl-2 [show_price_cap_billing]\"> 3. Overheidsheffingen op [product_type], dit dragen we af aan de overheid </td>\r\n                                <td class=\"pl-2 text-right\">[total_tax_amount]</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <td class=\"pl-2 [hide_price_cap_billing]\"> 3. Netbeheerkosten op [product_type], dit dragen we af aan je\r\n                                    netbeheerder</td>\r\n                                <td class=\"pl-2 [show_price_cap_billing]\"> 4. Netbeheerkosten op [product_type], dit dragen we af aan je\r\n                                    netbeheerder </td>\r\n                                <td class=\"pl-2 text-right\">[total_grid_operator_amount]</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <td class=\"pl-2 font-weight-bold\"></td>\r\n                                <td class=\"pl-2 text-right  font-weight-bold\">[total_real_amount_incl_cancel_fee]</td>\r\n                            </tr>\r\n                        </tbody>\r\n                    </table>\r\n                </div>\r\n                <div class=\"mt-5\">\r\n                    <table class=\"table table-first\">\r\n                        <tbody>\r\n                            <tr>\r\n                                <td class=\"pl-2 [hide_price_cap_billing]\"> 4. In rekening gebrachte termijnbedragen </td>\r\n                                <td class=\"pl-2 [show_price_cap_billing]\"> 5. In rekening gebrachte termijnbedragen </td>\r\n                                <td class=\"pl-2 text-right\">[total_generated_amount_negative]</td>\r\n                            </tr>\r\n                            <tr class=\"[total_unpaid_amount_class]\">\r\n                                <td class=\"pl-4 font-italic\"> Openstaande termijnbedragen </td>\r\n                                <td class=\"pl-2 text-right\">[total_unpaid_amount]</td>\r\n                            </tr>\r\n                            <tr class=\"[total_collection_cost_amount_class]\">\r\n                                <td class=\"pl-4 font-italic\"> Openstaande incassokosten </td>\r\n                                <td class=\"pl-2 text-right\">[total_collection_cost_amount]</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <td class=\"pl-2 font-weight-bold\"></td>\r\n                                <td class=\"pl-2 text-right  font-weight-bold\">[total_real_generated_amount_negative]\r\n                                </td>\r\n                            </tr>\r\n                        </tbody>\r\n                    </table>\r\n                    <table>\r\n                        <tbody>\r\n                            <tr>\r\n                                <td class=\"w-100\"></td>\r\n                                <td class=\"pl-2 text-right font-weight-bold text-nowrap t-nowrap\">\r\n                                    <div class=\"border-top-bold position-relative\">\r\n                                        <span class=\"pr-5\">[is_receive]</span>\r\n                                        <span>€ [difference_amount]</span>\r\n                                    </div>\r\n                                </td>\r\n                            </tr>\r\n                        </tbody>\r\n                    </table>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div class=\"[usage_only_gas_elk_visible]\">\r\n                    <p class=\"mb-1 font-weight-bold\"> Berekening van je verbruik </p>\r\n                           <p class=\"mb-5\">\r\n            Je hebt een contract waarbij je dynamische tarieven betaalt [dynamic_based_on_type_of_product_in_contract]. Hierdoor berekenen we jouw verbruik door [dynamic_based_on_type_of_product_in_contract] het netto verbruik (verbruik minus eventuele teruglevering) bij elkaar op te tellen. In onderstaand overzicht zie je voor de volledigheid ook een overzicht van jouw meterstanden (en het daaruit resulterende verbruik) per periode.\r\n          </p>\r\n                </div>\r\n                <div class=\"[usage_only_gas_elk_visible]\"> [usage_item_by_ean] </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    <div class=\"[usage_only_gas_elk_visible]\" style=\"page-break-before: always\"></div>\r\n    <div class=\"page [usage_both_gas_elk_visible]\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div>\r\n                    <p class=\"mb-1 font-weight-bold\"> Berekening van je verbruik </p>\r\n                       <p class=\"mb-5\">\r\n            Je hebt een contract waarbij je dynamische tarieven betaalt [dynamic_based_on_type_of_product_in_contract]. Hierdoor berekenen we jouw verbruik door [dynamic_based_on_type_of_product_in_contract] het netto verbruik (verbruik minus eventuele teruglevering) bij elkaar op te tellen. In onderstaand overzicht zie je voor de volledigheid ook een overzicht van jouw meterstanden (en het daaruit resulterende verbruik) per periode.\r\n          </p>\r\n                </div>\r\n                <div> [usage_item_by_ean] </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    <div class=\"[usage_both_gas_elk_visible]\" style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div>\r\n                    <p class=\"mb-4\">Op de volgende pagina’s vind je een nadere specificatie van de kosten die\r\n                        weergegeven zijn op pagina 2.</p>\r\n                    [return_tariff_section]\r\n                    <p class=\"mb-1 font-weight-bold\">1. Leveringskosten voor [product_type]</p>\r\n                     <p class=\"mb-1\">\r\n            Met jouw contract betaal je dynamische tarieven. Omdat wij niet alle tarieven per uur/dag op de <span class=\"[final_bill_visible]\">eindafrekening</span> <span class=\"[yearly_bill_visible]\">jaarafrekening</span> kunnen tonen, berekenen wij eerst jouw gewogen gemiddelde tarief per maand door jouw verbruik per uur/dag te vermenigvuldigen met de uur/dagprijs en dit vervolgens te delen door jouw verbruik in de maand. Zo kunnen we een helder tarief tonen op de <span class=\"[final_bill_visible]\">eindafrekening</span> <span class=\"[yearly_bill_visible]\">jaarafrekening</span>, maar betaal je alsnog gewoon de uur/dagprijs.\r\n          </p>\r\n          <p class=\"mb-5\">\r\n            Een specificatie van hoe wij jouw gewogen gemiddelde tarief berekenen vind je terug in de Mijn [reseller_name] Online.\r\n          </p>\r\n                </div>\r\n                <div class=\"table_fixed_delivery\"> [fixed_delivery_item_dynamic_page] </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n\r\n    [price_cap_section_template]\r\n\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div class=\"row\">\r\n                    <div class=\"col-12\">\r\n                        <p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">2. Overheidsheffingen op [product_type]</p>\r\n                        <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">3. Overheidsheffingen op [product_type]</p>\r\n                        <p style=\"display: [show_new_ode_tax_description]\">Naast de kosten voor het verbruik van\r\n                            [product_type], moet je ook belastingen betalen aan de overheid. Ook deze zijn afhankelijk\r\n                            van je verbruik. Onderstaande kosten dragen wij direct af aan de overheid. Omdat de\r\n                            heffingen jaarlijks (per 1 januari) veranderen zie je onderstaand mogelijk twee\r\n                            berekeningen: een voor de periode vóór en een voor de periode ná 1 januari.</p>\r\n                    </div>\r\n                </div>\r\n                <div class=\"mt-3\"> [tax_item_dynamic_page] </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div class=\"row\">\r\n                    <div class=\"col-12\">\r\n                        <p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">3. Netbeheerkosten voor [product_type]</p>\r\n                        <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">4. Netbeheerkosten voor [product_type]</p>\r\n                        <p class=\"mb-3\">Om van [product_type] gebruik te kunnen maken, dien je aangesloten te zijn op\r\n                            het openbare [product_type]netwerk van je netbeheerder. Hiervoor betaal je een vaste\r\n                            vergoeding die afhankelijk is van je aansluiting. Wij dragen deze vervolgens weer af aan je\r\n                            netbeheerder. Ook hier geldt dat de tarieven jaarlijks per 1 januari wijzigen. Om deze reden\r\n                            zie je onderstaand mogelijk weer twee berekeningen: voor de periode vóór en de periode ná 1\r\n                            januari. </p>\r\n                        <p> Je netbeheerder: <strong>[grid_operator_name]</strong>\r\n                        </p>\r\n                    </div>\r\n                </div>\r\n                <div class=\"mt-3 custom-table table_grid_operator\"> [grid_operator_item_dynamic_page] </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div class=\"row\">\r\n                    <div class=\"col-12\">\r\n                    	<p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">4. Totaal in rekening gebrachte termijnbedragen</p>\r\n                        <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">5. Totaal in rekening gebrachte termijnbedragen</p>\r\n                        <p class=\"mb-1\">Hier zie je een overzicht van de door ons in rekening gebrachte termijnbedragen in de afgelopen periode (incl. btw). Een negatief termijnbedrag wordt als niet in rekening gebracht beschouwd en daarom als 0 weergegeven.</p>\r\n                    </div>\r\n                </div>\r\n                <div class=\"mt-5\">\r\n                    <table class=\"table table-custom\">\r\n                        <thead>\r\n                            <th class=\"pl-2 charge-item-month-column\">MAAND</th>\r\n                            <th class=\"pl-2 charge-item-invoice-number\">FACTUURNUMMER</th>\r\n                            <th class=\"pl-2 text-right\" colspan=\"2\">BEDRAG</th>\r\n                        </thead>\r\n                        <tbody> [charged_item_by_month] </tbody>\r\n                    </table>\r\n                    <table>\r\n                        <tbody>\r\n                            <tr>\r\n                                <td style=\"height: 15px;\"></td>\r\n                            </tr>\r\n                            <tr>\r\n                                <td class=\"w-100\"></td>\r\n                                <td class=\"pl-2 text-right font-weight-bold text-nowrap t-nowrap\">\r\n                                    <div class=\"border-top-bold position-relative\">\r\n                                        <span class=\"pr-5\">Totaal in rekening gebrachte termijnbedragen</span>\r\n                                        <span>[total_generated_amount]</span>\r\n                                    </div>\r\n                                </td>\r\n                            </tr>\r\n                        </tbody>\r\n                    </table>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div>\r\n                    <p class=\"font-weight-bold\">Jouw EAN-codes</p> [elk_gas_eans]\r\n                </div>\r\n                <div class=\"mt-5\">\r\n                    <p class=\"font-weight-bold\">Btw-aangifte</p>\r\n                    <p class=\"mb-0\">\r\n                        [reseller_name] handelt onder de leveranciersvergunning van Kikker Energie. In het geval je een\r\n                        btw-aangifte moet doen, dien je daarom de gegevens van Kikker Energie te gebruiken. De benodigde\r\n                        informatie van Kikker Energie en je netbeheerder vind je onderstaand:\r\n                    </p>\r\n                </div>\r\n                <div class=\"row mt-4\">\r\n                    <div class=\"col-5\">\r\n                        <p class=\"mb-0\">\r\n                            Kikker Energie B.V.</br>\r\n                            Tolnasingel 12 </br> 2411PV Bodegraven\r\n                        </p>\r\n                        <p class=\"mb-0\">KvK: 71246681</p>\r\n                        <p class=\"mb-0\">Btw nr.: NL858635732B01</p>\r\n                    </div>\r\n                    <div class=\"col-5\">\r\n                        <p class=\"mb-0\"> [grid_operator_name] </br> [grid_operator_house_nr] </br>\r\n                            [grid_operator_postcode] </p>\r\n                        <p class=\"mb-0\">KvK: [grid_operator_kvk]</p>\r\n                        <p class=\"mb-0\">Btw nr.: [grid_operator_btw]</p>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</body>\r\n\r\n</html>\r\n', NULL, NULL, 'nl', 'ke-pdf', NULL, '2024-06-13 10:55:49.593649', NULL);
INSERT IGNORE INTO `templates_reseller` (`Id`, `reseller_id`, `template_name`, `html_content`, `header_id`, `footer_id`, `language_code`, `CreatedBy`, `ModifiedBy`, `CreatedAt`, `ModifiedAt`) VALUES (267, 197, 'FINALBILL_TEMPLATE_CANCELATION_FEE_ONE_YEAR', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n\r\n<head>\r\n    <title>Billing | Kikker</title>\r\n    <meta charset=\"utf-8\">\r\n    <link rel=\"icon\" href=\"asset/kikker-icon.ico\" />\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\r\n    <link rel=\"stylesheet\" href=\"https://storage.googleapis.com/kikkerprodbucket/static-files/pdf-css/site.css\">\r\n    <link rel=\"stylesheet\" href=\"https://storage.googleapis.com/kikkerprodbucket/static-files/pdf-css/final_bill.css\">\r\n</head>\r\n<body>\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div class=\"row header mr-0 ml-0\">\r\n                    <div style=\"width: 33%;\">\r\n                    </div>\r\n                    <div class=\"[hide-header-invoice-info] header-invoice-info\">\r\n                        <div class=\"d-flex justify-content-end\">\r\n                            <div class=\"space-span d-inline-block\" style=\"padding-top: 0\">\r\n                                <div class=\"mb-0 d-flex\">\r\n                                    <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\">Klantnummer:</p>\r\n                                    <p class=\"mb-0\">[client_number]</p>\r\n                                </div>\r\n                                <div class=\"mb-0 d-flex\">\r\n                                    <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\"\r\n                                        >Contractnummer:\r\n                                    </p>\r\n                                    <p class=\"mb-0\">[contract_number]</p>\r\n                                </div>\r\n                                <div class=\"mb-0 d-flex [hidden_contract_reference]\" style=\"flex-flow: row;\">\r\n                                    <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\">Contractreferentie: </p>\r\n                                    <p class=\"mb-0\">[contract_reference]</p>\r\n                                </div>\r\n                                <div class=\"mb-0 d-flex\">\r\n                                    <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\"\r\n                                        >Factuurnummer:\r\n                                    </p>\r\n                                    <p class=\"mb-0\">[invoice_number]</p>\r\n                                </div>\r\n                                <div class=\"mb-0 d-flex [company_name_visible]\" style=\"flex-flow: row;\">\r\n                                    <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\">Bedrijfsnaam: </p>\r\n                                    <p class=\"mb-0\">[company_name]</p>\r\n                                </div>\r\n                                <div class=\"mb-0 d-flex\" style=\"flex-flow: row;\">\r\n                                    <p class=\"text-right pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\">Energie intermediair: </p>\r\n                                    <p class=\"mb-0\">[header_reseller_name]</p>\r\n                                </div>\r\n                                <div class=\"mb-0 d-flex\">\r\n                                    <p class=\"text-right vertical-align-top pr-3 mb-0\" style=\"min-width: 200px;width: 200px;\"\r\n                                        >Leveringsadres:</p\r\n                                    >\r\n                                    <p class=\"mb-0\" class=\"d-inline-block\"\r\n                                        >[delivery_address_street] [delivery_address_houseNr] [delivery_address_zipcode]<br><span class=\"text-capitalize\">[delivery_address_city]</span></p\r\n                                    >\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n                <div class=\"row\">\r\n                    <div class=\"col-12\">\r\n                        <p class=\"mb-0\">\r\n                            <span class=\"float-right\">[date_generate_PDF]</span>\r\n                        </p>\r\n                        <p class=\"mt-5 mb-4\">Beste [customer_first_name],</p>\r\n                        <p class=\"mb-4 [final_bill_visible]\">Dit is je eindafrekening over de verbruiksperiode van\r\n                            [final_bill_start_date] tot [final_bill_end_date] voor je leveringsadres\r\n                            [delivery_address_street] [delivery_address_houseNr] te <span\r\n                                class=\"text-capitalize\">[delivery_address_city]</span>. Je ontvangt deze afrekening\r\n                            omdat je contract met [reseller_name] eindigt. In deze eindafrekening berekenen we de kosten\r\n                            tot de einddatum van je contract. Indien je onlangs een nieuw [reseller_name]-contract hebt\r\n                            afgesloten, ontvang je hier apart bericht van. </p>\r\n                        <p class=\"mb-4 [yearly_bill_visible]\">Dit is je jaarafrekening over de verbruiksperiode van\r\n                            [final_bill_start_date] tot [final_bill_end_date] voor je leveringsadres\r\n                            [delivery_address_street] te <span class=\"text-capitalize\">[delivery_address_city]</span>.\r\n                            In deze jaarafrekening vind je een overzicht van je energieverbruik in het afgelopen jaar en\r\n                            wat je hiervoor hebt betaald. </p>\r\n                    </div>\r\n                </div>\r\n                [FINALBILL_TEMPLATE_UNPAID_AMOUNT_INVOICE_ITEM]\r\n                [FINALBILL_TEMPLATE_PAID_AMOUNT_INVOICE_ITEM]\r\n                <div>\r\n                    <p class=\"mb-1 font-weight-bold [yearly_bill_visible] [new_monthly_amount_visible]\"> Je nieuwe\r\n                        termijnbedrag </span>\r\n                    </p>\r\n                    <p class=\"mb-4 [yearly_bill_visible] [new_monthly_amount_visible]\"> Op basis van je verbruik in de\r\n                        afgelopen 12 maanden, hebben we een nieuw termijnbedrag voor je uitgerekend. We passen het\r\n                        termijnbedrag automatisch voor je aan. Ben je het niet eens met je nieuwe termijnbedrag? Dan kun\r\n                        je dit gemakkelijk aanpassen in onze mobiele app. </p>\r\n                </div>\r\n                <div class=\"row monthly-amount-block [yearly_bill_visible] [new_monthly_amount_visible] mt-4\"\r\n                    style=\"background-image: url(\'data:image/png;base64,\');background-size: 100%; background-repeat: no-repeat; background-position: center center;\">\r\n                    <div class=\"col-6\">\r\n                        <span> Oude termijnbedrag </span>\r\n                        <span class=\"float-right\"> € [current_monthly_amount] </span>\r\n                    </div>\r\n                    <div class=\"col-6 pl-5 font-weight-bold\">\r\n                        <span> Nieuwe termijnbedrag </span>\r\n                        <span class=\"float-right\"> € [new_monthly_amount] </span>\r\n                    </div>\r\n                </div>\r\n                <div class=\"mt-4\">\r\n                    <p class=\"font-weight-bold mb-1\">Vragen?</p>\r\n                    <p class=\"mb-3\">Je kunt altijd contact met ons opnemen via [reseller_email] of bellen naar\r\n                        [reseller_phone].</p>\r\n                    <p class=\"mb-3\">Met vriendelijke groet, </p>\r\n                    <p class=\"mb-0\">[reseller_name]</p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div class=\"row\">\r\n                    <div class=\"col-12\">\r\n                        <p>Meer informatie over je verbruik of de precieze berekening van je <span class=\"[final_bill_visible]\">eindafrekening</span> <span class=\"[yearly_bill_visible]\">jaarafrekening</span> vind je op de volgende pagina’s.</p>\r\n                        <p class=\"mb-1 font-weight-bold\">Samenvatting van je <span\r\n                                class=\"[final_bill_visible]\">eindafrekening</span>\r\n                            <span class=\"[yearly_bill_visible]\">jaarafrekening</span>\r\n                        </p>\r\n                    </div>\r\n                </div>\r\n                <div class=\"[hide_text_summary]\">[text_summary]</div>\r\n                <div class=\"mt-5 table-first\">\r\n                    <table class=\"table\">\r\n                        <tbody>\r\n                            <tr>\r\n                                <td class=\"pl-2\"> 1. Leveringskosten van [product_type] </td>\r\n                                <td class=\"pl-2 text-right\">[total_delivery_amount]</td>\r\n                            </tr>\r\n                            <tr class=\"[show_price_cap_billing]\">\r\n                                <td class=\"pl-2\"> 2. Tegemoetkoming uit het prijsplafond</td>\r\n                                <td class=\"pl-2 text-right\">[total_price_cap]</td>\r\n                              </tr>\r\n                            <tr>\r\n                                <td class=\"pl-2 [hide_price_cap_billing]\">2. Overheidsheffingen op [product_type], dit dragen we af aan de overheid</td>\r\n                                <td class=\"pl-2 [show_price_cap_billing]\">3. Overheidsheffingen op [product_type], dit dragen we af aan de overheid</td>\r\n                                <td class=\"pl-2 text-right\">[total_tax_amount]</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <td class=\"pl-2 [hide_price_cap_billing]\">3. Netbeheerkosten op [product_type], dit dragen we af aan je netbeheerder</td>\r\n                                <td class=\"pl-2 [show_price_cap_billing]\">4. Netbeheerkosten op [product_type], dit dragen we af aan je netbeheerder</td>\r\n                                <td class=\"pl-2 text-right\">[total_grid_operator_amount]</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <td class=\"pl-2 [hide_price_cap_billing]\">4. Opzegboete voor tussentijdse opzegging</td>\r\n                                <td class=\"pl-2 [show_price_cap_billing]\">5. Opzegboete voor tussentijdse opzegging</td>\r\n                                <td class=\"pl-2 text-right\">[cancelation_fee]</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <td class=\"pl-2 font-weight-bold\"></td>\r\n                                <td class=\"pl-2 text-right  font-weight-bold\">[total_real_amount_incl_cancel_fee]</td>\r\n                            </tr>\r\n                        </tbody>\r\n                    </table>\r\n                </div>\r\n                <div class=\"mt-4 table-first\">\r\n                    <table class=\"table\">\r\n                        <tbody>\r\n                            <tr>\r\n                                <td class=\"pl-2 [hide_price_cap_billing]\">5. In rekening gebrachte termijnbedragen </td>\r\n                                <td class=\"pl-2 [show_price_cap_billing]\">6. In rekening gebrachte termijnbedragen </td>\r\n                                <td class=\"pl-2 text-right\">[total_generated_amount_negative]</td>\r\n                            </tr>\r\n                            <tr class=\"[total_unpaid_amount_class]\">\r\n                                <td class=\"pl-4 font-italic\"> Openstaande termijnbedragen </td>\r\n                                <td class=\"pl-2 text-right\">[total_unpaid_amount]</td>\r\n                            </tr>\r\n                            <tr class=\"[total_collection_cost_amount_class]\">\r\n                                <td class=\"pl-4 font-italic\"> Openstaande incassokosten </td>\r\n                                <td class=\"pl-2 text-right\">[total_collection_cost_amount]</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <td class=\"pl-2 font-weight-bold\"></td>\r\n                                <td class=\"pl-2 text-right  font-weight-bold\">[total_real_generated_amount_negative]\r\n                                </td>\r\n                            </tr>\r\n                        </tbody>\r\n                    </table>\r\n                    <table>\r\n                        <tbody>\r\n                            <tr>\r\n                                <td style=\"height: 15px;\"></td>\r\n                            </tr>\r\n                            <tr>\r\n                                <td class=\"w-100\"></td>\r\n                                <td class=\"pl-2 text-right font-weight-bold text-nowrap t-nowrap\">\r\n                                    <div class=\"border-top-bold position-relative\">\r\n                                        <span class=\"pr-5\">[is_receive]</span>\r\n                                        <span>€ [difference_amount]</span>\r\n                                    </div>\r\n                                </td>\r\n                            </tr>\r\n                        </tbody>\r\n                    </table>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div class=\"[usage_only_gas_elk_visible]\">\r\n                    <p class=\"mb-1 font-weight-bold\"> Berekening van je verbruik </p>\r\n                   <p class=\"mb-5\">\r\n            Je hebt een contract waarbij je dynamische tarieven betaalt [dynamic_based_on_type_of_product_in_contract]. Hierdoor berekenen we jouw verbruik door [dynamic_based_on_type_of_product_in_contract] het netto verbruik (verbruik minus eventuele teruglevering) bij elkaar op te tellen. In onderstaand overzicht zie je voor de volledigheid ook een overzicht van jouw meterstanden (en het daaruit resulterende verbruik) per periode.\r\n          </p>\r\n                </div>\r\n                <div class=\"mt-5 [usage_only_gas_elk_visible]\"> [usage_item_by_ean] </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    <div class=\"[usage_only_gas_elk_visible]\" style=\"page-break-before: always\"></div>\r\n    <div class=\"page [usage_both_gas_elk_visible]\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div>\r\n                    <p class=\"mb-1 font-weight-bold\"> Berekening van je verbruik </p>\r\n                    <p class=\"mb-5\">\r\n            Je hebt een contract waarbij je dynamische tarieven betaalt [dynamic_based_on_type_of_product_in_contract]. Hierdoor berekenen we jouw verbruik door [dynamic_based_on_type_of_product_in_contract] het netto verbruik (verbruik minus eventuele teruglevering) bij elkaar op te tellen. In onderstaand overzicht zie je voor de volledigheid ook een overzicht van jouw meterstanden (en het daaruit resulterende verbruik) per periode.\r\n          </p>\r\n                </div>\r\n                <div class=\"mt-5\"> [usage_item_by_ean] </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    <div class=\"[usage_both_gas_elk_visible]\" style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div>\r\n                    <p class=\"mb-4\">Op de volgende pagina’s vind je een nadere specificatie van de kosten die\r\n                        weergegeven zijn op pagina 2.</p>\r\n                    [return_tariff_section]\r\n                    <p class=\"mb-1 font-weight-bold\">1. Leveringskosten voor [product_type]</p>\r\n                              <p class=\"mb-1\">\r\n            Met jouw contract betaal je dynamische tarieven. Omdat wij niet alle tarieven per uur/dag op de <span class=\"[final_bill_visible]\">eindafrekening</span> <span class=\"[yearly_bill_visible]\">jaarafrekening</span> kunnen tonen, berekenen wij eerst jouw gewogen gemiddelde tarief per maand door jouw verbruik per uur/dag te vermenigvuldigen met de uur/dagprijs en dit vervolgens te delen door jouw verbruik in de maand. Zo kunnen we een helder tarief tonen op de <span class=\"[final_bill_visible]\">eindafrekening</span> <span class=\"[yearly_bill_visible]\">jaarafrekening</span>, maar betaal je alsnog gewoon de uur/dagprijs.\r\n          </p>\r\n          <p class=\"mb-5\">\r\n            Een specificatie van hoe wij jouw gewogen gemiddelde tarief berekenen vind je terug in de Mijn [reseller_name] Online.\r\n          </p>\r\n                </div>\r\n                <div class=\"table_fixed_delivery\"> [fixed_delivery_item_dynamic_page] </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n\r\n    [price_cap_section_template]\r\n\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div class=\"row\">\r\n                    <div class=\"col-12\">\r\n                        <p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">2. Overheidsheffingen op [product_type]</p>\r\n                        <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">3. Overheidsheffingen op [product_type]</p>\r\n                        <p style=\"display: [show_new_ode_tax_description]\">Naast de kosten voor het verbruik van\r\n                            [product_type], moet je ook belastingen betalen aan de overheid. Ook deze zijn afhankelijk\r\n                            van je verbruik. Onderstaande kosten dragen wij direct af aan de overheid. Omdat de\r\n                            heffingen jaarlijks (per 1 januari) veranderen zie je onderstaand mogelijk twee\r\n                            berekeningen: een voor de periode vóór en een voor de periode ná 1 januari.</p>\r\n                    </div>\r\n                </div>\r\n                <div class=\"mt-3\"> [tax_item_dynamic_page] </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div class=\"row\">\r\n                    <div class=\"col-12\">\r\n                        <p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">3. Netbeheerkosten voor [product_type]</p>\r\n                        <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">4. Netbeheerkosten voor [product_type]</p>\r\n                        <p class=\"mb-3\">Om van [product_type] gebruik te kunnen maken, dien je aangesloten te zijn op\r\n                            het openbare [product_type]netwerk van je netbeheerder. Hiervoor betaal je een vaste\r\n                            vergoeding die afhankelijk is van je aansluiting. Wij dragen deze vervolgens weer af aan je\r\n                            netbeheerder. Ook hier geldt dat de tarieven jaarlijks per 1 januari wijzigen. Om deze reden\r\n                            zie je onderstaand mogelijk weer twee berekeningen: voor de periode vóór en de periode ná 1\r\n                            januari. </p>\r\n                        <p> Je netbeheerder: <strong>[grid_operator_name]</strong>\r\n                        </p>\r\n                    </div>\r\n                </div>\r\n                <div class=\"mt-3 custom-table table_grid_operator\"> [grid_operator_item_dynamic_page] </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    <div style=\"page-break-before: always\"></div>\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div class=\"row\">\r\n                    <div class=\"col-12\">\r\n                        <p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">4. Opzegboete voor tussentijdse opzegging</p>\r\n                        <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">5. Opzegboete voor tussentijdse opzegging</p>\r\n                        <p>Dit contract had een looptijd voor <span\r\n                                style=\"text-transform: lowercase;\">[contract_duration]</span>, maar is na\r\n                            [day_active_in_our_system] dagen opgezegd. Conform de afgesproken voorwaarden, wordt bij\r\n                            opzegging gedurende de vaste looptijd van het contract een opzegboete in rekening gebracht.\r\n                            Deze opzegboete is afhankelijk van de resterende looptijd van het contract en geldt per\r\n                            product ([product_type]). Voor een resterende looptijd van [remaning_days], bedraagt de\r\n                            opzegboete € [cancelation_fee_summary] per product. Hierbij houden we ons aan de richtlijnen\r\n                            van de Autoriteit Consument en Markt. </p>\r\n                    </div>\r\n                </div>\r\n                <div class=\"mt-5\">\r\n                    <table class=\"table table-custom [cancellation_fee_visible]\">\r\n                        <thead>\r\n                            <th class=\"pl-2 text-uppercase\">OPZEGBOETE VOOR CONTRACT MET RESTERENDE LOOPTIJD MEER DAN\r\n                                [contract_duration_title]</th>\r\n                            <th class=\"pl-2 text-right\">BEDRAG</th>\r\n                        </thead>\r\n                        <tbody>\r\n                            <tr class=\"[cancellation_fee_elk_visible]\">\r\n                                <td class=\"pl-2\"> Opzegboete stroom </td>\r\n                                <td class=\"pl-2 text-right\">€ [cancelation_fee_elk]</td>\r\n                            </tr>\r\n                            <tr class=\"[cancellation_fee_gas_visible]\">\r\n                                <td class=\"pl-2\"> Opzegboete gas </td>\r\n                                <td class=\"pl-2 text-right\">€ [cancelation_fee_gas]</td>\r\n                            </tr>\r\n                        </tbody>\r\n                    </table>\r\n                    <table>\r\n                        <tbody>\r\n                            <tr>\r\n                                <td style=\"height: 15px;\"></td>\r\n                            </tr>\r\n                            <tr>\r\n                                <td class=\"w-100\"></td>\r\n                                <td class=\"pl-2 text-right font-weight-bold text-nowrap t-nowrap\">\r\n                                    <div class=\"border-top-bold position-relative\">\r\n                                        <span class=\"pr-5\">Totaalbedrag opzegboete voor tussentijdse opzegging</span>\r\n                                        <span>€ [cancelation_fee_last_page]</span>\r\n                                    </div>\r\n                                </td>\r\n                            </tr>\r\n                        </tbody>\r\n                    </table>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n\r\n    <div style=\"page-break-before: always\"></div>\r\n\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div class=\"row\">\r\n                    <div class=\"col-12\">\r\n                    	<p class=\"mb-1 font-weight-bold [hide_price_cap_billing]\">5. Totaal in rekening gebrachte termijnbedragen</p>\r\n                        <p class=\"mb-1 font-weight-bold [show_price_cap_billing]\">6. Totaal in rekening gebrachte termijnbedragen</p>\r\n                        <p>Hier zie je een overzicht van de door ons in rekening gebrachte termijnbedragen in de afgelopen periode (incl. btw). Een negatief termijnbedrag wordt als niet in rekening gebracht beschouwd en daarom als 0 weergegeven.</p>\r\n                    </div>\r\n                </div>\r\n                <div class=\"mt-5\">\r\n                    <table class=\"table table-custom\">\r\n                        <thead>\r\n                            <th class=\"pl-2 charge-item-month-column\">MAAND</th>\r\n                            <th class=\"pl-2 charge-item-invoice-number\">FACTUURNUMME</th>\r\n                            <th class=\"pl-2 text-right\" colspan=\"2\">BEDRAG</th>\r\n                        </thead>\r\n                        <tbody> [charged_item_by_month] </tbody>\r\n                    </table>\r\n                    <table>\r\n                        <tbody>\r\n                            <tr>\r\n                                <td style=\"height: 15px;\"></td>\r\n                            </tr>\r\n                            <tr>\r\n                                <td class=\"w-100\"></td>\r\n                                <td class=\"pl-2 text-right font-weight-bold text-nowrap t-nowrap\">\r\n                                    <div class=\"border-top-bold position-relative\">\r\n                                        <span class=\"pr-5\">Totaal in rekening gebrachte termijnbedragen</span>\r\n                                        <span>[total_generated_amount]</span>\r\n                                    </div>\r\n                                </td>\r\n                            </tr>\r\n                        </tbody>\r\n                    </table>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n\r\n    <div style=\"page-break-before: always\"></div>\r\n\r\n    <div class=\"page\">\r\n        <div class=\"container text-normal\">\r\n            <div class=\"content\">\r\n                <div class=\"space-span mt-2\">\r\n                    <p class=\"font-weight-bold\">Jouw EAN-codes</p> [elk_gas_eans]\r\n                </div>\r\n                <div class=\"mt-5\">\r\n                    <p class=\"font-weight-bold\">Btw-aangifte</p>\r\n                    <p class=\"mb-0\"> [reseller_name] handelt onder de leveranciersvergunning van Kikker Energie. In het\r\n                        geval je een btw-aangifte moet doen, dien je daarom de gegevens van Kikker Energie te gebruiken.\r\n                        De benodigde informatie van Kikker Energie en je netbeheerder vind je onderstaand: </p>\r\n                </div>\r\n                <div class=\"row mt-4\">\r\n                    <div class=\"col-5\">\r\n                        <p class=\"mb-0\">\r\n                            Kikker Energie B.V.</br>\r\n                            Tolnasingel 12 </br> 2411PV Bodegraven\r\n                        </p>\r\n                        <p class=\"mb-0\">KvK: 71246681</p>\r\n                        <p class=\"mb-0\">Btw nr.: NL858635732B01</p>\r\n                    </div>\r\n                    <div class=\"col-5\">\r\n                        <p class=\"mb-0\"> [grid_operator_name] </br> [grid_operator_house_nr] </br>\r\n                            [grid_operator_postcode] </p>\r\n                        <p class=\"mb-0\">KvK: [grid_operator_kvk]</p>\r\n                        <p class=\"mb-0\">Btw nr.: [grid_operator_btw]</p>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</body>\r\n\r\n</html>', NULL, NULL, 'nl', 'ke-pdf', NULL, '2024-06-13 10:57:17.449444', NULL);
